window.CODE_FILES = {"parametrization/db_relational_model/DB_relational_model.sql":"-- MySQL Script generated by MySQL Workbench\n-- Thu Sep 17 11:07:41 2026\n-- Model: New Model    Version: 1.0\n-- MySQL Workbench Forward Engineering\n\nSET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0;\nSET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0;\nSET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';\n\n-- -----------------------------------------------------\n-- Schema personal_management\n-- -----------------------------------------------------\n\n-- -----------------------------------------------------\n-- Schema personal_management\n-- -----------------------------------------------------\nCREATE SCHEMA IF NOT EXISTS `personal_management` DEFAULT CHARACTER SET utf8 ;\nUSE `personal_management` ;\n\n-- -----------------------------------------------------\n-- Table `personal_management`.`USUARIO`\n-- -----------------------------------------------------\nCREATE TABLE IF NOT EXISTS `personal_management`.`USUARIO` (\n  `id` INT NOT NULL AUTO_INCREMENT,\n  `primer_nombre` VARCHAR(45) NOT NULL,\n  `segundo_nombre` VARCHAR(45) NULL,\n  `primer_apellido` VARCHAR(45) NOT NULL,\n  `segundo_apellido` VARCHAR(45) NULL,\n  `fecha_nacimiento` DATETIME NOT NULL,\n  `edad` INT NOT NULL,\n  `ciudad_domicilio` VARCHAR(45) NOT NULL,\n  `estado` INT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE INDEX `id_UNIQUE` (`id` ASC) VISIBLE)\nENGINE = InnoDB;\n\n\n-- -----------------------------------------------------\n-- Table `personal_management`.`TELEFONO`\n-- -----------------------------------------------------\nCREATE TABLE IF NOT EXISTS `personal_management`.`TELEFONO` (\n  `id` INT NOT NULL AUTO_INCREMENT,\n  `numero_telefono` VARCHAR(45) NULL,\n  `tipo_telefono` VARCHAR(45) NULL,\n  `USUARIO_id` INT NOT NULL,\n  `activo` INT NULL,\n  PRIMARY KEY (`id`),\n  CONSTRAINT `fk_TELEFONO_USUARIO`\n    FOREIGN KEY (`USUARIO_id`)\n    REFERENCES `personal_management`.`USUARIO` (`id`)\n    ON DELETE NO ACTION\n    ON UPDATE NO ACTION)\nENGINE = InnoDB;\n\n\n-- -----------------------------------------------------\n-- Table `personal_management`.`RED_SOCIAL`\n-- -----------------------------------------------------\nCREATE TABLE IF NOT EXISTS `personal_management`.`RED_SOCIAL` (\n  `id` INT NOT NULL AUTO_INCREMENT,\n  `nombre` VARCHAR(45) NOT NULL,\n  `url` VARCHAR(45) NOT NULL,\n  PRIMARY KEY (`id`))\nENGINE = InnoDB;\n\n\n-- -----------------------------------------------------\n-- Table `personal_management`.`PERFIL_SOCIAL`\n-- -----------------------------------------------------\nCREATE TABLE IF NOT EXISTS `personal_management`.`PERFIL_SOCIAL` (\n  `RED_SOCIAL_id` INT NOT NULL,\n  `USUARIO_id` INT NOT NULL,\n  `url_perfil` VARCHAR(45) NULL,\n  PRIMARY KEY (`RED_SOCIAL_id`, `USUARIO_id`),\n  CONSTRAINT `fk_RED_SOCIAL_has_USUARIO_RED_SOCIAL1`\n    FOREIGN KEY (`RED_SOCIAL_id`)\n    REFERENCES `personal_management`.`RED_SOCIAL` (`id`)\n    ON DELETE NO ACTION\n    ON UPDATE NO ACTION,\n  CONSTRAINT `fk_RED_SOCIAL_has_USUARIO_USUARIO1`\n    FOREIGN KEY (`USUARIO_id`)\n    REFERENCES `personal_management`.`USUARIO` (`id`)\n    ON DELETE NO ACTION\n    ON UPDATE NO ACTION)\nENGINE = InnoDB;\n\n\nSET SQL_MODE=@OLD_SQL_MODE;\nSET FOREIGN_KEY_CHECKS=@OLD_FOREIGN_KEY_CHECKS;\nSET UNIQUE_CHECKS=@OLD_UNIQUE_CHECKS;\n","persona-api/.env":"# =====================================================================\n# .env  -  Variables de entorno de persona-api\n# ---------------------------------------------------------------------\n# ESTE ARCHIVO NUNCA SE SUBE A GIT. Esta listado en .gitignore.\n# Contiene las credenciales reales de TU maquina.\n# Para compartir la estructura con el equipo se usa .env.example\n# =====================================================================\n\n# ---------- Servidor HTTP ----------\nPUERTO=3000\nNODE_ENV=development\n\n# ---------- Base de datos MySQL ----------\nDB_HOST=localhost\nDB_PUERTO=3306\nDB_USUARIO=pm_user\nDB_CLAVE=pm_pass_2026\nDB_NOMBRE=personal_management\n\n# Numero maximo de conexiones simultaneas en el pool.\nDB_LIMITE_CONEXIONES=10\n\n# ---------- CORS ----------\n# Origenes del frontend autorizados a consumir la API, separados por coma.\nORIGENES_PERMITIDOS=http://localhost:5500,http://127.0.0.1:5500,http://localhost:3000\n","persona-api/.gitignore":"# =====================================================================\n# .gitignore  -  Archivos que git debe IGNORAR\n# ---------------------------------------------------------------------\n# Regla general: nunca se versiona lo que se puede regenerar\n# (node_modules) ni lo que es secreto (.env).\n# =====================================================================\n\n# Dependencias: se reinstalan con \"npm install\" leyendo package.json\nnode_modules/\n\n# Variables de entorno con credenciales reales\n.env\n.env.local\n.env.*.local\n\n# Logs\nlogs/\n*.log\nnpm-debug.log*\n\n# Archivos del sistema operativo\n.DS_Store\nThumbs.db\n\n# Carpetas de editores\n.vscode/\n.idea/\n\n# Cache y cobertura de pruebas\n.cache/\ncoverage/\n","persona-api/config/database.js":"/**\n * config/database.js\n * ---------------------------------------------------------------------\n * Clase Database: unico punto de acceso a MySQL en toda la aplicacion.\n *\n * CONCEPTOS QUE SE APLICAN AQUI\n *\n * 1. POOL DE CONEXIONES\n *    Abrir una conexion a MySQL es costoso (handshake, autenticacion).\n *    El pool abre un grupo de conexiones una sola vez y las presta y\n *    recoge segun la demanda. Es como una fila de cajeros en un banco:\n *    el cliente no contrata un cajero nuevo, usa uno libre.\n *\n * 2. SINGLETON\n *    Exportamos UNA instancia ya creada, no la clase. Asi, por mas\n *    archivos que hagan require() de este modulo, todos comparten el\n *    mismo pool. Node.js cachea los modulos, de modo que el codigo de\n *    abajo se ejecuta una sola vez.\n *\n * 3. CONSULTAS PARAMETRIZADAS (prepared statements)\n *    JAMAS se concatena texto en una consulta SQL:\n *\n *       MAL:  `SELECT * FROM USUARIO WHERE id = ${id}`\n *       BIEN: 'SELECT * FROM USUARIO WHERE id = ?'  +  [id]\n *\n *    En la version mala, si id vale \"1 OR 1=1\" el atacante lee toda la\n *    tabla. Eso es una INYECCION SQL. Con el signo ? el driver envia\n *    el valor por separado y MySQL lo trata siempre como dato, nunca\n *    como codigo.\n *\n * 4. ENCAPSULAMIENTO\n *    El pool es un atributo PRIVADO (#pool). Ningun service puede\n *    tocarlo directo; solo puede llamar a los metodos publicos\n *    ejecutar(), obtenerUno() y conTransaccion().\n */\n\nconst mysql = require('mysql2/promise');\nconst config = require('./env');\n\nclass Database {\n  // ---- Atributos privados (el # los hace inaccesibles desde afuera) ----\n  #pool;\n  #estaConectada;\n\n  constructor() {\n    this.#pool = null;\n    this.#estaConectada = false;\n  }\n\n  // ---------------------------- Getters ----------------------------\n\n  /** true si ya se verifico la conexion con la base de datos. */\n  get estaConectada() {\n    return this.#estaConectada;\n  }\n\n  /**\n   * Devuelve el pool, creandolo la primera vez que se necesita\n   * (patron \"lazy initialization\" o inicializacion perezosa).\n   */\n  get pool() {\n    if (this.#pool === null) {\n      this.#crearPool();\n    }\n    return this.#pool;\n  }\n\n  // ----------------------- Metodos privados ------------------------\n\n  /**\n   * Crea el pool de conexiones con la configuracion del archivo .env\n   * Metodo privado: solo se puede llamar desde dentro de la clase.\n   */\n  #crearPool() {\n    this.#pool = mysql.createPool({\n      host: config.baseDatos.host,\n      port: config.baseDatos.puerto,\n      user: config.baseDatos.usuario,\n      password: config.baseDatos.clave,\n      database: config.baseDatos.nombre,\n\n      // waitForConnections: si todas las conexiones estan ocupadas,\n      // la peticion espera en cola en vez de fallar de inmediato.\n      waitForConnections: true,\n\n      // Maximo de conexiones simultaneas.\n      connectionLimit: config.baseDatos.limiteConexiones,\n\n      // 0 = la cola de espera es ilimitada.\n      queueLimit: 0,\n\n      // Soporte de acentos y emojis.\n      charset: 'utf8mb4',\n\n      // 'local' hace que los DATETIME se interpreten en la zona horaria\n      // del servidor. Debe coincidir con lo que hace utils/fechas.js\n      timezone: 'local',\n\n      // Devuelve DECIMAL y BIGINT como texto para no perder precision.\n      decimalNumbers: false\n    });\n  }\n\n  // ------------------------ Metodos publicos -----------------------\n\n  /**\n   * Comprueba que la base de datos responda. Se llama al arrancar el\n   * servidor para fallar temprano si MySQL esta apagado.\n   *\n   * @returns {Promise<boolean>}\n   */\n  async verificarConexion() {\n    // getConnection() toma prestada una conexion del pool.\n    const conexion = await this.pool.getConnection();\n\n    try {\n      // ping() envia un paquete minimo al servidor y espera respuesta.\n      await conexion.ping();\n      this.#estaConectada = true;\n      return true;\n    } finally {\n      // El bloque finally SIEMPRE se ejecuta, con error o sin error.\n      // release() devuelve la conexion al pool. Si se olvida esta\n      // linea, el pool se agota y la aplicacion se congela.\n      conexion.release();\n    }\n  }\n\n  /**\n   * Ejecuta una consulta parametrizada y devuelve las filas.\n   *\n   * Usamos execute() y no query() porque execute() usa prepared\n   * statements del lado del servidor: MySQL compila la consulta una\n   * vez y la reutiliza, lo que da mas seguridad y mas velocidad.\n   *\n   * @param {string} sql         Consulta con marcadores ?\n   * @param {Array}  parametros  Valores que reemplazan a cada ?\n   * @returns {Promise<Array>}   Filas (SELECT) o metadatos (INSERT/UPDATE).\n   *\n   * @example\n   *   const filas = await db.ejecutar(\n   *     'SELECT * FROM USUARIO WHERE ciudad_domicilio = ?',\n   *     ['Medellin']\n   *   );\n   */\n  async ejecutar(sql, parametros = []) {\n    // mysql2 devuelve [filas, camposMetadata]; solo necesitamos filas.\n    const [filas] = await this.pool.execute(sql, parametros);\n    return filas;\n  }\n\n  /**\n   * Ejecuta una consulta y devuelve SOLO la primera fila, o null.\n   * Evita escribir `filas[0] ?? null` en cada service.\n   *\n   * @param {string} sql\n   * @param {Array} parametros\n   * @returns {Promise<object|null>}\n   */\n  async obtenerUno(sql, parametros = []) {\n    const filas = await this.ejecutar(sql, parametros);\n\n    // Array.isArray protege el caso de un INSERT, que no devuelve filas.\n    if (!Array.isArray(filas) || filas.length === 0) {\n      return null;\n    }\n\n    return filas[0];\n  }\n\n  /**\n   * Ejecuta varias operaciones dentro de una TRANSACCION.\n   *\n   * Una transaccion es un bloque \"todo o nada\". Si cualquier paso\n   * falla, se deshacen TODOS los anteriores (rollback) y la base de\n   * datos queda como estaba.\n   *\n   * Caso real de esta API: al borrar un usuario hay que borrar primero\n   * sus telefonos y sus perfiles sociales. Si el borrado del usuario\n   * falla a mitad de camino, no queremos quedarnos sin los telefonos.\n   *\n   * @param {function} trabajo  Funcion async que recibe la conexion.\n   * @returns {Promise<*>}      Lo que devuelva la funcion `trabajo`.\n   *\n   * @example\n   *   await db.conTransaccion(async (conexion) => {\n   *     await conexion.execute('DELETE FROM TELEFONO WHERE USUARIO_id = ?', [id]);\n   *     await conexion.execute('DELETE FROM USUARIO WHERE id = ?', [id]);\n   *   });\n   */\n  async conTransaccion(trabajo) {\n    const conexion = await this.pool.getConnection();\n\n    try {\n      // A partir de aqui nada se guarda de forma definitiva.\n      await conexion.beginTransaction();\n\n      // Le pasamos la conexion para que TODAS las consultas del bloque\n      // viajen por la MISMA conexion. Si usaramos el pool, cada\n      // consulta podria tomar una conexion distinta y la transaccion\n      // no cubriria nada.\n      const resultado = await trabajo(conexion);\n\n      // Si llegamos aqui no hubo errores: confirmamos los cambios.\n      await conexion.commit();\n\n      return resultado;\n    } catch (error) {\n      // Algo fallo: deshacemos todo lo hecho desde beginTransaction.\n      await conexion.rollback();\n\n      // Relanzamos el error para que lo atrape el middleware.\n      throw error;\n    } finally {\n      // Pase lo que pase, devolvemos la conexion al pool.\n      conexion.release();\n    }\n  }\n\n  /**\n   * Cierra todas las conexiones del pool.\n   * Se llama al apagar el servidor (apagado elegante o graceful shutdown).\n   */\n  async cerrar() {\n    if (this.#pool !== null) {\n      await this.#pool.end();\n      this.#pool = null;\n      this.#estaConectada = false;\n    }\n  }\n}\n\n// ---------------------------------------------------------------------\n// SINGLETON: exportamos una INSTANCIA, no la clase.\n// Node.js guarda en cache el resultado de cada require(), por eso\n// `new Database()` corre una sola vez en toda la vida del proceso.\n// ---------------------------------------------------------------------\nmodule.exports = new Database();\n","persona-api/config/env.js":"/**\n * config/env.js\n * ---------------------------------------------------------------------\n * Carga y VALIDA las variables de entorno.\n *\n * Por que un modulo dedicado?\n *\n * 1. `require('dotenv').config()` se ejecuta UNA sola vez, aqui.\n *    El resto de la aplicacion importa este modulo en lugar de leer\n *    `process.env` por todos lados.\n *\n * 2. Validamos al arrancar (fail fast). Es mejor que el servidor NO\n *    arranque por falta de DB_CLAVE, que arranque y falle con un error\n *    confuso en la primera peticion de un usuario.\n *\n * 3. Convertimos los tipos. `process.env` SIEMPRE devuelve texto:\n *    process.env.PUERTO es \"3000\" (string), no 3000 (number).\n */\n\nconst path = require('node:path');\n\n// dotenv lee el archivo .env y copia su contenido a process.env.\n// Indicamos la ruta de forma explicita para que funcione sin importar\n// desde que carpeta se ejecute \"node index.js\".\nrequire('dotenv').config({\n  path: path.resolve(__dirname, '..', '.env')\n});\n\nconst MENSAJES = require('../utils/mensajes');\n\n/**\n * Lee una variable obligatoria. Si no existe, detiene el proceso.\n *\n * @param {string} nombre\n * @returns {string}\n */\nfunction obligatoria(nombre) {\n  const valor = process.env[nombre];\n\n  if (valor === undefined || valor === null || String(valor).trim() === '') {\n    // console.error escribe en el flujo de errores (stderr).\n    console.error(`\\n[CONFIG] ${MENSAJES.SISTEMA.VARIABLE_ENTORNO_FALTANTE(nombre)}\\n`);\n\n    // process.exit(1) termina el programa con codigo de error.\n    // El 0 significa \"todo bien\"; cualquier otro numero, \"fallo\".\n    process.exit(1);\n  }\n\n  return String(valor).trim();\n}\n\n/**\n * Lee una variable opcional y devuelve un valor por defecto si falta.\n */\nfunction opcional(nombre, valorPorDefecto) {\n  const valor = process.env[nombre];\n\n  if (valor === undefined || valor === null || String(valor).trim() === '') {\n    return valorPorDefecto;\n  }\n\n  return String(valor).trim();\n}\n\n/**\n * Lee una variable y la convierte a numero entero.\n */\nfunction entera(nombre, valorPorDefecto) {\n  const texto = opcional(nombre, String(valorPorDefecto));\n  const numero = Number.parseInt(texto, 10);\n\n  // Number.isNaN detecta el caso \"abc\" -> NaN.\n  return Number.isNaN(numero) ? valorPorDefecto : numero;\n}\n\n/**\n * Lee una variable con valores separados por coma y devuelve un arreglo.\n *   \"http://a.com, http://b.com\"  ->  [\"http://a.com\", \"http://b.com\"]\n */\nfunction lista(nombre, valorPorDefecto = []) {\n  const texto = opcional(nombre, '');\n\n  if (texto === '') return valorPorDefecto;\n\n  return texto\n    .split(',')\n    .map((parte) => parte.trim())\n    .filter((parte) => parte.length > 0);\n}\n\n// ---------------------------------------------------------------------\n// Objeto de configuracion final.\n// Object.freeze lo vuelve inmutable: ningun modulo puede alterarlo\n// despues de que la aplicacion arranco.\n// ---------------------------------------------------------------------\nconst config = Object.freeze({\n  // Entorno de ejecucion: development | production | test\n  entorno: opcional('NODE_ENV', 'development'),\n\n  // Puerto donde escucha Express.\n  puerto: entera('PUERTO', 3000),\n\n  // Datos de conexion a MySQL.\n  baseDatos: Object.freeze({\n    host: opcional('DB_HOST', 'localhost'),\n    puerto: entera('DB_PUERTO', 3306),\n    usuario: obligatoria('DB_USUARIO'),\n    clave: obligatoria('DB_CLAVE'),\n    nombre: obligatoria('DB_NOMBRE'),\n    limiteConexiones: entera('DB_LIMITE_CONEXIONES', 10)\n  }),\n\n  // Origenes autorizados para CORS.\n  origenesPermitidos: lista('ORIGENES_PERMITIDOS', ['http://localhost:5500']),\n\n  // Atajos booleanos para no comparar textos por toda la aplicacion.\n  get esDesarrollo() {\n    return this.entorno === 'development';\n  },\n\n  get esProduccion() {\n    return this.entorno === 'production';\n  }\n});\n\nmodule.exports = config;\n","persona-api/config/express.js":"/**\n * config/express.js\n * ---------------------------------------------------------------------\n * Construye y configura la aplicacion Express.\n *\n * POR QUE SEPARAR ESTO DE index.js?\n * Porque asi la aplicacion se puede CREAR sin ARRANCAR el servidor.\n * Eso es lo que permite escribir pruebas automatizadas: el test\n * importa la app y le manda peticiones falsas, sin ocupar el puerto\n * 3000 ni necesitar que nadie levante nada.\n *\n *   config/express.js -> crea la app  (QUE hace la aplicacion)\n *   index.js          -> la enciende  (CUANDO y DONDE escucha)\n *\n * EL ORDEN DE LOS app.use() ES CRITICO\n * Express ejecuta los middlewares en el ORDEN EN QUE SE REGISTRAN.\n * Este archivo esta escrito de arriba hacia abajo siguiendo el viaje\n * real de una peticion:\n *\n *   1. CORS            -> permiso del navegador\n *   2. express.json()  -> convertir el cuerpo JSON en objeto\n *   3. logger          -> registrar la peticion\n *   4. rutas           -> atender la peticion\n *   5. 404             -> ninguna ruta coincidio\n *   6. errores         -> SIEMPRE el ultimo\n *\n * Si el logger estuviera antes de express.json(), no podria mostrar el\n * cuerpo porque todavia no existiria. Si el manejador de errores\n * estuviera antes de las rutas, nunca atraparia nada.\n */\n\nconst express = require('express');\nconst cors = require('cors');\n\nconst config = require('./env');\nconst rutas = require('../routes');\nconst { registrarPeticion } = require('../middleware/logger');\nconst { rutaNoEncontrada, manejadorErrores } = require('../middleware/errorHandler');\n\n/**\n * Crea la aplicacion Express completamente configurada.\n * @returns {import('express').Express}\n */\nfunction crearAplicacion() {\n  const app = express();\n\n  // -------------------------------------------------------------------\n  // 1. CONFIGURACION BASICA\n  // -------------------------------------------------------------------\n\n  // Oculta la cabecera \"X-Powered-By: Express\".\n  // Decirle al mundo que framework usas solo le ahorra trabajo a quien\n  // busca vulnerabilidades conocidas.\n  app.disable('x-powered-by');\n\n  // -------------------------------------------------------------------\n  // 2. CORS (Cross-Origin Resource Sharing)\n  // -------------------------------------------------------------------\n  //\n  // QUE PROBLEMA RESUELVE?\n  // Por seguridad, el navegador bloquea las peticiones de JavaScript\n  // hacia un ORIGEN distinto al de la pagina. Un origen es la terna\n  // protocolo + dominio + puerto.\n  //\n  // Nuestro frontend corre en  http://localhost:5500\n  // Nuestra API corre en       http://localhost:3000\n  //                                              ^^^^ puerto distinto\n  //                                              = origen distinto\n  //\n  // Sin CORS, el fetch del frontend falla con el error\n  // \"blocked by CORS policy\", aunque la API responda perfecto.\n  // CORS es el servidor diciendo: \"autorizo a este origen\".\n  //\n  // IMPORTANTE: NO usamos origin: '*' aunque sea mas facil. Hay que\n  // declarar los origenes permitidos (vienen de .env). Una API abierta\n  // a cualquier origen puede ser consumida por cualquier sitio web.\n  app.use(\n    cors({\n      origin: config.origenesPermitidos,\n\n      // Verbos HTTP que aceptamos.\n      methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],\n\n      // Cabeceras que el cliente puede enviar.\n      allowedHeaders: ['Content-Type', 'Accept'],\n\n      // Cabeceras que el navegador puede LEER de la respuesta.\n      // Sin esto, el frontend no puede leer la cabecera Location que\n      // devolvemos al crear un recurso.\n      exposedHeaders: ['Location'],\n\n      // Cuanto tiempo (segundos) puede el navegador cachear el permiso\n      // de la peticion previa OPTIONS. Ahorra viajes de ida y vuelta.\n      maxAge: 86400\n    })\n  );\n\n  // -------------------------------------------------------------------\n  // 3. LECTURA DEL CUERPO DE LA PETICION\n  // -------------------------------------------------------------------\n\n  // express.json() lee el cuerpo, lo interpreta como JSON y lo deja en\n  // req.body. Sin este middleware, req.body seria undefined.\n  //\n  // El limite de 100kb protege contra peticiones gigantes. Para esta\n  // API un cuerpo nunca pasa de unos kilobytes.\n  app.use(express.json({ limit: '100kb' }));\n\n  // Lee los formularios HTML clasicos (Content-Type:\n  // application/x-www-form-urlencoded). extended: true admite\n  // objetos anidados.\n  app.use(express.urlencoded({ extended: true, limit: '100kb' }));\n\n  // -------------------------------------------------------------------\n  // 4. REGISTRO DE PETICIONES (logging)\n  // -------------------------------------------------------------------\n  app.use(registrarPeticion);\n\n  // -------------------------------------------------------------------\n  // 5. RUTAS DE LA API\n  // -------------------------------------------------------------------\n\n  // Todo el enrutador principal se monta bajo el prefijo /api.\n  app.use('/api', rutas);\n\n  // Ruta raiz: un saludo que orienta a quien abre el servidor en el\n  // navegador y no sabe por donde empezar.\n  app.get('/', (req, res) => {\n    res.json({\n      ok: true,\n      mensaje: 'Bienvenido a persona-api. La documentacion de recursos esta en /api',\n      datos: {\n        documentacion: '/api',\n        estadoSalud: '/api/salud'\n      }\n    });\n  });\n\n  // -------------------------------------------------------------------\n  // 6. MANEJO DE ERRORES (SIEMPRE AL FINAL)\n  // -------------------------------------------------------------------\n\n  // Si la peticion llego hasta aqui, ninguna ruta coincidio -> 404.\n  app.use(rutaNoEncontrada);\n\n  // Middleware de errores. Debe ser el ULTIMO app.use() y tener\n  // CUATRO parametros (err, req, res, next).\n  app.use(manejadorErrores);\n\n  return app;\n}\n\nmodule.exports = { crearAplicacion };\n","persona-api/controllers/telefono.controller.js":"/**\n * controllers/telefono.controller.js\n * ---------------------------------------------------------------------\n * CAPA DE CONTROLADOR de la entidad Telefono.\n *\n * Nota de disenio REST: este controlador atiende dos familias de rutas.\n *\n *   1. Recurso principal:  /api/telefonos\n *   2. Subrecurso:         /api/usuarios/:id/telefonos\n *\n * La segunda forma expresa la relacion \"los telefonos DE este usuario\"\n * y es la que recomienda REST para relaciones 1 a N. Las dos conviven\n * sin problema porque la logica esta en el service, no aqui.\n */\n\nconst telefonoService = require('../services/telefono.service');\nconst respuesta = require('../utils/respuesta');\nconst MENSAJES = require('../utils/mensajes');\nconst { capturarAsync } = require('../middleware/errorHandler');\n\nclass TelefonoController {\n  /**\n   * GET /api/telefonos\n   * Query admitida: ?usuarioId=5&activo=1&tipo=Celular&buscar=300&pagina=1\n   */\n  listar = capturarAsync(async (req, res) => {\n    const { telefonos, total, pagina, limite } = await telefonoService.listar(req.query);\n\n    return respuesta.exito(res, {\n      mensaje: MENSAJES.EXITO.LISTA('telefonos'),\n      datos: telefonos,\n      meta: respuesta.construirMeta({\n        total,\n        pagina,\n        limite,\n        devueltos: telefonos.length\n      })\n    });\n  });\n\n  /** GET /api/telefonos/:id */\n  obtener = capturarAsync(async (req, res) => {\n    const telefono = await telefonoService.obtenerPorId(req.idsValidados.id);\n\n    return respuesta.exito(res, {\n      mensaje: MENSAJES.EXITO.DETALLE('Telefono'),\n      datos: telefono\n    });\n  });\n\n  /**\n   * GET /api/usuarios/:id/telefonos\n   * Los telefonos de un usuario concreto (subrecurso).\n   */\n  listarPorUsuario = capturarAsync(async (req, res) => {\n    const usuarioId = req.idsValidados.id;\n\n    const telefonos = await telefonoService.listarPorUsuario(usuarioId);\n\n    return respuesta.exito(res, {\n      mensaje: MENSAJES.EXITO.LISTA(`telefonos del usuario ${usuarioId}`),\n      datos: telefonos\n    });\n  });\n\n  /** POST /api/telefonos */\n  crear = capturarAsync(async (req, res) => {\n    const telefono = await telefonoService.crear(req.body);\n\n    res.set('Location', `/api/telefonos/${telefono.id}`);\n\n    return respuesta.creado(res, {\n      mensaje: MENSAJES.EXITO.CREADO('Telefono'),\n      datos: telefono\n    });\n  });\n\n  /**\n   * POST /api/usuarios/:id/telefonos\n   * Crea un telefono para un usuario, tomando el id del usuario de la\n   * URL en lugar del cuerpo.\n   *\n   * Fijate en el orden del spread: ponemos usuarioId DESPUES de\n   * ...req.body a proposito. Asi, si el cuerpo trae otro usuarioId\n   * distinto, la URL manda. La URL es la fuente de verdad del recurso.\n   */\n  crearParaUsuario = capturarAsync(async (req, res) => {\n    const usuarioId = req.idsValidados.id;\n\n    const telefono = await telefonoService.crear({\n      ...req.body,\n      usuarioId\n    });\n\n    res.set('Location', `/api/telefonos/${telefono.id}`);\n\n    return respuesta.creado(res, {\n      mensaje: MENSAJES.EXITO.CREADO('Telefono'),\n      datos: telefono\n    });\n  });\n\n  /** PUT /api/telefonos/:id */\n  actualizar = capturarAsync(async (req, res) => {\n    const telefono = await telefonoService.actualizar(req.idsValidados.id, req.body);\n\n    return respuesta.exito(res, {\n      mensaje: MENSAJES.EXITO.ACTUALIZADO('Telefono'),\n      datos: telefono\n    });\n  });\n\n  /** DELETE /api/telefonos/:id */\n  eliminar = capturarAsync(async (req, res) => {\n    const resumen = await telefonoService.eliminar(req.idsValidados.id);\n\n    return respuesta.exito(res, {\n      mensaje: MENSAJES.EXITO.ELIMINADO('Telefono'),\n      datos: resumen\n    });\n  });\n\n  /**\n   * PATCH /api/telefonos/:id/activar\n   * PATCH /api/telefonos/:id/desactivar\n   *\n   * Otro patron de fabrica: este metodo NO es el manejador, DEVUELVE\n   * el manejador ya configurado. Asi evitamos escribir dos metodos\n   * casi identicos.\n   *\n   * Y por que PATCH y no PUT? Porque PUT significa \"reemplaza el\n   * recurso completo\" y aqui solo tocamos una bandera. PATCH es el\n   * verbo correcto para una modificacion parcial puntual.\n   */\n  cambiarEstado(activar) {\n    return capturarAsync(async (req, res) => {\n      const telefono = await telefonoService.cambiarEstado(req.idsValidados.id, activar);\n\n      return respuesta.exito(res, {\n        mensaje: `Telefono ${activar ? 'activado' : 'desactivado'} correctamente.`,\n        datos: telefono\n      });\n    });\n  }\n}\n\nmodule.exports = new TelefonoController();\n","persona-api/controllers/usuario.controller.js":"/**\n * controllers/usuario.controller.js\n * ---------------------------------------------------------------------\n * CAPA DE CONTROLADOR de la entidad Usuario.\n *\n * SU UNICA RESPONSABILIDAD: traducir entre HTTP y el servicio.\n *\n *   ENTRADA : saca los datos de req (params, query, body).\n *   DELEGA  : llama al service, que es quien sabe las reglas.\n *   SALIDA  : arma la respuesta HTTP con el codigo correcto.\n *\n * REGLA PARA RECONOCER UN CONTROLADOR BIEN HECHO:\n * No debe contener NI UNA consulta SQL, NI UNA validacion de negocio,\n * NI UN calculo. Si ves un `SELECT` o un `if (edad > 18)` aqui, esa\n * logica esta en la capa equivocada.\n *\n * Un controlador \"delgado\" (thin controller) suele tener entre 3 y 8\n * lineas por metodo. Si crece, es sintoma de que se le esta metiendo\n * logica que pertenece al service.\n *\n * DE DONDE SALEN LOS DATOS DE LA PETICION?\n *   req.params -> de la ruta        /api/usuarios/7        -> { id: '7' }\n *   req.query  -> de la query       ?pagina=2&limite=10    -> { pagina: '2', ... }\n *   req.body   -> del cuerpo JSON   { \"primerNombre\": ... }\n *\n * OJO: req.params y req.query SIEMPRE traen TEXTO, nunca numeros.\n * Por eso el middleware validarIdNumerico ya nos dejo el id convertido\n * en req.idsValidados.\n */\n\nconst usuarioService = require('../services/usuario.service');\nconst respuesta = require('../utils/respuesta');\nconst MENSAJES = require('../utils/mensajes');\nconst { capturarAsync } = require('../middleware/errorHandler');\n\nclass UsuarioController {\n  /**\n   * GET /api/usuarios\n   * Lista usuarios con filtros y paginacion.\n   *\n   * Query admitida: ?pagina=1&limite=20&estado=1&ciudad=Medellin&buscar=hopper\n   *\n   * Cada metodo se envuelve en capturarAsync: si el service lanza un\n   * error, se va solo al middleware manejadorErrores. Por eso no hay\n   * ni un try/catch en este archivo.\n   */\n  listar = capturarAsync(async (req, res) => {\n    // Le pasamos la query completa al service; el decide que usar.\n    const { usuarios, total, pagina, limite } = await usuarioService.listar(req.query);\n\n    return respuesta.exito(res, {\n      mensaje: MENSAJES.EXITO.LISTA('usuarios'),\n\n      // usuarios es un arreglo de objetos Usuario. Al serializar,\n      // JSON.stringify llama al toJSON() de cada uno de forma\n      // automatica: no hay que convertir nada a mano.\n      datos: usuarios,\n\n      meta: respuesta.construirMeta({\n        total,\n        pagina,\n        limite,\n        devueltos: usuarios.length\n      })\n    });\n  });\n\n  /**\n   * GET /api/usuarios/:id\n   * Devuelve un usuario con sus telefonos y perfiles sociales.\n   */\n  obtener = capturarAsync(async (req, res) => {\n    // El id ya viene validado y convertido a numero por el middleware.\n    const id = req.idsValidados.id;\n\n    const usuario = await usuarioService.obtenerPorId(id);\n\n    return respuesta.exito(res, {\n      mensaje: MENSAJES.EXITO.DETALLE('Usuario'),\n      datos: usuario\n    });\n  });\n\n  /**\n   * POST /api/usuarios\n   * Crea un usuario nuevo.\n   *\n   * Responde 201 Created, no 200. Es el codigo correcto cuando una\n   * peticion crea un recurso nuevo en el servidor.\n   */\n  crear = capturarAsync(async (req, res) => {\n    const usuario = await usuarioService.crear(req.body);\n\n    // Cabecera Location: le dice al cliente en que URL quedo el\n    // recurso recien creado. Es parte del estandar REST.\n    res.set('Location', `/api/usuarios/${usuario.id}`);\n\n    return respuesta.creado(res, {\n      mensaje: MENSAJES.EXITO.CREADO('Usuario'),\n      datos: usuario\n    });\n  });\n\n  /**\n   * PUT /api/usuarios/:id\n   * Actualiza un usuario (acepta actualizaciones parciales).\n   */\n  actualizar = capturarAsync(async (req, res) => {\n    const id = req.idsValidados.id;\n\n    const usuario = await usuarioService.actualizar(id, req.body);\n\n    return respuesta.exito(res, {\n      mensaje: MENSAJES.EXITO.ACTUALIZADO('Usuario'),\n      datos: usuario\n    });\n  });\n\n  /**\n   * DELETE /api/usuarios/:id\n   * Elimina el usuario junto con sus telefonos y perfiles sociales.\n   *\n   * Devolvemos 200 con un resumen de lo borrado en lugar de 204\n   * (sin contenido), porque al aprendiz le sirve VER cuantas filas\n   * relacionadas se eliminaron en la transaccion.\n   */\n  eliminar = capturarAsync(async (req, res) => {\n    const id = req.idsValidados.id;\n\n    const resumen = await usuarioService.eliminar(id);\n\n    return respuesta.exito(res, {\n      mensaje: MENSAJES.EXITO.ELIMINADO('Usuario'),\n      datos: resumen\n    });\n  });\n}\n\nmodule.exports = new UsuarioController();\n","persona-api/database/01_schema.sql":"-- =====================================================================\n-- 01_schema.sql\n-- Proyecto : Personal Management API\n-- Objetivo : Crear el esquema y las 4 tablas del modelo relacional.\n-- Origen   : parametrization/db_relational_model/DB_relational_model.sql\n-- Nota     : El script es IDEMPOTENTE (usa IF NOT EXISTS), por lo tanto\n--            se puede ejecutar varias veces sin borrar datos existentes.\n-- Ejecutar : mysql -u root -p < 01_schema.sql\n-- =====================================================================\n\n-- Guardamos la configuracion original de la sesion para restaurarla al final.\nSET @OLD_UNIQUE_CHECKS      = @@UNIQUE_CHECKS,      UNIQUE_CHECKS = 0;\nSET @OLD_FOREIGN_KEY_CHECKS = @@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS = 0;\n\n-- ---------------------------------------------------------------------\n-- Esquema (base de datos) personal_management\n-- utf8mb4 permite guardar acentos, enies y emojis.\n-- ---------------------------------------------------------------------\nCREATE SCHEMA IF NOT EXISTS `personal_management`\n  DEFAULT CHARACTER SET utf8mb4\n  DEFAULT COLLATE utf8mb4_unicode_ci;\n\nUSE `personal_management`;\n\n-- ---------------------------------------------------------------------\n-- Tabla USUARIO  (la \"persona\" del dominio)\n-- Es la tabla padre: TELEFONO y PERFIL_SOCIAL dependen de ella.\n-- ---------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS `USUARIO` (\n  `id`               INT          NOT NULL AUTO_INCREMENT,\n  `primer_nombre`    VARCHAR(45)  NOT NULL,\n  `segundo_nombre`   VARCHAR(45)  NULL,\n  `primer_apellido`  VARCHAR(45)  NOT NULL,\n  `segundo_apellido` VARCHAR(45)  NULL,\n  `fecha_nacimiento` DATETIME     NOT NULL,\n  `edad`             INT          NOT NULL,\n  `ciudad_domicilio` VARCHAR(45)  NOT NULL,\n  `estado`           INT          NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE INDEX `id_UNIQUE` (`id` ASC) VISIBLE\n) ENGINE = InnoDB;\n\n-- ---------------------------------------------------------------------\n-- Tabla TELEFONO  (relacion 1 a N con USUARIO)\n-- Un usuario puede tener muchos telefonos; un telefono pertenece a uno.\n-- ---------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS `TELEFONO` (\n  `id`              INT         NOT NULL AUTO_INCREMENT,\n  `numero_telefono` VARCHAR(45) NULL,\n  `tipo_telefono`   VARCHAR(45) NULL,\n  `USUARIO_id`      INT         NOT NULL,\n  `activo`          INT         NULL,\n  PRIMARY KEY (`id`),\n  CONSTRAINT `fk_TELEFONO_USUARIO`\n    FOREIGN KEY (`USUARIO_id`)\n    REFERENCES `USUARIO` (`id`)\n    ON DELETE NO ACTION\n    ON UPDATE NO ACTION\n) ENGINE = InnoDB;\n\n-- ---------------------------------------------------------------------\n-- Tabla RED_SOCIAL  (catalogo: Facebook, Instagram, TikTok, ...)\n-- ---------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS `RED_SOCIAL` (\n  `id`     INT         NOT NULL AUTO_INCREMENT,\n  `nombre` VARCHAR(45) NOT NULL,\n  `url`    VARCHAR(45) NOT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE = InnoDB;\n\n-- ---------------------------------------------------------------------\n-- Tabla PERFIL_SOCIAL  (tabla puente N a N entre RED_SOCIAL y USUARIO)\n-- Su llave primaria es COMPUESTA: (RED_SOCIAL_id, USUARIO_id).\n-- Esto significa que un usuario solo puede tener un perfil por red.\n-- ---------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS `PERFIL_SOCIAL` (\n  `RED_SOCIAL_id` INT         NOT NULL,\n  `USUARIO_id`    INT         NOT NULL,\n  `url_perfil`    VARCHAR(45) NULL,\n  PRIMARY KEY (`RED_SOCIAL_id`, `USUARIO_id`),\n  CONSTRAINT `fk_RED_SOCIAL_has_USUARIO_RED_SOCIAL1`\n    FOREIGN KEY (`RED_SOCIAL_id`)\n    REFERENCES `RED_SOCIAL` (`id`)\n    ON DELETE NO ACTION\n    ON UPDATE NO ACTION,\n  CONSTRAINT `fk_RED_SOCIAL_has_USUARIO_USUARIO1`\n    FOREIGN KEY (`USUARIO_id`)\n    REFERENCES `USUARIO` (`id`)\n    ON DELETE NO ACTION\n    ON UPDATE NO ACTION\n) ENGINE = InnoDB;\n\n-- Restauramos la configuracion original de la sesion.\nSET FOREIGN_KEY_CHECKS = @OLD_FOREIGN_KEY_CHECKS;\nSET UNIQUE_CHECKS      = @OLD_UNIQUE_CHECKS;\n\n-- Verificacion rapida.\nSHOW TABLES;\n","persona-api/database/02_usuario_app.sql":"-- =====================================================================\n-- 02_usuario_app.sql\n-- Objetivo : Crear el usuario de MySQL que usara UNICAMENTE la API.\n-- Por que  : Nunca se conecta una aplicacion con el usuario 'root'.\n--            Si la API se ve comprometida, el atacante solo tendria\n--            permisos sobre la base de datos personal_management.\n--            Esto se llama \"principio de menor privilegio\".\n-- Ejecutar : mysql -u root -p < 02_usuario_app.sql\n-- =====================================================================\n\n-- Creamos el usuario. 'localhost' significa que solo puede conectarse\n-- desde la misma maquina donde corre MySQL.\nCREATE USER IF NOT EXISTS 'pm_user'@'localhost' IDENTIFIED BY 'pm_pass_2026';\n\n-- Le damos los permisos de datos (CRUD) sobre TODAS las tablas del esquema.\n-- SELECT -> leer | INSERT -> crear | UPDATE -> actualizar | DELETE -> borrar\nGRANT SELECT, INSERT, UPDATE, DELETE ON `personal_management`.* TO 'pm_user'@'localhost';\n\n-- Recargamos la tabla de privilegios para que los cambios apliquen ya.\nFLUSH PRIVILEGES;\n\n-- Verificacion: debe listar los GRANT otorgados arriba.\nSHOW GRANTS FOR 'pm_user'@'localhost';\n","persona-api/database/03_datos_prueba.sql":"-- =====================================================================\n-- 03_datos_prueba.sql\n-- Objetivo : Cargar datos de ejemplo (seed) para poder probar la API.\n-- Nota     : Es IDEMPOTENTE. Usa INSERT ... SELECT ... WHERE NOT EXISTS,\n--            asi que se puede correr varias veces sin duplicar filas\n--            ni borrar informacion que ya exista.\n-- Ejecutar : mysql -u root -p < 03_datos_prueba.sql\n-- =====================================================================\n\nUSE `personal_management`;\n\n-- ---------------------------------------------------------------------\n-- Catalogo de redes sociales. La condicion NOT EXISTS evita duplicados\n-- porque la columna 'nombre' no tiene indice UNIQUE en el modelo.\n-- ---------------------------------------------------------------------\nINSERT INTO `RED_SOCIAL` (`nombre`, `url`)\nSELECT 'LinkedIn', 'https://www.linkedin.com'\nWHERE NOT EXISTS (SELECT 1 FROM `RED_SOCIAL` WHERE `nombre` = 'LinkedIn');\n\nINSERT INTO `RED_SOCIAL` (`nombre`, `url`)\nSELECT 'X', 'https://www.x.com'\nWHERE NOT EXISTS (SELECT 1 FROM `RED_SOCIAL` WHERE `nombre` = 'X');\n\nINSERT INTO `RED_SOCIAL` (`nombre`, `url`)\nSELECT 'GitHub', 'https://www.github.com'\nWHERE NOT EXISTS (SELECT 1 FROM `RED_SOCIAL` WHERE `nombre` = 'GitHub');\n\n-- ---------------------------------------------------------------------\n-- Usuarios de ejemplo. Identificamos cada uno por nombre + apellido.\n-- La columna 'edad' se guarda calculada; la API la recalcula siempre\n-- a partir de 'fecha_nacimiento' (ver utils/fechas.js).\n-- ---------------------------------------------------------------------\nINSERT INTO `USUARIO`\n  (`primer_nombre`, `segundo_nombre`, `primer_apellido`, `segundo_apellido`,\n   `fecha_nacimiento`, `edad`, `ciudad_domicilio`, `estado`)\nSELECT 'Grace', 'Brewster', 'Hopper', 'Murray', '1906-12-09 00:00:00', 119, 'Nueva York', 1\nWHERE NOT EXISTS (\n  SELECT 1 FROM `USUARIO` WHERE `primer_nombre` = 'Grace' AND `primer_apellido` = 'Hopper'\n);\n\nINSERT INTO `USUARIO`\n  (`primer_nombre`, `segundo_nombre`, `primer_apellido`, `segundo_apellido`,\n   `fecha_nacimiento`, `edad`, `ciudad_domicilio`, `estado`)\nSELECT 'Alan', 'Mathison', 'Turing', NULL, '1912-06-23 00:00:00', 113, 'Londres', 1\nWHERE NOT EXISTS (\n  SELECT 1 FROM `USUARIO` WHERE `primer_nombre` = 'Alan' AND `primer_apellido` = 'Turing'\n);\n\n-- ---------------------------------------------------------------------\n-- Telefonos de ejemplo. Buscamos el USUARIO_id con una subconsulta\n-- en lugar de \"adivinar\" el id, porque el AUTO_INCREMENT puede variar.\n-- ---------------------------------------------------------------------\nINSERT INTO `TELEFONO` (`numero_telefono`, `tipo_telefono`, `USUARIO_id`, `activo`)\nSELECT '3001234567', 'Celular', u.`id`, 1\nFROM `USUARIO` u\nWHERE u.`primer_nombre` = 'Grace' AND u.`primer_apellido` = 'Hopper'\n  AND NOT EXISTS (SELECT 1 FROM `TELEFONO` t WHERE t.`numero_telefono` = '3001234567');\n\nINSERT INTO `TELEFONO` (`numero_telefono`, `tipo_telefono`, `USUARIO_id`, `activo`)\nSELECT '6045550101', 'Fijo', u.`id`, 1\nFROM `USUARIO` u\nWHERE u.`primer_nombre` = 'Alan' AND u.`primer_apellido` = 'Turing'\n  AND NOT EXISTS (SELECT 1 FROM `TELEFONO` t WHERE t.`numero_telefono` = '6045550101');\n\n-- ---------------------------------------------------------------------\n-- Perfiles sociales de ejemplo (tabla puente con llave compuesta).\n-- INSERT IGNORE evita el error 1062 (Duplicate entry) si ya existe.\n-- ---------------------------------------------------------------------\nINSERT IGNORE INTO `PERFIL_SOCIAL` (`RED_SOCIAL_id`, `USUARIO_id`, `url_perfil`)\nSELECT r.`id`, u.`id`, 'https://www.linkedin.com/in/gracehopper'\nFROM `RED_SOCIAL` r, `USUARIO` u\nWHERE r.`nombre` = 'LinkedIn'\n  AND u.`primer_nombre` = 'Grace' AND u.`primer_apellido` = 'Hopper';\n\nINSERT IGNORE INTO `PERFIL_SOCIAL` (`RED_SOCIAL_id`, `USUARIO_id`, `url_perfil`)\nSELECT r.`id`, u.`id`, 'https://www.github.com/aturing'\nFROM `RED_SOCIAL` r, `USUARIO` u\nWHERE r.`nombre` = 'GitHub'\n  AND u.`primer_nombre` = 'Alan' AND u.`primer_apellido` = 'Turing';\n\n-- Verificacion: conteo de filas por tabla.\nSELECT 'USUARIO' AS tabla, COUNT(*) AS filas FROM `USUARIO`\nUNION ALL SELECT 'TELEFONO',      COUNT(*) FROM `TELEFONO`\nUNION ALL SELECT 'RED_SOCIAL',    COUNT(*) FROM `RED_SOCIAL`\nUNION ALL SELECT 'PERFIL_SOCIAL', COUNT(*) FROM `PERFIL_SOCIAL`;\n","persona-api/index.js":"/**\n * index.js\n * ---------------------------------------------------------------------\n * PUNTO DE ENTRADA de la aplicacion. Es el archivo que ejecuta\n * `node index.js` y, por lo tanto, lo primero que corre.\n *\n * SU UNICA RESPONSABILIDAD: el CICLO DE VIDA del servidor.\n *   1. Verificar que la base de datos responda.\n *   2. Crear la aplicacion Express.\n *   3. Ponerla a escuchar en un puerto.\n *   4. Apagarla de forma ordenada cuando toque.\n *\n * Observa que este archivo NO tiene rutas, NI consultas SQL, NI\n * validaciones. Solo enciende y apaga. Toda la configuracion vive en\n * config/express.js.\n */\n\nconst config = require('./config/env');\nconst db = require('./config/database');\nconst { crearAplicacion } = require('./config/express');\nconst { COLOR } = require('./middleware/logger');\n\n/**\n * Imprime el banner de arranque con los datos utiles para el aprendiz.\n */\nfunction mostrarBanner() {\n  const linea = '='.repeat(62);\n\n  console.log(`\\n${COLOR.cian}${linea}${COLOR.reinicio}`);\n  console.log(`${COLOR.cian}  persona-api  ·  API REST Personal Management${COLOR.reinicio}`);\n  console.log(`${COLOR.cian}${linea}${COLOR.reinicio}`);\n  console.log(`  Entorno        : ${config.entorno}`);\n  console.log(`  Servidor       : http://localhost:${config.puerto}`);\n  console.log(`  Documentacion  : http://localhost:${config.puerto}/api`);\n  console.log(`  Estado salud   : http://localhost:${config.puerto}/api/salud`);\n  console.log(`  Base de datos  : ${config.baseDatos.nombre} @ ${config.baseDatos.host}:${config.baseDatos.puerto}`);\n  console.log(`  Usuario MySQL  : ${config.baseDatos.usuario}`);\n  console.log(`  Origenes CORS  : ${config.origenesPermitidos.join(', ')}`);\n  console.log(`${COLOR.cian}${linea}${COLOR.reinicio}`);\n  console.log(`  ${COLOR.gris}Presiona Ctrl + C para detener el servidor${COLOR.reinicio}\\n`);\n}\n\n/**\n * Arranca el servidor.\n *\n * Es `async` porque verificar la conexion a MySQL es una operacion\n * asincrona: hay que esperar la respuesta de la base de datos.\n */\nasync function iniciarServidor() {\n  try {\n    // ---- Paso 1: comprobar la base de datos ANTES de abrir el puerto ----\n    //\n    // Esto se llama \"fail fast\": si MySQL esta apagado, es mejor que el\n    // servidor no arranque y lo digamos claramente, en lugar de\n    // arrancar y fallar en la primera peticion de un usuario.\n    console.log(`${COLOR.gris}Verificando conexion con MySQL...${COLOR.reinicio}`);\n    await db.verificarConexion();\n    console.log(`${COLOR.verde}Conexion con MySQL establecida.${COLOR.reinicio}`);\n\n    // ---- Paso 2: crear la aplicacion ----\n    const app = crearAplicacion();\n\n    // ---- Paso 3: escuchar ----\n    // app.listen devuelve el objeto servidor de Node, que guardamos\n    // para poder cerrarlo despues de forma ordenada.\n    const servidor = app.listen(config.puerto, () => {\n      mostrarBanner();\n    });\n\n    // -------------------------------------------------------------------\n    // APAGADO ELEGANTE (graceful shutdown)\n    // -------------------------------------------------------------------\n    //\n    // Cuando pulsas Ctrl + C, el sistema operativo envia la senial\n    // SIGINT. Si no la atendemos, Node muere de golpe y deja conexiones\n    // a MySQL abiertas y peticiones a medio responder.\n    //\n    // Apagado elegante = dejar de aceptar peticiones nuevas, terminar\n    // las que estan en curso, cerrar el pool y recien entonces salir.\n    const apagar = async (senial) => {\n      console.log(`\\n${COLOR.amarillo}Senial ${senial} recibida. Cerrando el servidor...${COLOR.reinicio}`);\n\n      // server.close deja de aceptar conexiones nuevas y espera a que\n      // terminen las que ya estan en curso.\n      servidor.close(async () => {\n        try {\n          await db.cerrar();\n          console.log(`${COLOR.verde}Pool de MySQL cerrado. Hasta pronto.${COLOR.reinicio}\\n`);\n          process.exit(0);\n        } catch (error) {\n          console.error('Error al cerrar el pool:', error.message);\n          process.exit(1);\n        }\n      });\n\n      // Red de seguridad: si en 10 segundos no termino, salimos a la\n      // fuerza. Evita que el proceso se quede colgado para siempre.\n      setTimeout(() => {\n        console.error('El cierre tardo demasiado. Forzando la salida.');\n        process.exit(1);\n      }, 10_000);\n    };\n\n    // SIGINT  -> Ctrl + C en la terminal.\n    // SIGTERM -> lo envian Docker, Kubernetes o un gestor de procesos.\n    process.on('SIGINT', () => apagar('SIGINT'));\n    process.on('SIGTERM', () => apagar('SIGTERM'));\n\n    return servidor;\n  } catch (error) {\n    // Si falla el arranque, mostramos un diagnostico util en vez de un\n    // stack trace crudo que no le dice nada al aprendiz.\n    console.error(`\\n${COLOR.rojo}No se pudo iniciar el servidor.${COLOR.reinicio}`);\n    console.error(`${COLOR.rojo}Motivo: ${error.message}${COLOR.reinicio}\\n`);\n    console.error('Lista de verificacion:');\n    console.error('  1. El servidor MySQL esta encendido?');\n    console.error(`  2. Existe la base de datos \"${config.baseDatos.nombre}\"?`);\n    console.error(`  3. El usuario \"${config.baseDatos.usuario}\" y su clave son correctos en .env?`);\n    console.error('  4. Ejecutaste los scripts de la carpeta database/?\\n');\n\n    process.exit(1);\n  }\n}\n\n// -------------------------------------------------------------------\n// RED DE SEGURIDAD GLOBAL\n// -------------------------------------------------------------------\n\n// Una promesa que se rechaza y nadie atrapa. Sin este manejador, Node\n// imprime un aviso y en versiones modernas termina el proceso.\nprocess.on('unhandledRejection', (razon) => {\n  console.error(`\\n${COLOR.rojo}[unhandledRejection] Promesa rechazada sin manejar:${COLOR.reinicio}`, razon);\n});\n\n// Una excepcion que escapo de todos los try/catch. Llegar aqui\n// significa que el proceso quedo en un estado no confiable, asi que lo\n// correcto es registrar y salir para que el gestor de procesos\n// reinicie limpio.\nprocess.on('uncaughtException', (error) => {\n  console.error(`\\n${COLOR.rojo}[uncaughtException] Error no capturado:${COLOR.reinicio}`, error);\n  process.exit(1);\n});\n\n// Encendemos todo.\niniciarServidor();\n","persona-api/middleware/errorHandler.js":"/**\n * middleware/errorHandler.js\n * ---------------------------------------------------------------------\n * Manejo CENTRALIZADO de errores.\n *\n * La idea: en los services y controllers simplemente lanzamos el error\n * (`throw`). Nadie responde errores a mano. Todos los errores terminan\n * aqui, en un solo lugar, que decide:\n *   - que codigo HTTP responder,\n *   - que mensaje mostrarle al usuario,\n *   - que registrar en el log del servidor.\n *\n * Ventaja: si manana hay que enviar los errores a un sistema de\n * monitoreo, se agrega UNA linea aqui y cubre toda la aplicacion.\n *\n * REGLA DE ORO DE EXPRESS: el middleware de errores tiene CUATRO\n * parametros (err, req, res, next). Si le pones tres, Express lo\n * registra como middleware normal y nunca atrapara los errores.\n */\n\nconst AppError = require('../utils/AppError');\nconst MENSAJES = require('../utils/mensajes');\nconst { HTTP, CODIGO_ERROR } = require('../utils/constants');\nconst respuesta = require('../utils/respuesta');\nconst config = require('../config/env');\nconst { COLOR } = require('./logger');\n\n/**\n * Traduce los codigos de error de MySQL a errores de la aplicacion.\n *\n * MySQL devuelve codigos tecnicos como 'ER_DUP_ENTRY' que no se le\n * pueden mostrar a un usuario final. Aqui los convertimos en mensajes\n * entendibles y en el codigo HTTP adecuado.\n *\n * @param {Error} error  Error original del driver mysql2.\n * @returns {AppError|null}  AppError traducido, o null si no era de MySQL.\n */\nfunction traducirErrorMySQL(error) {\n  // El driver mysql2 agrega la propiedad `code` a sus errores.\n  const codigo = error.code;\n\n  switch (codigo) {\n    // Se intento insertar un valor repetido en una llave UNIQUE o PRIMARY.\n    case 'ER_DUP_ENTRY':\n      return AppError.conflicto(\n        'El registro ya existe. Revisa los campos que deben ser unicos.'\n      );\n\n    // Se referencio un id que no existe en la tabla padre.\n    // Ejemplo: crear un TELEFONO con USUARIO_id = 9999.\n    case 'ER_NO_REFERENCED_ROW':\n    case 'ER_NO_REFERENCED_ROW_2':\n      return new AppError(\n        'El registro referenciado no existe. Verifica los identificadores enviados.',\n        HTTP.SOLICITUD_INCORRECTA,\n        CODIGO_ERROR.LLAVE_FORANEA\n      );\n\n    // Se intento borrar un registro padre que aun tiene hijos.\n    case 'ER_ROW_IS_REFERENCED':\n    case 'ER_ROW_IS_REFERENCED_2':\n      return new AppError(\n        'No se puede eliminar el registro porque otros registros dependen de el.',\n        HTTP.CONFLICTO,\n        CODIGO_ERROR.LLAVE_FORANEA\n      );\n\n    // El texto enviado es mas largo que el VARCHAR de la columna.\n    case 'ER_DATA_TOO_LONG':\n      return AppError.validacion(\n        'Uno de los campos supera el tamanio permitido por la base de datos (45 caracteres).'\n      );\n\n    // Se envio null en una columna NOT NULL.\n    case 'ER_BAD_NULL_ERROR':\n      return AppError.validacion('Falta un campo obligatorio requerido por la base de datos.');\n\n    // El servidor MySQL esta apagado o no acepta conexiones.\n    case 'ECONNREFUSED':\n    case 'PROTOCOL_CONNECTION_LOST':\n    case 'ER_CON_COUNT_ERROR':\n      return AppError.baseDatos(\n        'No se pudo conectar con la base de datos. Verifica que MySQL este encendido.'\n      );\n\n    // Usuario o clave incorrectos en el archivo .env\n    case 'ER_ACCESS_DENIED_ERROR':\n      return AppError.baseDatos(\n        'Credenciales de base de datos incorrectas. Revisa DB_USUARIO y DB_CLAVE en tu archivo .env'\n      );\n\n    default:\n      // No era un error de MySQL que sepamos traducir.\n      return null;\n  }\n}\n\n/**\n * Middleware 404: se registra DESPUES de todas las rutas.\n * Si la peticion llego hasta aqui, ninguna ruta coincidio.\n */\nfunction rutaNoEncontrada(req, res, next) {\n  const error = new AppError(\n    MENSAJES.SISTEMA.RUTA_NO_ENCONTRADA(req.method, req.originalUrl),\n    HTTP.NO_ENCONTRADO,\n    CODIGO_ERROR.RUTA_NO_ENCONTRADA\n  );\n\n  // next(error) salta directo al middleware de errores.\n  // Si llamaramos next() sin argumento, seguiria la cadena normal.\n  next(error);\n}\n\n/**\n * Middleware de errores. DEBE ser el ultimo app.use() de la aplicacion\n * y DEBE declarar cuatro parametros.\n */\n// eslint-disable-next-line no-unused-vars\nfunction manejadorErrores(err, req, res, next) {\n  // ----- Paso 1: normalizar el error a un AppError -----\n  let error = err;\n\n  if (!(error instanceof AppError)) {\n    // Caso A: JSON mal formado. express.json() lanza un SyntaxError\n    // con la propiedad `body` cuando el cuerpo no se pudo parsear.\n    if (error instanceof SyntaxError && 'body' in error) {\n      error = AppError.validacion(MENSAJES.SISTEMA.JSON_MAL_FORMADO);\n    } else {\n      // Caso B: error del driver de MySQL.\n      const traducido = traducirErrorMySQL(error);\n\n      if (traducido !== null) {\n        error = traducido;\n      } else {\n        // Caso C: cualquier otro error inesperado (un bug nuestro).\n        // No mostramos el mensaje interno al cliente para no filtrar\n        // detalles de implementacion; eso solo viaja al log.\n        error = new AppError(\n          MENSAJES.SISTEMA.ERROR_INTERNO,\n          HTTP.ERROR_SERVIDOR,\n          CODIGO_ERROR.INTERNO\n        );\n      }\n    }\n  }\n\n  // ----- Paso 2: registrar en el log del servidor -----\n  const esErrorServidor = error.estadoHttp >= HTTP.ERROR_SERVIDOR;\n\n  if (esErrorServidor) {\n    // Los errores 5xx son bugs: registramos TODO, incluido el stack.\n    console.error(\n      `${COLOR.rojo}[ERROR ${error.estadoHttp}]${COLOR.reinicio} ` +\n      `${req.method} ${req.originalUrl}\\n`,\n      err.stack || err\n    );\n  } else if (config.esDesarrollo) {\n    // Los 4xx son errores del cliente: una linea basta.\n    console.warn(\n      `${COLOR.amarillo}[AVISO ${error.estadoHttp}]${COLOR.reinicio} ` +\n      `${req.method} ${req.originalUrl} -> ${error.message}`\n    );\n  }\n\n  // ----- Paso 3: responder al cliente -----\n  return respuesta.error(res, {\n    estado: error.estadoHttp,\n    codigo: error.codigo,\n    mensaje: error.message,\n    detalles: error.detalles\n  });\n}\n\n/**\n * Envoltorio para controladores asincronos.\n *\n * PROBLEMA: Express 4 no atrapa los errores de funciones `async`.\n * Si un controlador async lanza un error, la peticion se queda colgada\n * y el cliente espera para siempre.\n *\n * SOLUCION CLASICA (repetitiva):\n *   async function listar(req, res, next) {\n *     try { ... } catch (e) { next(e); }\n *   }\n *\n * SOLUCION ELEGANTE: envolvemos el controlador en esta funcion, que\n * engancha un .catch(next) automatico. Asi los controladores quedan\n * limpios, sin try/catch repetido en cada metodo.\n *\n * @param {function} funcionAsincrona\n * @returns {function} Middleware listo para Express.\n */\nfunction capturarAsync(funcionAsincrona) {\n  return function (req, res, next) {\n    // Promise.resolve() convierte el retorno en promesa aunque la\n    // funcion no fuera async, y .catch(next) envia cualquier error\n    // al middleware manejadorErrores.\n    Promise.resolve(funcionAsincrona(req, res, next)).catch(next);\n  };\n}\n\nmodule.exports = {\n  rutaNoEncontrada,\n  manejadorErrores,\n  capturarAsync,\n  traducirErrorMySQL\n};\n","persona-api/middleware/logger.js":"/**\n * middleware/logger.js\n * ---------------------------------------------------------------------\n * Middleware que registra en consola cada peticion que llega.\n *\n * QUE ES UN MIDDLEWARE?\n * Es una funcion con la firma (req, res, next) que Express ejecuta en\n * cadena, en el orden en que se registra con app.use().\n *\n *   peticion -> [logger] -> [cors] -> [json] -> [rutas] -> [errores] -> respuesta\n *\n *   req  = la peticion entrante  (lo que envia el cliente)\n *   res  = la respuesta saliente (lo que devolvemos)\n *   next = funcion para pasar el control al SIGUIENTE middleware\n *\n * Si un middleware no llama a next() ni responde, la peticion se queda\n * colgada para siempre. Es el error mas comun al empezar con Express.\n */\n\nconst { ahoraISO } = require('../utils/fechas');\nconst config = require('../config/env');\n\n// Codigos de color ANSI para la terminal. Hacen el log mas legible.\n// \\x1b[ es el caracter de escape; 0m devuelve el color a la normalidad.\nconst COLOR = {\n  reinicio: '\\x1b[0m',\n  gris: '\\x1b[90m',\n  verde: '\\x1b[32m',\n  amarillo: '\\x1b[33m',\n  rojo: '\\x1b[31m',\n  azul: '\\x1b[34m',\n  cian: '\\x1b[36m'\n};\n\n/**\n * Elige el color segun el codigo HTTP de la respuesta.\n * 2xx verde, 3xx cian, 4xx amarillo, 5xx rojo.\n */\nfunction colorPorEstado(estado) {\n  if (estado >= 500) return COLOR.rojo;\n  if (estado >= 400) return COLOR.amarillo;\n  if (estado >= 300) return COLOR.cian;\n  return COLOR.verde;\n}\n\n/**\n * Middleware de registro de peticiones.\n *\n * Truco clave: medimos el tiempo de respuesta escuchando el evento\n * 'finish' del objeto res. Ese evento se dispara cuando Express ya\n * envio la respuesta completa, que es el unico momento en que\n * conocemos el codigo de estado final.\n */\nfunction registrarPeticion(req, res, next) {\n  // process.hrtime.bigint() da nanosegundos con alta precision.\n  // Date.now() solo da milisegundos y no sirve para medir rutas rapidas.\n  const inicio = process.hrtime.bigint();\n\n  res.on('finish', () => {\n    const fin = process.hrtime.bigint();\n\n    // De nanosegundos a milisegundos: dividimos entre un millon.\n    const duracionMs = Number(fin - inicio) / 1_000_000;\n\n    const color = colorPorEstado(res.statusCode);\n\n    // req.originalUrl incluye la query string (?pagina=2).\n    // req.method es GET, POST, PUT, DELETE...\n    console.log(\n      `${COLOR.gris}[${ahoraISO()}]${COLOR.reinicio} ` +\n      `${COLOR.azul}${req.method}${COLOR.reinicio} ` +\n      `${req.originalUrl} ` +\n      `${color}${res.statusCode}${COLOR.reinicio} ` +\n      `${COLOR.gris}${duracionMs.toFixed(1)} ms${COLOR.reinicio}`\n    );\n  });\n\n  // En desarrollo mostramos tambien el cuerpo de la peticion.\n  // En produccion NO, porque podria contener datos sensibles.\n  if (config.esDesarrollo && req.body && Object.keys(req.body).length > 0) {\n    console.log(`${COLOR.gris}   cuerpo:${COLOR.reinicio}`, JSON.stringify(req.body));\n  }\n\n  // Pasamos el control al siguiente middleware de la cadena.\n  next();\n}\n\nmodule.exports = { registrarPeticion, COLOR };\n","persona-api/middleware/validarParametros.js":"/**\n * middleware/validarParametros.js\n * ---------------------------------------------------------------------\n * Middlewares que validan los parametros de la URL ANTES de que la\n * peticion llegue al controlador.\n *\n * Por que validar aqui y no en el controlador?\n * Porque es una validacion de FORMATO, no de negocio. Si alguien pide\n * GET /api/usuarios/abc, no tiene sentido abrir una conexion a MySQL:\n * rechazamos de inmediato con 400 y ahorramos trabajo al servidor.\n *\n * Esto se llama \"fail fast\": fallar lo antes posible, lo mas cerca\n * posible de donde entra el dato malo.\n */\n\nconst AppError = require('../utils/AppError');\nconst MENSAJES = require('../utils/mensajes');\nconst { esEnteroPositivo } = require('../utils/validadores');\n\n/**\n * FABRICA DE MIDDLEWARES.\n *\n * Fijate que esta funcion NO es el middleware: es una funcion que\n * DEVUELVE un middleware. Ese patron se llama \"closure\" y permite\n * configurar el middleware al registrarlo:\n *\n *   router.get('/:id', validarIdNumerico('id'), controlador.obtener);\n *   router.delete('/:redSocialId/:usuarioId',\n *     validarIdNumerico('redSocialId'),\n *     validarIdNumerico('usuarioId'),\n *     controlador.eliminar);\n *\n * @param {string} nombreParametro  Nombre del parametro en la ruta.\n * @returns {function} Middleware de Express.\n */\nfunction validarIdNumerico(nombreParametro = 'id') {\n  return function (req, res, next) {\n    // req.params contiene los parametros de la ruta (:id -> req.params.id)\n    const valor = req.params[nombreParametro];\n\n    if (!esEnteroPositivo(valor)) {\n      // Pasamos el error al middleware manejadorErrores.\n      return next(\n        AppError.validacion(MENSAJES.VALIDACION.ID_INVALIDO(nombreParametro), [\n          { campo: nombreParametro, mensaje: MENSAJES.VALIDACION.ID_INVALIDO(nombreParametro) }\n        ])\n      );\n    }\n\n    // Convertimos el texto \"7\" a numero 7 y lo dejamos disponible en\n    // req.idsValidados para que el controlador no repita la conversion.\n    if (!req.idsValidados) {\n      req.idsValidados = {};\n    }\n    req.idsValidados[nombreParametro] = Number.parseInt(valor, 10);\n\n    next();\n  };\n}\n\n/**\n * Rechaza las peticiones con el cuerpo vacio.\n * Se usa en POST y PUT, donde enviar {} casi siempre es un error\n * del cliente (por ejemplo, olvido la cabecera Content-Type).\n */\nfunction exigirCuerpo(req, res, next) {\n  const cuerpo = req.body;\n\n  const estaVacio =\n    cuerpo === null ||\n    cuerpo === undefined ||\n    typeof cuerpo !== 'object' ||\n    Object.keys(cuerpo).length === 0;\n\n  if (estaVacio) {\n    return next(AppError.validacion(MENSAJES.VALIDACION.CUERPO_VACIO));\n  }\n\n  next();\n}\n\nmodule.exports = { validarIdNumerico, exigirCuerpo };\n","persona-api/models/PerfilSocial.js":"/**\n * models/PerfilSocial.js\n * ---------------------------------------------------------------------\n * ENTIDAD PerfilSocial -> tabla `PERFIL_SOCIAL`.\n *\n * ESTA ES LA CLASE MAS INTERESANTE DEL MODELO. Presta atencion:\n *\n * 1. ES UNA TABLA PUENTE (o tabla de union).\n *    Un usuario puede estar en muchas redes sociales y una red social\n *    tiene muchos usuarios: es una relacion de MUCHOS A MUCHOS (N:N).\n *    Las bases de datos relacionales no pueden representar N:N\n *    directamente, asi que se parte en dos relaciones 1:N usando una\n *    tabla intermedia:\n *\n *        USUARIO  1 ---- N  PERFIL_SOCIAL  N ---- 1  RED_SOCIAL\n *\n * 2. SU LLAVE PRIMARIA ES COMPUESTA.\n *    PRIMARY KEY (RED_SOCIAL_id, USUARIO_id)\n *\n *    No tiene una columna `id` AUTO_INCREMENT. La identidad de la fila\n *    son las DOS llaves foraneas juntas. Consecuencias practicas:\n *\n *      - La URL del recurso lleva dos parametros:\n *          GET /api/perfiles-sociales/4/3\n *        (red social 4, usuario 3)\n *\n *      - La base de datos garantiza que un usuario NO pueda tener dos\n *        perfiles en la misma red social. Esa regla la impone MySQL,\n *        no nuestro codigo: es mucho mas confiable.\n *\n * 3. Igual que en Telefono, los atributos #redSocial y #usuario\n *    aceptan un id o la instancia completa, y los getters\n *    `redSocialId` / `usuarioId` normalizan ambos casos.\n */\n\nclass PerfilSocial {\n  #redSocial;\n  #usuario;\n  #urlPerfil;\n\n  /**\n   * @param {number|RedSocial} redSocial  Id de la red social o la instancia.\n   * @param {number|Usuario}   usuario    Id del usuario o la instancia.\n   * @param {string|null}      urlPerfil  URL del perfil del usuario.\n   */\n  constructor(redSocial, usuario, urlPerfil = null) {\n    this.#redSocial = redSocial;\n    this.#usuario = usuario;\n    this.#urlPerfil = urlPerfil;\n  }\n\n  // ------------------------- Getters y setters -------------------------\n\n  get redSocial() {\n    return this.#redSocial;\n  }\n\n  set redSocial(valor) {\n    this.#redSocial = valor;\n  }\n\n  get usuario() {\n    return this.#usuario;\n  }\n\n  set usuario(valor) {\n    this.#usuario = valor;\n  }\n\n  get urlPerfil() {\n    return this.#urlPerfil;\n  }\n\n  set urlPerfil(valor) {\n    this.#urlPerfil = valor;\n  }\n\n  /**\n   * Normaliza la mitad \"red social\" de la llave compuesta.\n   * @returns {number|null}\n   */\n  get redSocialId() {\n    return PerfilSocial.#extraerId(this.#redSocial);\n  }\n\n  /**\n   * Normaliza la mitad \"usuario\" de la llave compuesta.\n   * @returns {number|null}\n   */\n  get usuarioId() {\n    return PerfilSocial.#extraerId(this.#usuario);\n  }\n\n  /**\n   * Metodo PRIVADO y ESTATICO a la vez.\n   *   - static  -> pertenece a la clase, no a la instancia.\n   *   - #       -> solo se puede llamar desde dentro de la clase.\n   *\n   * Lo usamos para no repetir la misma logica de normalizacion en los\n   * dos getters de arriba (principio DRY: Don't Repeat Yourself).\n   *\n   * @param {*} valor  Un id, una instancia o un objeto plano.\n   * @returns {number|null}\n   */\n  static #extraerId(valor) {\n    if (valor === null || valor === undefined) return null;\n\n    if (typeof valor === 'object') {\n      return valor.id ?? null;\n    }\n\n    const numero = Number(valor);\n    return Number.isInteger(numero) ? numero : null;\n  }\n\n  // -------------------------- Metodos de negocio ------------------------\n\n  /**\n   * Devuelve la llave compuesta como texto, util para logs y para\n   * usar como clave en un Map.\n   *\n   *   \"4:3\"  -> red social 4, usuario 3\n   */\n  obtenerClaveCompuesta() {\n    return `${this.redSocialId}:${this.usuarioId}`;\n  }\n\n  /** true si las dos mitades de la llave compuesta estan presentes. */\n  tieneClaveCompleta() {\n    return this.redSocialId !== null && this.usuarioId !== null;\n  }\n\n  /**\n   * Extrae el nombre de usuario (handle) desde la URL del perfil.\n   *\n   *   \"https://www.instagram.com/adalovelace\" -> \"adalovelace\"\n   *\n   * @returns {string|null}\n   */\n  obtenerNombreUsuarioPerfil() {\n    if (!this.#urlPerfil) return null;\n\n    try {\n      const url = new URL(this.#urlPerfil);\n\n      // pathname es \"/adalovelace\". Partimos por \"/\" y nos quedamos\n      // con el ultimo segmento que no este vacio.\n      const segmentos = url.pathname.split('/').filter(Boolean);\n\n      // at(-1) devuelve el ultimo elemento del arreglo.\n      return segmentos.length > 0 ? segmentos.at(-1) : null;\n    } catch {\n      return null;\n    }\n  }\n\n  /**\n   * Nombre de la red social, SOLO si #redSocial guarda la instancia\n   * completa. Si guarda un id devuelve null.\n   */\n  obtenerNombreRed() {\n    if (this.#redSocial !== null && typeof this.#redSocial === 'object') {\n      return this.#redSocial.nombre ?? null;\n    }\n    return null;\n  }\n\n  // ---------------------------- Fabricas -------------------------------\n\n  /**\n   * Construye un PerfilSocial desde una fila de MySQL.\n   *\n   * Si la consulta trajo un JOIN con RED_SOCIAL (columnas red_nombre y\n   * red_url), armamos la instancia de RedSocial para que el JSON de\n   * salida sea mas rico. Asi el frontend no necesita una segunda\n   * peticion para saber como se llama la red.\n   *\n   * @param {object} fila\n   * @returns {PerfilSocial|null}\n   */\n  static desdeFila(fila) {\n    if (!fila) return null;\n\n    // Por defecto guardamos solo el id de la red social.\n    let redSocial = fila.RED_SOCIAL_id;\n\n    // Si la fila viene de un JOIN, construimos el objeto completo.\n    if (fila.red_nombre !== undefined && fila.red_nombre !== null) {\n      const RedSocial = require('./RedSocial');\n      redSocial = new RedSocial(fila.RED_SOCIAL_id, fila.red_nombre, fila.red_url);\n    }\n\n    return new PerfilSocial(redSocial, fila.USUARIO_id, fila.url_perfil);\n  }\n\n  /** Construye un PerfilSocial desde el JSON del cliente. */\n  static desdeJSON(datos = {}) {\n    return new PerfilSocial(\n      datos.redSocialId ?? datos.redSocial ?? null,\n      datos.usuarioId ?? datos.usuario ?? null,\n      datos.urlPerfil ?? null\n    );\n  }\n\n  // -------------------------- Serializacion ----------------------------\n\n  /** Formato de fila para MySQL (nombres reales de las columnas). */\n  aFilaBaseDatos() {\n    return {\n      RED_SOCIAL_id: this.redSocialId,\n      USUARIO_id: this.usuarioId,\n      url_perfil: this.#urlPerfil\n    };\n  }\n\n  /** Formato JSON para el frontend. */\n  toJSON() {\n    const salida = {\n      redSocialId: this.redSocialId,\n      usuarioId: this.usuarioId,\n      urlPerfil: this.#urlPerfil,\n      nombreUsuarioPerfil: this.obtenerNombreUsuarioPerfil(),\n      claveCompuesta: this.obtenerClaveCompuesta()\n    };\n\n    // Solo agregamos los datos de la red si los tenemos cargados.\n    const nombreRed = this.obtenerNombreRed();\n    if (nombreRed !== null) {\n      salida.redSocial = this.#redSocial.toJSON();\n    }\n\n    return salida;\n  }\n}\n\nmodule.exports = PerfilSocial;\n","persona-api/models/RedSocial.js":"/**\n * models/RedSocial.js\n * ---------------------------------------------------------------------\n * ENTIDAD RedSocial -> tabla `RED_SOCIAL`.\n *\n * Es una tabla de CATALOGO (tambien llamada tabla maestra o de\n * referencia): guarda una lista cerrada de valores que el resto del\n * sistema reutiliza. Aqui: Facebook, Instagram, TikTok, LinkedIn...\n *\n * Es la clase mas simple del proyecto, perfecta para entender la\n * estructura base de un modelo antes de pasar a las relaciones.\n */\n\nclass RedSocial {\n  #id;\n  #nombre;\n  #url;\n\n  /**\n   * @param {number|null} id\n   * @param {string}      nombre  Nombre comercial: \"Instagram\".\n   * @param {string}      url     URL base: \"https://www.instagram.com\".\n   */\n  constructor(id = null, nombre, url) {\n    this.#id = id;\n    this.#nombre = nombre;\n    this.#url = url;\n  }\n\n  // ------------------------- Getters y setters -------------------------\n\n  get id() {\n    return this.#id;\n  }\n\n  set id(valor) {\n    this.#id = valor;\n  }\n\n  get nombre() {\n    return this.#nombre;\n  }\n\n  set nombre(valor) {\n    this.#nombre = valor;\n  }\n\n  get url() {\n    return this.#url;\n  }\n\n  set url(valor) {\n    this.#url = valor;\n  }\n\n  // -------------------------- Metodos de negocio ------------------------\n\n  /**\n   * Extrae el dominio de la URL: \"https://www.instagram.com\" -> \"instagram.com\"\n   *\n   * Usamos la clase URL nativa de JavaScript en lugar de cortar el\n   * texto con split(), porque entiende puertos, rutas y parametros.\n   * Va dentro de try/catch porque el constructor de URL lanza un\n   * TypeError si el texto no es una URL valida.\n   *\n   * @returns {string|null}\n   */\n  obtenerDominio() {\n    try {\n      const url = new URL(this.#url);\n\n      // hostname es \"www.instagram.com\". Quitamos el \"www.\" inicial.\n      return url.hostname.replace(/^www\\./, '');\n    } catch {\n      return null;\n    }\n  }\n\n  /**\n   * Construye la URL de un perfil concatenando la URL base con un\n   * nombre de usuario:\n   *\n   *   base \"https://www.instagram.com\" + \"adalovelace\"\n   *   -> \"https://www.instagram.com/adalovelace\"\n   *\n   * @param {string} nombreUsuario\n   * @returns {string|null}\n   */\n  construirURLPerfil(nombreUsuario) {\n    if (!this.#url || !nombreUsuario) return null;\n\n    const base = String(this.#url).replace(/\\/+$/, '');\n    const usuario = String(nombreUsuario).replace(/^\\/+/, '');\n\n    return `${base}/${usuario}`;\n  }\n\n  // ---------------------------- Fabricas -------------------------------\n\n  /** Construye una RedSocial desde una fila de MySQL. */\n  static desdeFila(fila) {\n    if (!fila) return null;\n    return new RedSocial(fila.id, fila.nombre, fila.url);\n  }\n\n  /** Construye una RedSocial desde el JSON del cliente. */\n  static desdeJSON(datos = {}) {\n    return new RedSocial(datos.id ?? null, datos.nombre, datos.url);\n  }\n\n  // -------------------------- Serializacion ----------------------------\n\n  /** Formato de fila para MySQL. */\n  aFilaBaseDatos() {\n    return {\n      nombre: this.#nombre,\n      url: this.#url\n    };\n  }\n\n  /** Formato JSON para el frontend. */\n  toJSON() {\n    return {\n      id: this.#id,\n      nombre: this.#nombre,\n      url: this.#url,\n      dominio: this.obtenerDominio()\n    };\n  }\n}\n\nmodule.exports = RedSocial;\n","persona-api/models/Telefono.js":"/**\n * models/Telefono.js\n * ---------------------------------------------------------------------\n * ENTIDAD Telefono -> tabla `TELEFONO`.\n *\n * RELACION: un USUARIO tiene MUCHOS telefonos (1 a N).\n * En la base de datos esa relacion es la columna TELEFONO.USUARIO_id,\n * que es una LLAVE FORANEA hacia USUARIO.id.\n *\n * DETALLE DE DISENIO IMPORTANTE:\n * El atributo #usuario puede guardar dos cosas distintas:\n *   a) un NUMERO: el id del usuario (lo normal, viene del formulario);\n *   b) una INSTANCIA de Usuario: cuando queremos el objeto completo.\n *\n * Para que el resto del codigo no tenga que preguntar \"que me dieron?\",\n * el getter `usuarioId` NORMALIZA los dos casos y siempre devuelve un\n * numero. Ese es el valor de tener getters: esconden la complejidad.\n */\n\nconst { ESTADO_TELEFONO, TIPOS_TELEFONO } = require('../utils/constants');\n\nclass Telefono {\n  #id;\n  #numeroTelefono;\n  #tipoTelefono;\n  #usuario;\n  #activo;\n\n  /**\n   * @param {number|null}        id\n   * @param {string}             numeroTelefono\n   * @param {string}             tipoTelefono    Celular, Fijo, Trabajo...\n   * @param {number|Usuario}     usuario         Id del usuario o la instancia.\n   * @param {number}             activo          1 activo, 0 inactivo.\n   */\n  constructor(\n    id = null,\n    numeroTelefono,\n    tipoTelefono,\n    usuario,\n    activo = ESTADO_TELEFONO.ACTIVO\n  ) {\n    this.#id = id;\n    this.#numeroTelefono = numeroTelefono;\n    this.#tipoTelefono = tipoTelefono;\n    this.#usuario = usuario;\n    this.#activo = activo;\n  }\n\n  // ------------------------- Getters y setters -------------------------\n\n  get id() {\n    return this.#id;\n  }\n\n  set id(valor) {\n    this.#id = valor;\n  }\n\n  get numeroTelefono() {\n    return this.#numeroTelefono;\n  }\n\n  set numeroTelefono(valor) {\n    this.#numeroTelefono = valor;\n  }\n\n  get tipoTelefono() {\n    return this.#tipoTelefono;\n  }\n\n  set tipoTelefono(valor) {\n    this.#tipoTelefono = valor;\n  }\n\n  /** Devuelve lo que se guardo: el id o la instancia de Usuario. */\n  get usuario() {\n    return this.#usuario;\n  }\n\n  set usuario(valor) {\n    this.#usuario = valor;\n  }\n\n  /**\n   * GETTER NORMALIZADOR: siempre devuelve el id del usuario como\n   * numero, sin importar si #usuario guarda un id o un objeto Usuario.\n   *\n   * @returns {number|null}\n   */\n  get usuarioId() {\n    if (this.#usuario === null || this.#usuario === undefined) {\n      return null;\n    }\n\n    // Caso objeto: le pedimos su id (puede ser una instancia de Usuario\n    // o un objeto plano con la propiedad id).\n    if (typeof this.#usuario === 'object') {\n      return this.#usuario.id ?? null;\n    }\n\n    // Caso valor simple: lo convertimos a numero.\n    const numero = Number(this.#usuario);\n    return Number.isInteger(numero) ? numero : null;\n  }\n\n  get activo() {\n    return this.#activo;\n  }\n\n  set activo(valor) {\n    this.#activo = valor;\n  }\n\n  // -------------------------- Metodos de negocio ------------------------\n\n  /** true si la bandera `activo` vale 1. */\n  esActivo() {\n    return this.#activo === ESTADO_TELEFONO.ACTIVO;\n  }\n\n  /** Activa el telefono. */\n  activar() {\n    this.#activo = ESTADO_TELEFONO.ACTIVO;\n    return this;\n  }\n\n  /** Desactiva el telefono sin borrar la fila (baja logica). */\n  desactivar() {\n    this.#activo = ESTADO_TELEFONO.INACTIVO;\n    return this;\n  }\n\n  /** true si el tipo pertenece al catalogo de TIPOS_TELEFONO. */\n  tieneTipoValido() {\n    return TIPOS_TELEFONO.includes(this.#tipoTelefono);\n  }\n\n  /**\n   * Version enmascarada del numero, para mostrar en pantalla sin\n   * exponer el dato completo: \"3001234567\" -> \"******4567\"\n   */\n  obtenerNumeroEnmascarado() {\n    // Requerimos el modulo aqui para que el modelo no cargue utilidades\n    // de cifrado si nadie llama a este metodo.\n    const { enmascarar } = require('../utils/cifrado');\n    return enmascarar(this.#numeroTelefono, 4);\n  }\n\n  /** Etiqueta lista para la interfaz: \"Celular: 3001234567\". */\n  obtenerEtiqueta() {\n    const tipo = this.#tipoTelefono ?? 'Telefono';\n    return `${tipo}: ${this.#numeroTelefono ?? 'sin numero'}`;\n  }\n\n  // ---------------------------- Fabricas -------------------------------\n\n  /**\n   * Construye un Telefono desde una fila de MySQL.\n   * @param {object} fila\n   * @returns {Telefono|null}\n   */\n  static desdeFila(fila) {\n    if (!fila) return null;\n\n    return new Telefono(\n      fila.id,\n      fila.numero_telefono,\n      fila.tipo_telefono,\n      fila.USUARIO_id,\n      fila.activo\n    );\n  }\n\n  /**\n   * Construye un Telefono desde el JSON del cliente.\n   * Acepta tanto `usuarioId` como `usuario` para ser tolerante con el\n   * frontend.\n   *\n   * @param {object} datos\n   * @returns {Telefono}\n   */\n  static desdeJSON(datos = {}) {\n    return new Telefono(\n      datos.id ?? null,\n      datos.numeroTelefono,\n      datos.tipoTelefono,\n      datos.usuarioId ?? datos.usuario ?? null,\n      datos.activo ?? ESTADO_TELEFONO.ACTIVO\n    );\n  }\n\n  // -------------------------- Serializacion ----------------------------\n\n  /** Formato de fila para MySQL (snake_case + nombre real de la FK). */\n  aFilaBaseDatos() {\n    return {\n      numero_telefono: this.#numeroTelefono,\n      tipo_telefono: this.#tipoTelefono,\n      USUARIO_id: this.usuarioId,\n      activo: this.#activo\n    };\n  }\n\n  /** Formato JSON para el frontend. */\n  toJSON() {\n    return {\n      id: this.#id,\n      numeroTelefono: this.#numeroTelefono,\n      numeroEnmascarado: this.obtenerNumeroEnmascarado(),\n      tipoTelefono: this.#tipoTelefono,\n      usuarioId: this.usuarioId,\n      activo: this.#activo,\n      esActivo: this.esActivo(),\n      etiqueta: this.obtenerEtiqueta()\n    };\n  }\n}\n\nmodule.exports = Telefono;\n","persona-api/models/Usuario.js":"/**\n * models/Usuario.js\n * ---------------------------------------------------------------------\n * ENTIDAD Usuario -> tabla `USUARIO` de la base de datos.\n *\n * QUE ES UN MODELO EN ESTA ARQUITECTURA?\n * Es una clase que representa una fila de la tabla como un OBJETO de\n * JavaScript. No sabe nada de SQL ni de HTTP: solo guarda datos y\n * expone comportamiento propio del dominio.\n *\n * LOS CUATRO PILARES DE LA POO, APLICADOS AQUI:\n *\n *  1. ABSTRACCION    -> la clase describe que ES un usuario, sin\n *                       detalles de como se guarda.\n *  2. ENCAPSULAMIENTO-> los atributos llevan # (privados). Solo se\n *                       acceden por getters y setters. Nadie puede\n *                       hacer usuario.#edad = -5 desde afuera.\n *  3. HERENCIA       -> no se usa en esta clase (ver utils/AppError.js,\n *                       que si hereda de Error).\n *  4. POLIMORFISMO   -> toJSON() es el ejemplo: JSON.stringify() lo\n *                       llama automaticamente, sin saber que clase es.\n *\n * POR QUE PRIVADOS CON # Y NO _nombre?\n * El guion bajo es solo una CONVENCION: nada impide tocar el atributo.\n * El numeral # es sintaxis real de JavaScript: si intentas leerlo\n * desde afuera, el programa lanza un SyntaxError. Es privacidad de\n * verdad, verificada por el motor del lenguaje.\n */\n\nconst fechas = require('../utils/fechas');\nconst { ESTADO_USUARIO } = require('../utils/constants');\n\nclass Usuario {\n  // ---- Declaracion de atributos privados ----\n  // Se declaran arriba, fuera del constructor, para que la clase\n  // documente de un vistazo que datos maneja.\n  #id;\n  #primerNombre;\n  #segundoNombre;\n  #primerApellido;\n  #segundoApellido;\n  #fechaNacimiento;\n  #edad;\n  #ciudadDomicilio;\n  #estado;\n  #telefonos;\n  #perfilesSociales;\n\n  // Conteos de las relaciones.\n  //\n  // Por que guardar un conteo si ya tenemos los arreglos?\n  // Porque el LISTADO (GET /api/usuarios) no carga las relaciones\n  // completas: seria carisimo traer los telefonos de 50 usuarios solo\n  // para mostrar un numero. En su lugar, la consulta del listado trae\n  // los conteos con una SUBCONSULTA CORRELACIONADA y los guardamos\n  // aqui. El DETALLE (GET /api/usuarios/:id) si carga los arreglos.\n  #totalTelefonos;\n  #totalPerfilesSociales;\n\n  /**\n   * @param {number|null} id                Null cuando el usuario aun no se guardo.\n   * @param {string}      primerNombre\n   * @param {string|null} segundoNombre\n   * @param {string}      primerApellido\n   * @param {string|null} segundoApellido\n   * @param {string}      fechaNacimiento   Formato AAAA-MM-DD.\n   * @param {number}      edad              Anios cumplidos.\n   * @param {string}      ciudadDomicilio\n   * @param {number}      estado            1 activo, 0 inactivo.\n   */\n  constructor(\n    id = null,\n    primerNombre,\n    segundoNombre = null,\n    primerApellido,\n    segundoApellido = null,\n    fechaNacimiento,\n    edad,\n    ciudadDomicilio,\n    estado = ESTADO_USUARIO.ACTIVO\n  ) {\n    this.#id = id;\n    this.#primerNombre = primerNombre;\n    this.#segundoNombre = segundoNombre;\n    this.#primerApellido = primerApellido;\n    this.#segundoApellido = segundoApellido;\n    this.#fechaNacimiento = fechaNacimiento;\n    this.#edad = edad;\n    this.#ciudadDomicilio = ciudadDomicilio;\n    this.#estado = estado;\n\n    // Colecciones de las relaciones. Arrancan vacias y se llenan con\n    // agregarTelefono() / agregarPerfilSocial().\n    this.#telefonos = [];\n    this.#perfilesSociales = [];\n\n    // 0 hasta que el listado los informe o se carguen las relaciones.\n    this.#totalTelefonos = 0;\n    this.#totalPerfilesSociales = 0;\n  }\n\n  // =====================================================================\n  // GETTERS Y SETTERS\n  // ---------------------------------------------------------------------\n  // Un getter se LEE como una propiedad: usuario.primerNombre\n  // (sin parentesis), aunque por dentro sea un metodo.\n  //\n  // Los setters son el lugar natural para normalizar y proteger el\n  // estado del objeto. Mira el setter de fechaNacimiento: recalcula la\n  // edad solo. Asi es IMPOSIBLE que el objeto quede inconsistente.\n  // =====================================================================\n\n  get id() {\n    return this.#id;\n  }\n\n  set id(valor) {\n    this.#id = valor;\n  }\n\n  get primerNombre() {\n    return this.#primerNombre;\n  }\n\n  set primerNombre(valor) {\n    this.#primerNombre = valor;\n  }\n\n  get segundoNombre() {\n    return this.#segundoNombre;\n  }\n\n  set segundoNombre(valor) {\n    this.#segundoNombre = valor;\n  }\n\n  get primerApellido() {\n    return this.#primerApellido;\n  }\n\n  set primerApellido(valor) {\n    this.#primerApellido = valor;\n  }\n\n  get segundoApellido() {\n    return this.#segundoApellido;\n  }\n\n  set segundoApellido(valor) {\n    this.#segundoApellido = valor;\n  }\n\n  get fechaNacimiento() {\n    // Siempre devolvemos el formato ISO corto, sin importar si por\n    // dentro era un Date (MySQL) o un texto (JSON del cliente).\n    return fechas.aFechaISO(this.#fechaNacimiento);\n  }\n\n  /**\n   * Al cambiar la fecha de nacimiento, la edad se RECALCULA sola.\n   * Esta es la ventaja concreta de usar setters en lugar de atributos\n   * publicos: la regla de negocio vive dentro del objeto.\n   */\n  set fechaNacimiento(valor) {\n    this.#fechaNacimiento = valor;\n\n    const edadCalculada = fechas.calcularEdad(valor);\n    if (edadCalculada !== null) {\n      this.#edad = edadCalculada;\n    }\n  }\n\n  get edad() {\n    return this.#edad;\n  }\n\n  /**\n   * El setter de edad existe para cargar datos que ya vienen de la\n   * base. En el flujo normal la edad NO se asigna a mano: se deriva\n   * de fechaNacimiento (ver el setter de arriba y recalcularEdad()).\n   */\n  set edad(valor) {\n    this.#edad = valor;\n  }\n\n  get ciudadDomicilio() {\n    return this.#ciudadDomicilio;\n  }\n\n  set ciudadDomicilio(valor) {\n    this.#ciudadDomicilio = valor;\n  }\n\n  get estado() {\n    return this.#estado;\n  }\n\n  set estado(valor) {\n    this.#estado = valor;\n  }\n\n  /**\n   * Devuelve una COPIA del arreglo de telefonos.\n   *\n   * Por que una copia y no el arreglo original?\n   * Porque si devolvieramos la referencia, cualquiera podria hacer\n   * `usuario.telefonos.push(basura)` y romper el encapsulamiento sin\n   * pasar por agregarTelefono(). Devolver [...copia] protege el estado.\n   */\n  get telefonos() {\n    return [...this.#telefonos];\n  }\n\n  get perfilesSociales() {\n    return [...this.#perfilesSociales];\n  }\n\n  /**\n   * Cantidad de telefonos del usuario.\n   *\n   * Si las relaciones estan cargadas (vista de detalle), el valor real\n   * es la longitud del arreglo. Si no (vista de listado), devolvemos el\n   * conteo que trajo la subconsulta. Un solo getter cubre los dos casos\n   * y quien lo use no tiene que saber de donde viene el dato: eso es\n   * encapsulamiento.\n   */\n  get totalTelefonos() {\n    return this.#telefonos.length > 0 ? this.#telefonos.length : this.#totalTelefonos;\n  }\n\n  set totalTelefonos(valor) {\n    this.#totalTelefonos = Number(valor) || 0;\n  }\n\n  /** Cantidad de perfiles sociales del usuario. */\n  get totalPerfilesSociales() {\n    return this.#perfilesSociales.length > 0\n      ? this.#perfilesSociales.length\n      : this.#totalPerfilesSociales;\n  }\n\n  set totalPerfilesSociales(valor) {\n    this.#totalPerfilesSociales = Number(valor) || 0;\n  }\n\n  // =====================================================================\n  // METODOS DE NEGOCIO\n  // Comportamiento que pertenece al usuario mismo, no a la base de datos.\n  // =====================================================================\n\n  /**\n   * Arma el nombre completo omitiendo los campos que son null.\n   *\n   *   \"Grace\", \"Brewster\", \"Hopper\", \"Murray\" -> \"Grace Brewster Hopper Murray\"\n   *   \"Alan\", null, \"Turing\", null            -> \"Alan Turing\"\n   *\n   * @returns {string}\n   */\n  obtenerNombreCompleto() {\n    // Metemos las cuatro partes en un arreglo y filtramos las vacias.\n    // Boolean como funcion de filtro descarta null, undefined y \"\".\n    return [\n      this.#primerNombre,\n      this.#segundoNombre,\n      this.#primerApellido,\n      this.#segundoApellido\n    ]\n      .filter(Boolean)\n      .join(' ');\n  }\n\n  /** Apellidos concatenados, utiles para ordenar listados. */\n  obtenerApellidos() {\n    return [this.#primerApellido, this.#segundoApellido].filter(Boolean).join(' ');\n  }\n\n  /** true si el usuario esta activo (columna estado = 1). */\n  estaActivo() {\n    return this.#estado === ESTADO_USUARIO.ACTIVO;\n  }\n\n  /** Marca el usuario como activo. */\n  activar() {\n    this.#estado = ESTADO_USUARIO.ACTIVO;\n  }\n\n  /** Marca el usuario como inactivo (baja logica, no se borra la fila). */\n  desactivar() {\n    this.#estado = ESTADO_USUARIO.INACTIVO;\n  }\n\n  /**\n   * Fuerza el recalculo de la edad desde la fecha de nacimiento.\n   * El service la llama antes de cada INSERT y cada UPDATE para que la\n   * columna `edad` nunca mienta.\n   *\n   * @returns {number} La edad recalculada.\n   */\n  recalcularEdad() {\n    const edadCalculada = fechas.calcularEdad(this.#fechaNacimiento);\n\n    // El operador ?? (nullish coalescing) usa el lado derecho solo si\n    // el izquierdo es null o undefined. A diferencia de ||, el valor 0\n    // SI se considera valido, lo cual importa con edades de bebes.\n    this.#edad = edadCalculada ?? 0;\n\n    return this.#edad;\n  }\n\n  /** Agrega un objeto Telefono a la coleccion interna. */\n  agregarTelefono(telefono) {\n    this.#telefonos.push(telefono);\n\n    // Mantenemos el conteo sincronizado con el arreglo. Que el objeto\n    // cuide su propia consistencia es la razon de ser de los metodos:\n    // nadie de afuera puede dejar el estado a medias.\n    this.#totalTelefonos = this.#telefonos.length;\n\n    return this;\n  }\n\n  /** Agrega un objeto PerfilSocial a la coleccion interna. */\n  agregarPerfilSocial(perfilSocial) {\n    this.#perfilesSociales.push(perfilSocial);\n    this.#totalPerfilesSociales = this.#perfilesSociales.length;\n    return this;\n  }\n\n  /** Solo los telefonos cuya bandera `activo` es 1. */\n  obtenerTelefonosActivos() {\n    return this.#telefonos.filter((telefono) => telefono.esActivo());\n  }\n\n  /** Fecha de nacimiento en texto legible: \"9 de diciembre de 1906\". */\n  obtenerFechaNacimientoLarga() {\n    return fechas.aTextoLargo(this.#fechaNacimiento);\n  }\n\n  // =====================================================================\n  // METODOS ESTATICOS (de fabrica)\n  // ---------------------------------------------------------------------\n  // Un metodo `static` pertenece a la CLASE, no a las instancias:\n  //    Usuario.desdeFila(fila)   <- correcto\n  //    miUsuario.desdeFila(fila) <- NO existe\n  //\n  // Los usamos como \"constructores con nombre\". El constructor de esta\n  // clase recibe 9 parametros en orden; equivocarse de posicion es muy\n  // facil. Estas fabricas reciben un OBJETO con nombres y arman la\n  // instancia por nosotros.\n  // =====================================================================\n\n  /**\n   * Construye un Usuario a partir de una fila de MySQL.\n   * Traduce snake_case (primer_nombre) a camelCase (primerNombre).\n   *\n   * Este metodo es el \"mapeador\" entre el mundo de la base de datos y\n   * el mundo de los objetos.\n   *\n   * @param {object} fila  Fila devuelta por el driver mysql2.\n   * @returns {Usuario|null}\n   */\n  static desdeFila(fila) {\n    if (!fila) return null;\n\n    const usuario = new Usuario(\n      fila.id,\n      fila.primer_nombre,\n      fila.segundo_nombre,\n      fila.primer_apellido,\n      fila.segundo_apellido,\n      fechas.aFechaISO(fila.fecha_nacimiento),\n      fila.edad,\n      fila.ciudad_domicilio,\n      fila.estado\n    );\n\n    // Columnas que solo llegan en el listado, desde las subconsultas\n    // correlacionadas. En el detalle no vienen, y entonces los\n    // conteos se deducen de los arreglos ya cargados.\n    if (fila.total_telefonos !== undefined) {\n      usuario.totalTelefonos = fila.total_telefonos;\n    }\n\n    if (fila.total_perfiles_sociales !== undefined) {\n      usuario.totalPerfilesSociales = fila.total_perfiles_sociales;\n    }\n\n    return usuario;\n  }\n\n  /**\n   * Construye un Usuario a partir del JSON que envia el cliente\n   * (req.body ya normalizado por el service).\n   *\n   * @param {object} datos  Objeto con llaves en camelCase.\n   * @returns {Usuario}\n   */\n  static desdeJSON(datos = {}) {\n    return new Usuario(\n      datos.id ?? null,\n      datos.primerNombre,\n      datos.segundoNombre ?? null,\n      datos.primerApellido,\n      datos.segundoApellido ?? null,\n      datos.fechaNacimiento,\n      datos.edad,\n      datos.ciudadDomicilio,\n      datos.estado ?? ESTADO_USUARIO.ACTIVO\n    );\n  }\n\n  // =====================================================================\n  // SERIALIZACION\n  // =====================================================================\n\n  /**\n   * Convierte el objeto al formato de FILA que espera MySQL\n   * (llaves en snake_case, fecha como DATETIME).\n   *\n   * Nota: no incluimos el `id` porque es AUTO_INCREMENT en el INSERT\n   * y porque en el UPDATE viaja aparte, en el WHERE.\n   *\n   * @returns {object}\n   */\n  aFilaBaseDatos() {\n    return {\n      primer_nombre: this.#primerNombre,\n      segundo_nombre: this.#segundoNombre,\n      primer_apellido: this.#primerApellido,\n      segundo_apellido: this.#segundoApellido,\n      fecha_nacimiento: fechas.aFechaMySQL(this.#fechaNacimiento),\n      edad: this.#edad,\n      ciudad_domicilio: this.#ciudadDomicilio,\n      estado: this.#estado\n    };\n  }\n\n  /**\n   * Convierte el objeto al JSON que viaja al frontend.\n   *\n   * JSON.stringify() busca y llama este metodo de forma automatica.\n   * Gracias a eso, el controlador puede hacer simplemente\n   * res.json(usuario) y los atributos PRIVADOS se publican de forma\n   * controlada: nosotros decidimos exactamente que sale y que no.\n   *\n   * @returns {object}\n   */\n  toJSON() {\n    return {\n      id: this.#id,\n      primerNombre: this.#primerNombre,\n      segundoNombre: this.#segundoNombre,\n      primerApellido: this.#primerApellido,\n      segundoApellido: this.#segundoApellido,\n      nombreCompleto: this.obtenerNombreCompleto(),\n      fechaNacimiento: this.fechaNacimiento,\n      fechaNacimientoTexto: this.obtenerFechaNacimientoLarga(),\n      edad: this.#edad,\n      ciudadDomicilio: this.#ciudadDomicilio,\n      estado: this.#estado,\n      activo: this.estaActivo(),\n\n      // Conteos: el frontend los usa en las columnas del listado y en\n      // el aviso de consecuencias del dialogo de eliminacion.\n      totalTelefonos: this.totalTelefonos,\n      totalPerfilesSociales: this.totalPerfilesSociales,\n\n      // Las relaciones se serializan en cascada: cada Telefono y cada\n      // PerfilSocial tiene su propio toJSON().\n      telefonos: this.#telefonos.map((telefono) => telefono.toJSON()),\n      perfilesSociales: this.#perfilesSociales.map((perfil) => perfil.toJSON())\n    };\n  }\n}\n\nmodule.exports = Usuario;\n","persona-api/models/index.js":"/**\n * models/index.js\n * ---------------------------------------------------------------------\n * \"Barrel file\" (archivo barril): reexporta todos los modelos desde un\n * solo punto de entrada.\n *\n * Sin el, cada service necesitaria varias lineas de require:\n *   const Usuario  = require('../models/Usuario');\n *   const Telefono = require('../models/Telefono');\n *\n * Con el, basta una:\n *   const { Usuario, Telefono } = require('../models');\n *\n * Nota: require('../models') encuentra este archivo solo porque se\n * llama index.js. Es la convencion de Node.js para el archivo\n * principal de una carpeta.\n */\n\nconst Usuario = require('./Usuario');\nconst Telefono = require('./Telefono');\nconst RedSocial = require('./RedSocial');\nconst PerfilSocial = require('./PerfilSocial');\n\nmodule.exports = {\n  Usuario,\n  Telefono,\n  RedSocial,\n  PerfilSocial\n};\n","persona-api/package.json":"{\n  \"name\": \"persona-api\",\n  \"version\": \"1.0.0\",\n  \"description\": \"API REST para gestionar usuarios, telefonos, redes sociales y perfiles sociales. Proyecto formativo SENA.\",\n  \"main\": \"index.js\",\n  \"type\": \"commonjs\",\n  \"scripts\": {\n    \"start\": \"node index.js\",\n    \"dev\": \"node --watch index.js\",\n    \"db:schema\": \"mysql -u root -p < database/01_schema.sql\",\n    \"db:user\": \"mysql -u root -p < database/02_usuario_app.sql\",\n    \"db:seed\": \"mysql -u root -p < database/03_datos_prueba.sql\"\n  },\n  \"keywords\": [\n    \"api-rest\",\n    \"express\",\n    \"mysql\",\n    \"poo\",\n    \"sena\"\n  ],\n  \"author\": \"SENA - Ficha 3489088\",\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"cors\": \"^2.8.6\",\n    \"dotenv\": \"^18.0.7\",\n    \"express\": \"^5.3.0\",\n    \"mysql2\": \"^3.24.5\"\n  }\n}\n","persona-api/routes/index.js":"/**\n * routes/index.js\n * ---------------------------------------------------------------------\n * ENRUTADOR PRINCIPAL: junta todos los routers en un solo lugar y les\n * asigna su prefijo de URL.\n *\n * Gracias a este archivo, config/express.js solo necesita UNA linea\n * (app.use('/api', rutas)) en lugar de cuatro. Si manana agregas la\n * entidad \"Direccion\", la registras aqui y nada mas.\n *\n * COMO FUNCIONA router.use(prefijo, otroRouter)?\n * Monta un router hijo bajo un prefijo. La URL final es la suma de los\n * prefijos de toda la cadena:\n *\n *     app.use('/api', rutas)                      -> /api\n *       router.use('/usuarios', usuarioRoutes)    -> /api/usuarios\n *         router.get('/:id', ...)                 -> /api/usuarios/:id\n */\n\nconst express = require('express');\n\nconst usuarioRoutes = require('./usuario.routes');\nconst telefonoRoutes = require('./telefono.routes');\nconst redSocialRoutes = require('./redSocial.routes');\nconst perfilSocialRoutes = require('./perfilSocial.routes');\n\nconst db = require('../config/database');\nconst respuesta = require('../utils/respuesta');\nconst { capturarAsync } = require('../middleware/errorHandler');\nconst { ahoraISO } = require('../utils/fechas');\n\nconst router = express.Router();\n\n// ---------------------------------------------------------------------\n// GET /api  -> Documento de descubrimiento (discovery document)\n// ---------------------------------------------------------------------\n// Una buena API REST se describe a si misma: al entrar a la raiz,\n// devuelve la lista de recursos disponibles. Asi quien la consume no\n// tiene que adivinar las URL.\nrouter.get('/', (req, res) => {\n  return respuesta.exito(res, {\n    mensaje: 'API REST Personal Management. Estos son los recursos disponibles.',\n    datos: {\n      nombre: 'persona-api',\n      version: '1.0.0',\n      recursos: {\n        usuarios: '/api/usuarios',\n        telefonos: '/api/telefonos',\n        redesSociales: '/api/redes-sociales',\n        perfilesSociales: '/api/perfiles-sociales'\n      },\n      utilidades: {\n        estadoSalud: '/api/salud'\n      }\n    }\n  });\n});\n\n// ---------------------------------------------------------------------\n// GET /api/salud  -> Health check\n// ---------------------------------------------------------------------\n// Endpoint de monitoreo: verifica que la API responde Y que la base de\n// datos esta accesible. En produccion lo consultan los balanceadores\n// de carga para decidir si el servidor esta sano o hay que reiniciarlo.\nrouter.get(\n  '/salud',\n  capturarAsync(async (req, res) => {\n    // Si MySQL esta caido, verificarConexion lanza y el middleware de\n    // errores responde 500 con un mensaje claro.\n    await db.verificarConexion();\n\n    return respuesta.exito(res, {\n      mensaje: 'La API y la base de datos estan operativas.',\n      datos: {\n        api: 'activa',\n        baseDatos: db.estaConectada ? 'conectada' : 'desconectada',\n\n        // process.uptime() son los segundos que lleva corriendo el proceso.\n        tiempoActivoSegundos: Math.floor(process.uptime()),\n        marcaTiempo: ahoraISO()\n      }\n    });\n  })\n);\n\n// ---------------------------------------------------------------------\n// Montaje de los routers de cada entidad\n// ---------------------------------------------------------------------\nrouter.use('/usuarios', usuarioRoutes);\nrouter.use('/telefonos', telefonoRoutes);\nrouter.use('/redes-sociales', redSocialRoutes);\nrouter.use('/perfiles-sociales', perfilSocialRoutes);\n\nmodule.exports = router;\n","persona-api/routes/perfilSocial.routes.js":"/**\n * routes/perfilSocial.routes.js\n * ---------------------------------------------------------------------\n * CAPA DE RUTAS de la entidad PerfilSocial (llave compuesta).\n *\n * TABLA DE ENDPOINTS\n * ---------------------------------------------------------------------\n * GET    /api/perfiles-sociales                            Lista\n * GET    /api/perfiles-sociales/:redSocialId/:usuarioId    Detalle\n * POST   /api/perfiles-sociales                            Crear\n * PUT    /api/perfiles-sociales/:redSocialId/:usuarioId    Actualizar urlPerfil\n * DELETE /api/perfiles-sociales/:redSocialId/:usuarioId    Eliminar\n * ---------------------------------------------------------------------\n *\n * COMO SE EXPRESA UNA LLAVE COMPUESTA EN UNA URL REST?\n * Con los dos valores como segmentos consecutivos, en el mismo orden\n * de la PRIMARY KEY de la tabla:\n *\n *     PRIMARY KEY (RED_SOCIAL_id, USUARIO_id)\n *          ->  /api/perfiles-sociales/4/3\n *\n * Y se registra validarIdNumerico DOS veces, una por parametro. Los\n * middlewares se ejecutan en cadena y de izquierda a derecha, asi que\n * cuando el controlador toma el control ya tiene los dos id validados\n * y convertidos a numero en req.idsValidados.\n */\n\nconst express = require('express');\n\nconst perfilSocialController = require('../controllers/perfilSocial.controller');\nconst { validarIdNumerico, exigirCuerpo } = require('../middleware/validarParametros');\n\nconst router = express.Router();\n\n// ---- Coleccion ----\nrouter.get('/', perfilSocialController.listar);\nrouter.post('/', exigirCuerpo, perfilSocialController.crear);\n\n// ---- Recurso individual con LLAVE COMPUESTA ----\nrouter.get(\n  '/:redSocialId/:usuarioId',\n  validarIdNumerico('redSocialId'),\n  validarIdNumerico('usuarioId'),\n  perfilSocialController.obtener\n);\n\nrouter.put(\n  '/:redSocialId/:usuarioId',\n  validarIdNumerico('redSocialId'),\n  validarIdNumerico('usuarioId'),\n  exigirCuerpo,\n  perfilSocialController.actualizar\n);\n\nrouter.delete(\n  '/:redSocialId/:usuarioId',\n  validarIdNumerico('redSocialId'),\n  validarIdNumerico('usuarioId'),\n  perfilSocialController.eliminar\n);\n\nmodule.exports = router;\n","persona-api/routes/usuario.routes.js":"/**\n * routes/usuario.routes.js\n * ---------------------------------------------------------------------\n * CAPA DE RUTAS de la entidad Usuario.\n *\n * QUE HACE UNA RUTA?\n * Declara el CONTRATO de la API: que verbo HTTP + que URL ejecuta que\n * controlador, y por que middlewares pasa antes.\n *\n * Es la \"tabla de contenido\" de la API. Cualquiera puede abrir este\n * archivo y saber en 20 segundos todo lo que la API permite hacer con\n * los usuarios.\n *\n * express.Router() crea un mini-aplicacion de rutas que luego se monta\n * en un prefijo. Al montarlo en '/api/usuarios', la ruta '/' de aqui\n * se convierte en '/api/usuarios'.\n *\n * EL ORDEN DE LAS RUTAS IMPORTA\n * Express evalua de arriba hacia abajo y se detiene en la PRIMERA que\n * coincide. Por eso las rutas mas especificas van ANTES de las\n * genericas. Si pusieramos '/:id' antes de '/:id/telefonos', la\n * peticion a /api/usuarios/5/telefonos nunca llegaria a su destino.\n *\n * TABLA DE ENDPOINTS\n * ---------------------------------------------------------------------\n * GET    /api/usuarios                       Lista con filtros y paginacion\n * GET    /api/usuarios/:id                   Detalle con relaciones\n * GET    /api/usuarios/:id/telefonos         Telefonos del usuario\n * GET    /api/usuarios/:id/perfiles-sociales Perfiles sociales del usuario\n * POST   /api/usuarios                       Crear usuario\n * POST   /api/usuarios/:id/telefonos         Crear telefono del usuario\n * POST   /api/usuarios/:id/perfiles-sociales Crear perfil del usuario\n * PUT    /api/usuarios/:id                   Actualizar usuario\n * DELETE /api/usuarios/:id                   Eliminar usuario y sus hijos\n * ---------------------------------------------------------------------\n */\n\nconst express = require('express');\n\nconst usuarioController = require('../controllers/usuario.controller');\nconst telefonoController = require('../controllers/telefono.controller');\nconst perfilSocialController = require('../controllers/perfilSocial.controller');\nconst { validarIdNumerico, exigirCuerpo } = require('../middleware/validarParametros');\n\nconst router = express.Router();\n\n// ---------------------------------------------------------------------\n// Coleccion: /api/usuarios\n// ---------------------------------------------------------------------\n\n// GET /api/usuarios\nrouter.get('/', usuarioController.listar);\n\n// POST /api/usuarios\n// exigirCuerpo corre ANTES del controlador y rechaza los cuerpos vacios.\nrouter.post('/', exigirCuerpo, usuarioController.crear);\n\n// ---------------------------------------------------------------------\n// Subrecursos (van ANTES de '/:id' por el orden de evaluacion)\n// ---------------------------------------------------------------------\n\n// GET /api/usuarios/:id/telefonos\nrouter.get('/:id/telefonos', validarIdNumerico('id'), telefonoController.listarPorUsuario);\n\n// POST /api/usuarios/:id/telefonos\nrouter.post(\n  '/:id/telefonos',\n  validarIdNumerico('id'),\n  exigirCuerpo,\n  telefonoController.crearParaUsuario\n);\n\n// GET /api/usuarios/:id/perfiles-sociales\nrouter.get(\n  '/:id/perfiles-sociales',\n  validarIdNumerico('id'),\n  perfilSocialController.listarPorUsuario\n);\n\n// POST /api/usuarios/:id/perfiles-sociales\nrouter.post(\n  '/:id/perfiles-sociales',\n  validarIdNumerico('id'),\n  exigirCuerpo,\n  perfilSocialController.crearParaUsuario\n);\n\n// ---------------------------------------------------------------------\n// Recurso individual: /api/usuarios/:id\n// ---------------------------------------------------------------------\n\n// GET /api/usuarios/:id\nrouter.get('/:id', validarIdNumerico('id'), usuarioController.obtener);\n\n// PUT /api/usuarios/:id\nrouter.put('/:id', validarIdNumerico('id'), exigirCuerpo, usuarioController.actualizar);\n\n// DELETE /api/usuarios/:id\nrouter.delete('/:id', validarIdNumerico('id'), usuarioController.eliminar);\n\nmodule.exports = router;\n","persona-api/services/perfilSocial.service.js":"/**\n * services/perfilSocial.service.js\n * ---------------------------------------------------------------------\n * CAPA DE SERVICIO de la entidad PerfilSocial (tabla puente N:N).\n *\n * ESTE ES EL SERVICIO MAS INTERESANTE. Dos cosas lo hacen distinto a\n * los anteriores:\n *\n * 1. LA LLAVE PRIMARIA ES COMPUESTA: (RED_SOCIAL_id, USUARIO_id).\n *    Consecuencias practicas en TODO el CRUD:\n *      - obtenerPorId recibe DOS parametros, no uno.\n *      - el WHERE siempre lleva las dos columnas:\n *          WHERE RED_SOCIAL_id = ? AND USUARIO_id = ?\n *      - la URL del recurso tiene dos segmentos:\n *          /api/perfiles-sociales/:redSocialId/:usuarioId\n *\n * 2. VALIDA DOS LLAVES FORANEAS antes de insertar: el usuario y la red\n *    social tienen que existir las dos.\n *\n * Y una regla de negocio importante: en un PUT NO se permite cambiar\n * la llave compuesta. Cambiar la identidad de un recurso no es una\n * actualizacion, es un borrado mas una creacion. Lo unico actualizable\n * aqui es `url_perfil`.\n */\n\nconst db = require('../config/database');\nconst { PerfilSocial } = require('../models');\nconst usuarioService = require('./usuario.service');\nconst redSocialService = require('./redSocial.service');\n\nconst formato = require('../utils/formato');\nconst AppError = require('../utils/AppError');\nconst MENSAJES = require('../utils/mensajes');\nconst { ColectorErrores } = require('../utils/validadores');\nconst { LIMITES } = require('../utils/constants');\n\nclass PerfilSocialService {\n  // En la creacion aceptamos las dos llaves y la URL.\n  #camposPermitidos = ['redSocialId', 'usuarioId', 'urlPerfil'];\n\n  // En la actualizacion SOLO la URL: la llave compuesta es inmutable.\n  #camposActualizables = ['urlPerfil'];\n\n  /**\n   * SELECT con JOIN a las dos tablas padre.\n   *\n   * Por que un JOIN y no tres consultas separadas?\n   * Porque una sola consulta a MySQL es mucho mas rapida que tres\n   * viajes de ida y vuelta por la red. Los alias red_nombre, red_url,\n   * usuario_* los lee PerfilSocial.desdeFila() para armar los objetos\n   * relacionados.\n   */\n  #selectConJoin = `\n    SELECT  ps.RED_SOCIAL_id,\n            ps.USUARIO_id,\n            ps.url_perfil,\n            rs.nombre            AS red_nombre,\n            rs.url               AS red_url,\n            u.primer_nombre      AS usuario_primer_nombre,\n            u.primer_apellido    AS usuario_primer_apellido\n    FROM    PERFIL_SOCIAL ps\n    INNER JOIN RED_SOCIAL rs ON rs.id = ps.RED_SOCIAL_id\n    INNER JOIN USUARIO    u  ON u.id  = ps.USUARIO_id\n  `;\n\n  // ------------------------- Metodos privados --------------------------\n\n  #normalizar(datosCrudos, camposPermitidos = this.#camposPermitidos) {\n    const filtrados = formato.soloCamposPermitidos(datosCrudos, camposPermitidos);\n    const limpios = {};\n\n    if (Object.hasOwn(filtrados, 'redSocialId')) {\n      limpios.redSocialId = formato.aEnteroONulo(filtrados.redSocialId);\n    }\n\n    if (Object.hasOwn(filtrados, 'usuarioId')) {\n      limpios.usuarioId = formato.aEnteroONulo(filtrados.usuarioId);\n    }\n\n    if (Object.hasOwn(filtrados, 'urlPerfil')) {\n      limpios.urlPerfil = formato.normalizarURL(filtrados.urlPerfil);\n    }\n\n    return limpios;\n  }\n\n  #validarCreacion(datos) {\n    const errores = new ColectorErrores();\n\n    // Las dos mitades de la llave compuesta son obligatorias.\n    errores.exigirId('redSocialId', datos.redSocialId);\n    errores.exigirId('usuarioId', datos.usuarioId);\n\n    // url_perfil es NULL en el modelo, asi que es opcional.\n    errores.exigirURL('urlPerfil', datos.urlPerfil, {\n      requerido: false,\n      maximo: LIMITES.VARCHAR_CORTO\n    });\n\n    errores.lanzarSiHay('No se pudo crear el perfil social porque hay datos invalidos.');\n  }\n\n  #validarActualizacion(datos) {\n    if (formato.estaVacio(datos)) {\n      throw AppError.validacion(\n        'Solo se puede actualizar el campo \"urlPerfil\" de un perfil social.',\n        [\n          {\n            campo: 'cuerpo',\n            mensaje:\n              'La llave compuesta (redSocialId, usuarioId) identifica el recurso y no se puede cambiar. ' +\n              'Si necesitas moverlo, elimina el perfil y crea uno nuevo.'\n          }\n        ]\n      );\n    }\n\n    const errores = new ColectorErrores();\n\n    errores.exigirURL('urlPerfil', datos.urlPerfil, {\n      requerido: false,\n      maximo: LIMITES.VARCHAR_CORTO\n    });\n\n    errores.lanzarSiHay('No se pudo actualizar el perfil social porque hay datos invalidos.');\n  }\n\n  /**\n   * Verifica que EXISTAN las dos filas padre.\n   *\n   * Promise.all lanza las dos consultas en paralelo. Si el usuario no\n   * existe Y la red tampoco, informamos del usuario primero porque es\n   * el error mas probable en un formulario.\n   */\n  async #verificarLlavesForaneas(redSocialId, usuarioId) {\n    const [existeUsuario, existeRed] = await Promise.all([\n      usuarioService.existe(usuarioId),\n      redSocialService.existe(redSocialId)\n    ]);\n\n    if (!existeUsuario) {\n      throw AppError.noEncontrado(MENSAJES.NEGOCIO.USUARIO_NO_EXISTE(usuarioId));\n    }\n\n    if (!existeRed) {\n      throw AppError.noEncontrado(MENSAJES.NEGOCIO.RED_SOCIAL_NO_EXISTE(redSocialId));\n    }\n  }\n\n  /**\n   * Verifica que la llave compuesta no exista ya.\n   *\n   * Nota: MySQL tambien lo impide por la PRIMARY KEY, pero asi\n   * devolvemos 409 con un mensaje claro en vez del ER_DUP_ENTRY crudo.\n   */\n  async #verificarNoDuplicado(redSocialId, usuarioId) {\n    const fila = await db.obtenerUno(\n      `SELECT 1 AS existe\n       FROM PERFIL_SOCIAL\n       WHERE RED_SOCIAL_id = ? AND USUARIO_id = ?`,\n      [redSocialId, usuarioId]\n    );\n\n    if (fila !== null) {\n      throw AppError.conflicto(\n        MENSAJES.NEGOCIO.PERFIL_DUPLICADO(redSocialId, usuarioId)\n      );\n    }\n  }\n\n  // --------------------------- CRUD publico ----------------------------\n\n  /** READ (lista) con filtros y paginacion. */\n  async listar(filtros = {}) {\n    const pagina = Math.max(1, formato.aEnteroONulo(filtros.pagina) ?? LIMITES.PAGINA_DEFECTO);\n    const limite = Math.min(\n      Math.max(1, formato.aEnteroONulo(filtros.limite) ?? LIMITES.LIMITE_DEFECTO),\n      LIMITES.LIMITE_MAXIMO\n    );\n    const desplazamiento = (pagina - 1) * limite;\n\n    const condiciones = [];\n    const parametros = [];\n\n    const usuarioId = formato.aEnteroONulo(filtros.usuarioId);\n    if (usuarioId !== null) {\n      condiciones.push('ps.USUARIO_id = ?');\n      parametros.push(usuarioId);\n    }\n\n    const redSocialId = formato.aEnteroONulo(filtros.redSocialId);\n    if (redSocialId !== null) {\n      condiciones.push('ps.RED_SOCIAL_id = ?');\n      parametros.push(redSocialId);\n    }\n\n    const clausulaWhere = condiciones.length > 0 ? `WHERE ${condiciones.join(' AND ')}` : '';\n\n    // El conteo tambien necesita los JOIN, porque los filtros podrian\n    // apoyarse en columnas de las tablas relacionadas.\n    const filaTotal = await db.obtenerUno(\n      `SELECT COUNT(*) AS total\n       FROM PERFIL_SOCIAL ps\n       INNER JOIN RED_SOCIAL rs ON rs.id = ps.RED_SOCIAL_id\n       INNER JOIN USUARIO    u  ON u.id  = ps.USUARIO_id\n       ${clausulaWhere}`,\n      parametros\n    );\n    const total = Number(filaTotal?.total ?? 0);\n\n    const filas = await db.ejecutar(\n      `${this.#selectConJoin}\n       ${clausulaWhere}\n       ORDER BY u.primer_apellido, rs.nombre\n       LIMIT ? OFFSET ?`,\n      [...parametros, limite, desplazamiento]\n    );\n\n    return {\n      perfilesSociales: filas.map((fila) => PerfilSocial.desdeFila(fila)),\n      total,\n      pagina,\n      limite\n    };\n  }\n\n  /**\n   * READ (detalle) por LLAVE COMPUESTA.\n   * Observa que recibe dos parametros: asi se consulta una tabla puente.\n   */\n  async obtenerPorLlave(redSocialId, usuarioId) {\n    const fila = await db.obtenerUno(\n      `${this.#selectConJoin}\n       WHERE ps.RED_SOCIAL_id = ? AND ps.USUARIO_id = ?`,\n      [redSocialId, usuarioId]\n    );\n\n    if (fila === null) {\n      throw AppError.noEncontrado(\n        MENSAJES.NEGOCIO.PERFIL_NO_ENCONTRADO(redSocialId, usuarioId)\n      );\n    }\n\n    return PerfilSocial.desdeFila(fila);\n  }\n\n  /** READ - Todos los perfiles sociales de un usuario. */\n  async listarPorUsuario(usuarioId) {\n    const existe = await usuarioService.existe(usuarioId);\n\n    if (!existe) {\n      throw AppError.noEncontrado(MENSAJES.NEGOCIO.USUARIO_NO_EXISTE(usuarioId));\n    }\n\n    const filas = await db.ejecutar(\n      `${this.#selectConJoin}\n       WHERE ps.USUARIO_id = ?\n       ORDER BY rs.nombre`,\n      [usuarioId]\n    );\n\n    return filas.map((fila) => PerfilSocial.desdeFila(fila));\n  }\n\n  /** CREATE */\n  async crear(datosCrudos) {\n    const datos = this.#normalizar(datosCrudos);\n    this.#validarCreacion(datos);\n\n    // Primero las dos llaves foraneas...\n    await this.#verificarLlavesForaneas(datos.redSocialId, datos.usuarioId);\n\n    // ...y despues que la combinacion no exista ya.\n    await this.#verificarNoDuplicado(datos.redSocialId, datos.usuarioId);\n\n    const perfil = PerfilSocial.desdeJSON(datos);\n    const fila = perfil.aFilaBaseDatos();\n\n    // Esta tabla NO tiene AUTO_INCREMENT, asi que no hay insertId que\n    // recoger: la llave la enviamos nosotros en el INSERT.\n    await db.ejecutar(\n      `INSERT INTO PERFIL_SOCIAL (RED_SOCIAL_id, USUARIO_id, url_perfil)\n       VALUES (?, ?, ?)`,\n      [fila.RED_SOCIAL_id, fila.USUARIO_id, fila.url_perfil]\n    );\n\n    // Releemos con JOIN para devolver el perfil con el nombre de la red.\n    return this.obtenerPorLlave(datos.redSocialId, datos.usuarioId);\n  }\n\n  /**\n   * UPDATE - Solo cambia `url_perfil`.\n   * La llave compuesta identifica el recurso y es inmutable.\n   */\n  async actualizar(redSocialId, usuarioId, datosCrudos) {\n    // Lanza 404 si la combinacion no existe.\n    await this.obtenerPorLlave(redSocialId, usuarioId);\n\n    const datos = this.#normalizar(datosCrudos, this.#camposActualizables);\n    this.#validarActualizacion(datos);\n\n    await db.ejecutar(\n      `UPDATE PERFIL_SOCIAL\n       SET url_perfil = ?\n       WHERE RED_SOCIAL_id = ? AND USUARIO_id = ?`,\n      [datos.urlPerfil ?? null, redSocialId, usuarioId]\n    );\n\n    return this.obtenerPorLlave(redSocialId, usuarioId);\n  }\n\n  /**\n   * DELETE por llave compuesta.\n   * PERFIL_SOCIAL es una tabla hoja: nadie depende de ella, asi que el\n   * borrado es directo y sin transaccion.\n   */\n  async eliminar(redSocialId, usuarioId) {\n    const perfil = await this.obtenerPorLlave(redSocialId, usuarioId);\n\n    await db.ejecutar(\n      'DELETE FROM PERFIL_SOCIAL WHERE RED_SOCIAL_id = ? AND USUARIO_id = ?',\n      [redSocialId, usuarioId]\n    );\n\n    return {\n      redSocialId: perfil.redSocialId,\n      usuarioId: perfil.usuarioId,\n      urlPerfil: perfil.urlPerfil\n    };\n  }\n}\n\nmodule.exports = new PerfilSocialService();\n","persona-api/services/redSocial.service.js":"/**\n * services/redSocial.service.js\n * ---------------------------------------------------------------------\n * CAPA DE SERVICIO de la entidad RedSocial (tabla de catalogo).\n *\n * Es el servicio mas sencillo, ideal para fijar el patron:\n *   normalizar -> validar -> instanciar -> persistir -> devolver objeto\n *\n * CONCEPTO NUEVO: la PROTECCION AL BORRAR (restriccion de borrado).\n *\n * RED_SOCIAL es una tabla PADRE de PERFIL_SOCIAL. Si borraramos la\n * red social \"Instagram\" mientras tres usuarios tienen perfiles ahi,\n * esos perfiles quedarian apuntando a un id inexistente: datos\n * huerfanos.\n *\n * Hay tres estrategias posibles ante esa situacion:\n *   1. CASCADE  -> borrar tambien los perfiles. Destructivo.\n *   2. SET NULL -> dejar el perfil sin red. Aqui no sirve, la columna\n *                  es parte de la llave primaria y es NOT NULL.\n *   3. RESTRICT -> prohibir el borrado y avisar. <- la que elegimos.\n *\n * La tercera es la mas segura para un catalogo, y es la que ya pide el\n * modelo relacional con su ON DELETE NO ACTION.\n */\n\nconst db = require('../config/database');\nconst { RedSocial } = require('../models');\n\nconst formato = require('../utils/formato');\nconst AppError = require('../utils/AppError');\nconst MENSAJES = require('../utils/mensajes');\nconst { ColectorErrores } = require('../utils/validadores');\nconst { LIMITES } = require('../utils/constants');\n\nclass RedSocialService {\n  #camposPermitidos = ['nombre', 'url'];\n\n  #mapaColumnas = {\n    nombre: 'nombre',\n    url: 'url'\n  };\n\n  #columnasSelect = 'id, nombre, url';\n\n  // ------------------------- Metodos privados --------------------------\n\n  #normalizar(datosCrudos) {\n    const filtrados = formato.soloCamposPermitidos(datosCrudos, this.#camposPermitidos);\n    const limpios = {};\n\n    if (Object.hasOwn(filtrados, 'nombre')) {\n      limpios.nombre = formato.limpiarTexto(filtrados.nombre);\n    }\n\n    if (Object.hasOwn(filtrados, 'url')) {\n      limpios.url = formato.normalizarURL(filtrados.url);\n    }\n\n    return limpios;\n  }\n\n  #validarCreacion(datos) {\n    const errores = new ColectorErrores();\n\n    errores.exigirTexto('nombre', datos.nombre, { maximo: LIMITES.VARCHAR_CORTO });\n    errores.exigirURL('url', datos.url, { maximo: LIMITES.VARCHAR_CORTO });\n\n    errores.lanzarSiHay('No se pudo crear la red social porque hay datos invalidos.');\n  }\n\n  #validarActualizacion(datos) {\n    if (formato.estaVacio(datos)) {\n      throw AppError.validacion(\n        'Debes enviar al menos un campo valido para actualizar.',\n        [{ campo: 'cuerpo', mensaje: `Campos admitidos: ${this.#camposPermitidos.join(', ')}.` }]\n      );\n    }\n\n    const errores = new ColectorErrores();\n\n    if (Object.hasOwn(datos, 'nombre')) {\n      errores.exigirTexto('nombre', datos.nombre, { maximo: LIMITES.VARCHAR_CORTO });\n    }\n    if (Object.hasOwn(datos, 'url')) {\n      errores.exigirURL('url', datos.url, { maximo: LIMITES.VARCHAR_CORTO });\n    }\n\n    errores.lanzarSiHay('No se pudo actualizar la red social porque hay datos invalidos.');\n  }\n\n  /**\n   * Evita nombres de red social repetidos.\n   *\n   * Comparamos con LOWER() en los dos lados para que \"facebook\" y\n   * \"Facebook\" se consideren el mismo nombre.\n   */\n  async #verificarNombreUnico(nombre, idAExcluir = null) {\n    let sql = 'SELECT id FROM RED_SOCIAL WHERE LOWER(nombre) = LOWER(?)';\n    const parametros = [nombre];\n\n    if (idAExcluir !== null) {\n      sql += ' AND id <> ?';\n      parametros.push(idAExcluir);\n    }\n\n    const fila = await db.obtenerUno(sql, parametros);\n\n    if (fila !== null) {\n      throw AppError.conflicto(MENSAJES.NEGOCIO.RED_SOCIAL_DUPLICADA(nombre));\n    }\n  }\n\n  /**\n   * Cuenta cuantos perfiles sociales usan esta red.\n   * Lo necesita eliminar() para decidir si permite el borrado.\n   */\n  async #contarPerfilesAsociados(redSocialId) {\n    const fila = await db.obtenerUno(\n      'SELECT COUNT(*) AS total FROM PERFIL_SOCIAL WHERE RED_SOCIAL_id = ?',\n      [redSocialId]\n    );\n\n    return Number(fila?.total ?? 0);\n  }\n\n  // --------------------------- CRUD publico ----------------------------\n\n  /** READ (lista) con busqueda y paginacion. */\n  async listar(filtros = {}) {\n    const pagina = Math.max(1, formato.aEnteroONulo(filtros.pagina) ?? LIMITES.PAGINA_DEFECTO);\n    const limite = Math.min(\n      Math.max(1, formato.aEnteroONulo(filtros.limite) ?? LIMITES.LIMITE_DEFECTO),\n      LIMITES.LIMITE_MAXIMO\n    );\n    const desplazamiento = (pagina - 1) * limite;\n\n    const condiciones = [];\n    const parametros = [];\n\n    const buscar = formato.limpiarTexto(filtros.buscar);\n    if (buscar !== null) {\n      condiciones.push('(nombre LIKE ? OR url LIKE ?)');\n      const patron = `%${buscar}%`;\n      parametros.push(patron, patron);\n    }\n\n    const clausulaWhere = condiciones.length > 0 ? `WHERE ${condiciones.join(' AND ')}` : '';\n\n    const filaTotal = await db.obtenerUno(\n      `SELECT COUNT(*) AS total FROM RED_SOCIAL ${clausulaWhere}`,\n      parametros\n    );\n    const total = Number(filaTotal?.total ?? 0);\n\n    const filas = await db.ejecutar(\n      `SELECT ${this.#columnasSelect}\n       FROM RED_SOCIAL\n       ${clausulaWhere}\n       ORDER BY nombre\n       LIMIT ? OFFSET ?`,\n      [...parametros, limite, desplazamiento]\n    );\n\n    return {\n      redesSociales: filas.map((fila) => RedSocial.desdeFila(fila)),\n      total,\n      pagina,\n      limite\n    };\n  }\n\n  /** READ (detalle) */\n  async obtenerPorId(id) {\n    const fila = await db.obtenerUno(\n      `SELECT ${this.#columnasSelect} FROM RED_SOCIAL WHERE id = ?`,\n      [id]\n    );\n\n    if (fila === null) {\n      throw AppError.noEncontrado(MENSAJES.NEGOCIO.RED_SOCIAL_NO_EXISTE(id));\n    }\n\n    return RedSocial.desdeFila(fila);\n  }\n\n  /** CREATE */\n  async crear(datosCrudos) {\n    const datos = this.#normalizar(datosCrudos);\n    this.#validarCreacion(datos);\n\n    await this.#verificarNombreUnico(datos.nombre);\n\n    const redSocial = RedSocial.desdeJSON(datos);\n    const fila = redSocial.aFilaBaseDatos();\n\n    const resultado = await db.ejecutar(\n      'INSERT INTO RED_SOCIAL (nombre, url) VALUES (?, ?)',\n      [fila.nombre, fila.url]\n    );\n\n    redSocial.id = resultado.insertId;\n\n    return redSocial;\n  }\n\n  /** UPDATE (parcial) */\n  async actualizar(id, datosCrudos) {\n    const redSocial = await this.obtenerPorId(id);\n\n    const datos = this.#normalizar(datosCrudos);\n    this.#validarActualizacion(datos);\n\n    if (Object.hasOwn(datos, 'nombre')) {\n      await this.#verificarNombreUnico(datos.nombre, id);\n    }\n\n    for (const [campo, valor] of Object.entries(datos)) {\n      redSocial[campo] = valor;\n    }\n\n    const filaCompleta = redSocial.aFilaBaseDatos();\n    const asignaciones = [];\n    const parametros = [];\n\n    for (const campo of Object.keys(datos)) {\n      const columna = this.#mapaColumnas[campo];\n      if (!columna) continue;\n\n      asignaciones.push(`${columna} = ?`);\n      parametros.push(filaCompleta[columna]);\n    }\n\n    if (asignaciones.length === 0) {\n      return redSocial;\n    }\n\n    parametros.push(id);\n\n    await db.ejecutar(\n      `UPDATE RED_SOCIAL SET ${asignaciones.join(', ')} WHERE id = ?`,\n      parametros\n    );\n\n    return this.obtenerPorId(id);\n  }\n\n  /**\n   * DELETE con proteccion de integridad.\n   * Si la red tiene perfiles asociados, responde 409 Conflict en lugar\n   * de borrar o de dejar que MySQL lance un error tecnico.\n   */\n  async eliminar(id) {\n    const redSocial = await this.obtenerPorId(id);\n\n    const perfilesAsociados = await this.#contarPerfilesAsociados(id);\n\n    if (perfilesAsociados > 0) {\n      throw AppError.conflicto(\n        `${MENSAJES.NEGOCIO.RED_SOCIAL_EN_USO(id)} Perfiles asociados: ${perfilesAsociados}.`\n      );\n    }\n\n    await db.ejecutar('DELETE FROM RED_SOCIAL WHERE id = ?', [id]);\n\n    return {\n      id: redSocial.id,\n      nombre: redSocial.nombre\n    };\n  }\n\n  /** Lo usa perfilSocial.service para validar la llave foranea. */\n  async existe(id) {\n    const fila = await db.obtenerUno('SELECT 1 AS existe FROM RED_SOCIAL WHERE id = ?', [id]);\n    return fila !== null;\n  }\n}\n\nmodule.exports = new RedSocialService();\n","persona-api/services/telefono.service.js":"/**\n * services/telefono.service.js\n * ---------------------------------------------------------------------\n * CAPA DE SERVICIO de la entidad Telefono.\n *\n * NUEVO CONCEPTO QUE APARECE AQUI: la INTEGRIDAD REFERENCIAL.\n *\n * Un telefono no puede existir sin su usuario (TELEFONO.USUARIO_id es\n * una llave foranea NOT NULL). Entonces, antes de insertar, este\n * servicio pregunta al usuario.service si ese usuario existe.\n *\n * \"Y por que, si MySQL ya valida la llave foranea?\"\n * Porque MySQL devuelve el error tecnico ER_NO_REFERENCED_ROW_2, que\n * es incomprensible para un usuario final. Validando antes podemos\n * responder: \"No existe un usuario con id 42\". La base de datos sigue\n * siendo la ultima linea de defensa, pero la API da el mensaje claro.\n *\n * Fijate tambien como un service PUEDE usar otro service\n * (usuarioService.existe). Eso es composicion: cada clase sabe de lo\n * suyo y colabora con las demas.\n */\n\nconst db = require('../config/database');\nconst { Telefono } = require('../models');\nconst usuarioService = require('./usuario.service');\n\nconst formato = require('../utils/formato');\nconst AppError = require('../utils/AppError');\nconst MENSAJES = require('../utils/mensajes');\nconst { ColectorErrores } = require('../utils/validadores');\nconst { LIMITES, TIPOS_TELEFONO, ESTADO_TELEFONO } = require('../utils/constants');\n\nclass TelefonoService {\n  // Lista blanca de campos que acepta del cliente.\n  #camposPermitidos = ['numeroTelefono', 'tipoTelefono', 'usuarioId', 'activo'];\n\n  // Mapa camelCase -> columna real de MySQL.\n  #mapaColumnas = {\n    numeroTelefono: 'numero_telefono',\n    tipoTelefono: 'tipo_telefono',\n    usuarioId: 'USUARIO_id',\n    activo: 'activo'\n  };\n\n  #columnasSelect = 'id, numero_telefono, tipo_telefono, USUARIO_id, activo';\n\n  // ------------------------- Metodos privados --------------------------\n\n  /** Limpia y convierte los datos recibidos. */\n  #normalizar(datosCrudos) {\n    const filtrados = formato.soloCamposPermitidos(datosCrudos, this.#camposPermitidos);\n    const limpios = {};\n\n    if (Object.hasOwn(filtrados, 'numeroTelefono')) {\n      limpios.numeroTelefono = formato.normalizarTelefono(filtrados.numeroTelefono);\n    }\n\n    if (Object.hasOwn(filtrados, 'tipoTelefono')) {\n      // aTituloPropio deja \"celular\" como \"Celular\", que es justo\n      // lo que espera la lista TIPOS_TELEFONO.\n      limpios.tipoTelefono = formato.aTituloPropio(filtrados.tipoTelefono);\n    }\n\n    if (Object.hasOwn(filtrados, 'usuarioId')) {\n      limpios.usuarioId = formato.aEnteroONulo(filtrados.usuarioId);\n    }\n\n    if (Object.hasOwn(filtrados, 'activo')) {\n      limpios.activo = formato.aBanderaEntera(filtrados.activo, ESTADO_TELEFONO.ACTIVO);\n    }\n\n    return limpios;\n  }\n\n  /** Validacion para POST: numero, tipo y usuarioId son obligatorios. */\n  #validarCreacion(datos) {\n    const errores = new ColectorErrores();\n\n    errores.exigirTelefono('numeroTelefono', datos.numeroTelefono);\n    errores.exigirValorDeLista('tipoTelefono', datos.tipoTelefono, TIPOS_TELEFONO);\n    errores.exigirId('usuarioId', datos.usuarioId);\n    errores.exigirEntero('activo', datos.activo, {\n      requerido: false,\n      minimo: 0,\n      maximo: 1\n    });\n\n    errores.lanzarSiHay('No se pudo crear el telefono porque hay datos invalidos.');\n  }\n\n  /** Validacion para PUT: todo opcional, pero lo que venga debe ser valido. */\n  #validarActualizacion(datos) {\n    if (formato.estaVacio(datos)) {\n      throw AppError.validacion(\n        'Debes enviar al menos un campo valido para actualizar.',\n        [{ campo: 'cuerpo', mensaje: `Campos admitidos: ${this.#camposPermitidos.join(', ')}.` }]\n      );\n    }\n\n    const errores = new ColectorErrores();\n\n    if (Object.hasOwn(datos, 'numeroTelefono')) {\n      errores.exigirTelefono('numeroTelefono', datos.numeroTelefono);\n    }\n    if (Object.hasOwn(datos, 'tipoTelefono')) {\n      errores.exigirValorDeLista('tipoTelefono', datos.tipoTelefono, TIPOS_TELEFONO);\n    }\n    if (Object.hasOwn(datos, 'usuarioId')) {\n      errores.exigirId('usuarioId', datos.usuarioId);\n    }\n    if (Object.hasOwn(datos, 'activo')) {\n      errores.exigirEntero('activo', datos.activo, { minimo: 0, maximo: 1 });\n    }\n\n    errores.lanzarSiHay('No se pudo actualizar el telefono porque hay datos invalidos.');\n  }\n\n  /**\n   * Verifica que el usuario referenciado exista.\n   * @throws {AppError} 404 si no existe.\n   */\n  async #verificarUsuario(usuarioId) {\n    const existe = await usuarioService.existe(usuarioId);\n\n    if (!existe) {\n      throw AppError.noEncontrado(MENSAJES.NEGOCIO.USUARIO_NO_EXISTE(usuarioId));\n    }\n  }\n\n  /**\n   * Evita numeros de telefono repetidos.\n   *\n   * El modelo relacional NO tiene un indice UNIQUE en numero_telefono,\n   * asi que esta es una regla de NEGOCIO que imponemos desde la API.\n   *\n   * @param {string} numero\n   * @param {number|null} idAExcluir  Al actualizar, ignoramos el propio\n   *                                  registro (si no, choca consigo mismo).\n   */\n  async #verificarNumeroUnico(numero, idAExcluir = null) {\n    let sql = 'SELECT id FROM TELEFONO WHERE numero_telefono = ?';\n    const parametros = [numero];\n\n    if (idAExcluir !== null) {\n      sql += ' AND id <> ?';\n      parametros.push(idAExcluir);\n    }\n\n    const fila = await db.obtenerUno(sql, parametros);\n\n    if (fila !== null) {\n      throw AppError.conflicto(MENSAJES.NEGOCIO.TELEFONO_DUPLICADO(numero));\n    }\n  }\n\n  // --------------------------- CRUD publico ----------------------------\n\n  /**\n   * READ (lista) con filtros y paginacion.\n   *\n   * @param {object} filtros\n   * @param {number} filtros.usuarioId  Filtra los telefonos de un usuario.\n   * @param {*}      filtros.activo     1 o 0.\n   * @param {string} filtros.tipo       Celular, Fijo...\n   * @param {string} filtros.buscar     Busqueda parcial por numero.\n   */\n  async listar(filtros = {}) {\n    const pagina = Math.max(1, formato.aEnteroONulo(filtros.pagina) ?? LIMITES.PAGINA_DEFECTO);\n    const limite = Math.min(\n      Math.max(1, formato.aEnteroONulo(filtros.limite) ?? LIMITES.LIMITE_DEFECTO),\n      LIMITES.LIMITE_MAXIMO\n    );\n    const desplazamiento = (pagina - 1) * limite;\n\n    const condiciones = [];\n    const parametros = [];\n\n    const usuarioId = formato.aEnteroONulo(filtros.usuarioId);\n    if (usuarioId !== null) {\n      condiciones.push('USUARIO_id = ?');\n      parametros.push(usuarioId);\n    }\n\n    const activo = formato.aBanderaEntera(filtros.activo, null);\n    if (activo !== null) {\n      condiciones.push('activo = ?');\n      parametros.push(activo);\n    }\n\n    const tipo = formato.limpiarTexto(filtros.tipo);\n    if (tipo !== null) {\n      condiciones.push('tipo_telefono = ?');\n      parametros.push(tipo);\n    }\n\n    const buscar = formato.limpiarTexto(filtros.buscar);\n    if (buscar !== null) {\n      condiciones.push('numero_telefono LIKE ?');\n      parametros.push(`%${buscar}%`);\n    }\n\n    const clausulaWhere = condiciones.length > 0 ? `WHERE ${condiciones.join(' AND ')}` : '';\n\n    const filaTotal = await db.obtenerUno(\n      `SELECT COUNT(*) AS total FROM TELEFONO ${clausulaWhere}`,\n      parametros\n    );\n    const total = Number(filaTotal?.total ?? 0);\n\n    const filas = await db.ejecutar(\n      `SELECT ${this.#columnasSelect}\n       FROM TELEFONO\n       ${clausulaWhere}\n       ORDER BY USUARIO_id, id\n       LIMIT ? OFFSET ?`,\n      [...parametros, limite, desplazamiento]\n    );\n\n    return {\n      telefonos: filas.map((fila) => Telefono.desdeFila(fila)),\n      total,\n      pagina,\n      limite\n    };\n  }\n\n  /**\n   * READ (detalle) por id.\n   * @throws {AppError} 404 si no existe.\n   */\n  async obtenerPorId(id) {\n    const fila = await db.obtenerUno(\n      `SELECT ${this.#columnasSelect} FROM TELEFONO WHERE id = ?`,\n      [id]\n    );\n\n    if (fila === null) {\n      throw AppError.noEncontrado(MENSAJES.NEGOCIO.NO_ENCONTRADO('un telefono', id));\n    }\n\n    return Telefono.desdeFila(fila);\n  }\n\n  /**\n   * READ - Todos los telefonos de un usuario.\n   * Primero valida que el usuario exista, para distinguir dos casos\n   * muy distintos:\n   *   - usuario que existe y no tiene telefonos -> lista vacia (200)\n   *   - usuario que no existe                   -> 404\n   */\n  async listarPorUsuario(usuarioId) {\n    await this.#verificarUsuario(usuarioId);\n\n    const filas = await db.ejecutar(\n      `SELECT ${this.#columnasSelect} FROM TELEFONO WHERE USUARIO_id = ? ORDER BY id`,\n      [usuarioId]\n    );\n\n    return filas.map((fila) => Telefono.desdeFila(fila));\n  }\n\n  /** CREATE */\n  async crear(datosCrudos) {\n    const datos = this.#normalizar(datosCrudos);\n    this.#validarCreacion(datos);\n\n    // Reglas de negocio ANTES de tocar la base de datos.\n    await this.#verificarUsuario(datos.usuarioId);\n    await this.#verificarNumeroUnico(datos.numeroTelefono);\n\n    const telefono = Telefono.desdeJSON(datos);\n    const fila = telefono.aFilaBaseDatos();\n\n    const resultado = await db.ejecutar(\n      `INSERT INTO TELEFONO (numero_telefono, tipo_telefono, USUARIO_id, activo)\n       VALUES (?, ?, ?, ?)`,\n      [fila.numero_telefono, fila.tipo_telefono, fila.USUARIO_id, fila.activo]\n    );\n\n    telefono.id = resultado.insertId;\n\n    return telefono;\n  }\n\n  /** UPDATE (parcial) */\n  async actualizar(id, datosCrudos) {\n    const telefono = await this.obtenerPorId(id);\n\n    const datos = this.#normalizar(datosCrudos);\n    this.#validarActualizacion(datos);\n\n    // Si cambia de dueno, el nuevo usuario tiene que existir.\n    if (Object.hasOwn(datos, 'usuarioId')) {\n      await this.#verificarUsuario(datos.usuarioId);\n    }\n\n    // Si cambia el numero, no puede chocar con otro registro.\n    if (Object.hasOwn(datos, 'numeroTelefono')) {\n      await this.#verificarNumeroUnico(datos.numeroTelefono, id);\n    }\n\n    // Aplicamos los cambios al objeto mediante sus setters.\n    for (const [campo, valor] of Object.entries(datos)) {\n      if (campo === 'usuarioId') {\n        // El modelo guarda el dueno en `usuario`, que acepta un id.\n        telefono.usuario = valor;\n      } else {\n        telefono[campo] = valor;\n      }\n    }\n\n    // UPDATE dinamico con nombres de columna del mapa interno.\n    const filaCompleta = telefono.aFilaBaseDatos();\n    const asignaciones = [];\n    const parametros = [];\n\n    for (const campo of Object.keys(datos)) {\n      const columna = this.#mapaColumnas[campo];\n      if (!columna) continue;\n\n      asignaciones.push(`${columna} = ?`);\n      parametros.push(filaCompleta[columna]);\n    }\n\n    if (asignaciones.length === 0) {\n      return telefono;\n    }\n\n    parametros.push(id);\n\n    await db.ejecutar(\n      `UPDATE TELEFONO SET ${asignaciones.join(', ')} WHERE id = ?`,\n      parametros\n    );\n\n    return this.obtenerPorId(id);\n  }\n\n  /**\n   * DELETE\n   *\n   * Aqui NO hace falta transaccion: TELEFONO es una tabla \"hoja\",\n   * ninguna otra tabla la referencia, asi que el borrado es una sola\n   * operacion atomica por si misma.\n   */\n  async eliminar(id) {\n    const telefono = await this.obtenerPorId(id);\n\n    await db.ejecutar('DELETE FROM TELEFONO WHERE id = ?', [id]);\n\n    return {\n      id: telefono.id,\n      numeroTelefono: telefono.numeroTelefono,\n      usuarioId: telefono.usuarioId\n    };\n  }\n\n  /**\n   * Cambia la bandera `activo` (baja o alta logica).\n   * Es un buen ejemplo de un metodo de negocio que NO es CRUD puro:\n   * la operacion se le delega al MODELO (activar/desactivar) y el\n   * service solo persiste el resultado.\n   */\n  async cambiarEstado(id, activar) {\n    const telefono = await this.obtenerPorId(id);\n\n    // El objeto decide como representar su propio estado.\n    if (activar) {\n      telefono.activar();\n    } else {\n      telefono.desactivar();\n    }\n\n    await db.ejecutar('UPDATE TELEFONO SET activo = ? WHERE id = ?', [\n      telefono.activo,\n      id\n    ]);\n\n    return telefono;\n  }\n}\n\nmodule.exports = new TelefonoService();\n","persona-api/services/usuario.service.js":"/**\n * services/usuario.service.js\n * ---------------------------------------------------------------------\n * CAPA DE SERVICIO de la entidad Usuario.\n *\n * QUE RESPONSABILIDAD TIENE ESTA CAPA?\n * Es el CEREBRO de la aplicacion: aqui viven las reglas de negocio.\n *\n *   El controlador  -> habla HTTP (req, res, codigos de estado).\n *   El servicio     -> NO sabe que existe HTTP. Recibe y devuelve\n *                      objetos de JavaScript.\n *   El modelo       -> solo guarda datos y comportamiento del dominio.\n *   La base de datos-> solo persiste.\n *\n * Por que separar asi? Porque esta clase se podria reutilizar tal cual\n * desde una aplicacion de consola, desde una tarea programada o desde\n * un bot de WhatsApp. Si la logica estuviera en el controlador, estaria\n * amarrada a Express para siempre.\n *\n * EL FLUJO DE CADA METODO SIGUE SIEMPRE EL MISMO ORDEN:\n *\n *   1. NORMALIZAR  (utils/formato.js)    -> limpiar los datos\n *   2. VALIDAR     (utils/validadores.js)-> rechazar lo invalido\n *   3. INSTANCIAR  (models/Usuario.js)   -> crear el objeto\n *   4. PERSISTIR   (config/database.js)  -> guardar con SQL parametrizado\n *   5. DEVOLVER    el objeto, no la fila cruda\n *\n * Y TODO el acceso a los datos del objeto pasa por sus GETTERS: nunca\n * se toca un atributo privado. Eso es encapsulamiento en la practica.\n */\n\nconst db = require('../config/database');\nconst { Usuario, Telefono, PerfilSocial } = require('../models');\n\nconst formato = require('../utils/formato');\nconst fechas = require('../utils/fechas');\nconst AppError = require('../utils/AppError');\nconst MENSAJES = require('../utils/mensajes');\nconst { ColectorErrores } = require('../utils/validadores');\nconst { LIMITES, ESTADO_USUARIO } = require('../utils/constants');\n\nclass UsuarioService {\n  // =====================================================================\n  // ATRIBUTOS PRIVADOS DE LA CLASE\n  // ---------------------------------------------------------------------\n  // #camposPermitidos es la LISTA BLANCA de lo que el cliente puede\n  // enviar. Cualquier otra propiedad del JSON se descarta.\n  //\n  // Fijate que `id` y `edad` NO estan en la lista:\n  //   - el id lo genera MySQL (AUTO_INCREMENT);\n  //   - la edad la calcula la API desde fechaNacimiento.\n  // Si estuvieran, un cliente malicioso podria mandar\n  // { \"id\": 1, \"edad\": 999 } y corromper los datos.\n  // =====================================================================\n  #camposPermitidos = [\n    'primerNombre',\n    'segundoNombre',\n    'primerApellido',\n    'segundoApellido',\n    'fechaNacimiento',\n    'ciudadDomicilio',\n    'estado'\n  ];\n\n  // Mapa camelCase (JavaScript) -> snake_case (columnas de MySQL).\n  // Lo usamos para construir el UPDATE dinamico de forma SEGURA:\n  // los nombres de columna salen SIEMPRE de este mapa, nunca del\n  // cliente, asi que no se puede inyectar SQL por el nombre del campo.\n  #mapaColumnas = {\n    primerNombre: 'primer_nombre',\n    segundoNombre: 'segundo_nombre',\n    primerApellido: 'primer_apellido',\n    segundoApellido: 'segundo_apellido',\n    fechaNacimiento: 'fecha_nacimiento',\n    edad: 'edad',\n    ciudadDomicilio: 'ciudad_domicilio',\n    estado: 'estado'\n  };\n\n  // Columnas que se traen en los SELECT. Escribirlas de forma explicita\n  // (y no SELECT *) hace la consulta mas rapida y evita que un cambio\n  // en la tabla rompa la aplicacion sin avisar.\n  #columnasSelect = `\n    id, primer_nombre, segundo_nombre, primer_apellido, segundo_apellido,\n    fecha_nacimiento, edad, ciudad_domicilio, estado\n  `;\n\n  /**\n   * Columnas del LISTADO: las de arriba mas los conteos de relaciones.\n   *\n   * =================== EL PROBLEMA \"N + 1\" ===================\n   *\n   * El listado necesita mostrar cuantos telefonos y cuantos perfiles\n   * tiene cada usuario. La forma INGENUA de resolverlo seria:\n   *\n   *   1 consulta para traer los 50 usuarios\n   *   + 50 consultas para contar sus telefonos\n   *   + 50 consultas para contar sus perfiles\n   *   = 101 viajes a la base de datos\n   *\n   * Eso se llama problema \"N + 1\" y es la causa numero uno de APIs\n   * lentas. Con 50 ms por consulta serian 5 segundos de espera.\n   *\n   * =================== LA SOLUCION ===================\n   *\n   * Una SUBCONSULTA CORRELACIONADA: una consulta anidada que MySQL\n   * evalua por cada fila del resultado, pero DENTRO del mismo viaje.\n   *\n   *   (SELECT COUNT(*) FROM TELEFONO t WHERE t.USUARIO_id = u.id)\n   *\n   * Se llama \"correlacionada\" porque depende de la fila externa\n   * (u.id). Total: UNA sola consulta en lugar de 101.\n   *\n   * El alias `u` de la consulta externa es lo que permite la\n   * correlacion, por eso el FROM del listado dice `FROM USUARIO u`.\n   */\n  #columnasSelectListado = `\n    u.id, u.primer_nombre, u.segundo_nombre, u.primer_apellido, u.segundo_apellido,\n    u.fecha_nacimiento, u.edad, u.ciudad_domicilio, u.estado,\n    (SELECT COUNT(*) FROM TELEFONO      t  WHERE t.USUARIO_id  = u.id) AS total_telefonos,\n    (SELECT COUNT(*) FROM PERFIL_SOCIAL ps WHERE ps.USUARIO_id = u.id) AS total_perfiles_sociales\n  `;\n\n  // =====================================================================\n  // METODOS PRIVADOS DE APOYO\n  // =====================================================================\n\n  /**\n   * Deja los datos del cliente limpios y con el tipo correcto.\n   *\n   * Nota de disenio: solo normalizamos las propiedades que REALMENTE\n   * llegaron (Object.hasOwn). Esto es clave para el PUT parcial: si el\n   * cliente no envio `ciudadDomicilio`, no queremos convertirla en null\n   * y borrar el dato que ya existia.\n   *\n   * @param {object} datosCrudos  req.body tal como llego.\n   * @returns {object} Datos normalizados, solo con los campos enviados.\n   */\n  #normalizar(datosCrudos) {\n    // Paso 1: descartar cualquier campo que no este en la lista blanca.\n    const filtrados = formato.soloCamposPermitidos(datosCrudos, this.#camposPermitidos);\n    const limpios = {};\n\n    // Los nombres propios se guardan en \"Titulo Propio\": \"ANA maria\" -> \"Ana Maria\"\n    if (Object.hasOwn(filtrados, 'primerNombre')) {\n      limpios.primerNombre = formato.aTituloPropio(filtrados.primerNombre);\n    }\n    if (Object.hasOwn(filtrados, 'segundoNombre')) {\n      limpios.segundoNombre = formato.aTituloPropio(filtrados.segundoNombre);\n    }\n    if (Object.hasOwn(filtrados, 'primerApellido')) {\n      limpios.primerApellido = formato.aTituloPropio(filtrados.primerApellido);\n    }\n    if (Object.hasOwn(filtrados, 'segundoApellido')) {\n      limpios.segundoApellido = formato.aTituloPropio(filtrados.segundoApellido);\n    }\n    if (Object.hasOwn(filtrados, 'ciudadDomicilio')) {\n      limpios.ciudadDomicilio = formato.aTituloPropio(filtrados.ciudadDomicilio);\n    }\n\n    // La fecha se reduce al formato ISO corto \"AAAA-MM-DD\".\n    if (Object.hasOwn(filtrados, 'fechaNacimiento')) {\n      limpios.fechaNacimiento =\n        fechas.aFechaISO(filtrados.fechaNacimiento) ?? filtrados.fechaNacimiento;\n    }\n\n    // El estado se convierte a 1 o 0.\n    if (Object.hasOwn(filtrados, 'estado')) {\n      limpios.estado = formato.aBanderaEntera(filtrados.estado, ESTADO_USUARIO.ACTIVO);\n    }\n\n    return limpios;\n  }\n\n  /**\n   * Valida los datos para una CREACION (POST): los campos obligatorios\n   * del modelo relacional tienen que venir todos.\n   *\n   * @param {object} datos  Datos ya normalizados.\n   * @throws {AppError} 400 con la lista completa de errores.\n   */\n  #validarCreacion(datos) {\n    const errores = new ColectorErrores();\n\n    // Obligatorios segun el script SQL (columnas NOT NULL).\n    errores.exigirTexto('primerNombre', datos.primerNombre, { soloLetras: true });\n    errores.exigirTexto('primerApellido', datos.primerApellido, { soloLetras: true });\n    errores.exigirTexto('ciudadDomicilio', datos.ciudadDomicilio, { soloLetras: true });\n    errores.exigirFecha('fechaNacimiento', datos.fechaNacimiento);\n\n    // Opcionales (columnas NULL): requerido: false.\n    errores.exigirTexto('segundoNombre', datos.segundoNombre, {\n      requerido: false,\n      soloLetras: true\n    });\n    errores.exigirTexto('segundoApellido', datos.segundoApellido, {\n      requerido: false,\n      soloLetras: true\n    });\n    errores.exigirEntero('estado', datos.estado, { requerido: false, minimo: 0, maximo: 1 });\n\n    // Si hubo errores, lanza AppError 400 con TODOS de una sola vez.\n    errores.lanzarSiHay('No se pudo crear el usuario porque hay datos invalidos.');\n  }\n\n  /**\n   * Valida los datos para una ACTUALIZACION (PUT).\n   *\n   * Diferencia clave con #validarCreacion: aqui TODOS los campos son\n   * opcionales, porque permitimos actualizaciones parciales. Pero si un\n   * campo viene, tiene que ser valido.\n   */\n  #validarActualizacion(datos) {\n    if (formato.estaVacio(datos)) {\n      throw AppError.validacion(\n        'Debes enviar al menos un campo valido para actualizar.',\n        [{ campo: 'cuerpo', mensaje: `Campos admitidos: ${this.#camposPermitidos.join(', ')}.` }]\n      );\n    }\n\n    const errores = new ColectorErrores();\n\n    // El patron es: \"si el cliente envio este campo, validalo\".\n    if (Object.hasOwn(datos, 'primerNombre')) {\n      errores.exigirTexto('primerNombre', datos.primerNombre, { soloLetras: true });\n    }\n    if (Object.hasOwn(datos, 'primerApellido')) {\n      errores.exigirTexto('primerApellido', datos.primerApellido, { soloLetras: true });\n    }\n    if (Object.hasOwn(datos, 'ciudadDomicilio')) {\n      errores.exigirTexto('ciudadDomicilio', datos.ciudadDomicilio, { soloLetras: true });\n    }\n    if (Object.hasOwn(datos, 'fechaNacimiento')) {\n      errores.exigirFecha('fechaNacimiento', datos.fechaNacimiento);\n    }\n    if (Object.hasOwn(datos, 'segundoNombre')) {\n      errores.exigirTexto('segundoNombre', datos.segundoNombre, {\n        requerido: false,\n        soloLetras: true\n      });\n    }\n    if (Object.hasOwn(datos, 'segundoApellido')) {\n      errores.exigirTexto('segundoApellido', datos.segundoApellido, {\n        requerido: false,\n        soloLetras: true\n      });\n    }\n    if (Object.hasOwn(datos, 'estado')) {\n      errores.exigirEntero('estado', datos.estado, { minimo: 0, maximo: 1 });\n    }\n\n    errores.lanzarSiHay('No se pudo actualizar el usuario porque hay datos invalidos.');\n  }\n\n  /**\n   * Carga los telefonos y los perfiles sociales de un usuario y los\n   * agrega al objeto recibido.\n   *\n   * Observa que NO tocamos atributos privados: usamos los metodos\n   * publicos agregarTelefono() y agregarPerfilSocial(). El objeto\n   * controla como crece su propio estado.\n   *\n   * @param {Usuario} usuario\n   * @returns {Promise<Usuario>} El mismo objeto, ya con relaciones.\n   */\n  async #cargarRelaciones(usuario) {\n    const id = usuario.id;\n\n    // Promise.all lanza las dos consultas EN PARALELO en lugar de\n    // esperar una y despues la otra. Con dos consultas de 20 ms, pasa\n    // de 40 ms a 20 ms.\n    const [filasTelefonos, filasPerfiles] = await Promise.all([\n      db.ejecutar(\n        `SELECT id, numero_telefono, tipo_telefono, USUARIO_id, activo\n         FROM TELEFONO\n         WHERE USUARIO_id = ?\n         ORDER BY id`,\n        [id]\n      ),\n      // JOIN para traer tambien el nombre y la URL de la red social.\n      // Los alias red_nombre y red_url los usa PerfilSocial.desdeFila().\n      db.ejecutar(\n        `SELECT  ps.RED_SOCIAL_id,\n                 ps.USUARIO_id,\n                 ps.url_perfil,\n                 rs.nombre AS red_nombre,\n                 rs.url    AS red_url\n         FROM    PERFIL_SOCIAL ps\n         INNER JOIN RED_SOCIAL rs ON rs.id = ps.RED_SOCIAL_id\n         WHERE   ps.USUARIO_id = ?\n         ORDER BY rs.nombre`,\n        [id]\n      )\n    ]);\n\n    // Convertimos cada fila en un objeto del dominio.\n    for (const fila of filasTelefonos) {\n      usuario.agregarTelefono(Telefono.desdeFila(fila));\n    }\n\n    for (const fila of filasPerfiles) {\n      usuario.agregarPerfilSocial(PerfilSocial.desdeFila(fila));\n    }\n\n    return usuario;\n  }\n\n  // =====================================================================\n  // METODOS PUBLICOS: EL CRUD\n  // =====================================================================\n\n  /**\n   * READ (lista) - Devuelve usuarios con filtros y paginacion.\n   *\n   * CONSTRUCCION DINAMICA Y SEGURA DEL WHERE:\n   * Armamos dos arreglos en paralelo: uno con los textos de las\n   * condiciones y otro con los valores. El texto nunca contiene datos\n   * del cliente, solo signos de interrogacion.\n   *\n   * @param {object} filtros\n   * @param {number} filtros.pagina   Pagina solicitada (base 1).\n   * @param {number} filtros.limite   Registros por pagina.\n   * @param {*}      filtros.estado   1 o 0 para filtrar por estado.\n   * @param {string} filtros.ciudad   Filtro parcial por ciudad.\n   * @param {string} filtros.buscar   Busqueda en nombres y apellidos.\n   * @returns {Promise<{usuarios: Usuario[], total: number, pagina: number, limite: number}>}\n   */\n  async listar(filtros = {}) {\n    // ---- Paginacion ----\n    // Si el cliente no envia nada, usamos los valores por defecto.\n    const paginaSolicitada = formato.aEnteroONulo(filtros.pagina) ?? LIMITES.PAGINA_DEFECTO;\n    const limiteSolicitado = formato.aEnteroONulo(filtros.limite) ?? LIMITES.LIMITE_DEFECTO;\n\n    // Math.max(1, ...) evita paginas 0 o negativas.\n    const pagina = Math.max(1, paginaSolicitada);\n\n    // Math.min protege el servidor: aunque pidan limite=100000, el\n    // tope real es LIMITE_MAXIMO. Asi nadie puede tumbar la API\n    // pidiendo un millon de filas.\n    const limite = Math.min(Math.max(1, limiteSolicitado), LIMITES.LIMITE_MAXIMO);\n\n    // OFFSET = cuantas filas saltar. Pagina 3 con limite 10 -> saltar 20.\n    const desplazamiento = (pagina - 1) * limite;\n\n    // ---- WHERE dinamico ----\n    const condiciones = [];\n    const parametros = [];\n\n    // Filtro por estado (activo / inactivo).\n    const estado = formato.aBanderaEntera(filtros.estado, null);\n    if (estado !== null) {\n      condiciones.push('estado = ?');\n      parametros.push(estado);\n    }\n\n    // Filtro por ciudad (coincidencia parcial).\n    const ciudad = formato.limpiarTexto(filtros.ciudad);\n    if (ciudad !== null) {\n      condiciones.push('ciudad_domicilio LIKE ?');\n      // Los comodines % van en el VALOR, no en el texto de la consulta.\n      parametros.push(`%${ciudad}%`);\n    }\n\n    // Busqueda libre en nombres y apellidos.\n    const buscar = formato.limpiarTexto(filtros.buscar);\n    if (buscar !== null) {\n      condiciones.push(`(\n        primer_nombre    LIKE ? OR\n        segundo_nombre   LIKE ? OR\n        primer_apellido  LIKE ? OR\n        segundo_apellido LIKE ?\n      )`);\n      const patron = `%${buscar}%`;\n      parametros.push(patron, patron, patron, patron);\n    }\n\n    // Si no hay condiciones dejamos la clausula vacia.\n    const clausulaWhere =\n      condiciones.length > 0 ? `WHERE ${condiciones.join(' AND ')}` : '';\n\n    // ---- Consulta de conteo (para la paginacion) ----\n    const filaTotal = await db.obtenerUno(\n      `SELECT COUNT(*) AS total FROM USUARIO ${clausulaWhere}`,\n      parametros\n    );\n    const total = Number(filaTotal?.total ?? 0);\n\n    // ---- Consulta de datos ----\n    // Fijate en `FROM USUARIO u`: ese alias es el que usan las\n    // subconsultas correlacionadas de #columnasSelectListado.\n    const filas = await db.ejecutar(\n      `SELECT ${this.#columnasSelectListado}\n       FROM USUARIO u\n       ${clausulaWhere}\n       ORDER BY u.primer_apellido, u.primer_nombre\n       LIMIT ? OFFSET ?`,\n      // Los parametros del WHERE van primero y despues los del LIMIT,\n      // en el MISMO orden en que aparecen los signos ? en la consulta.\n      [...parametros, limite, desplazamiento]\n    );\n\n    // map() convierte cada fila cruda en un objeto Usuario.\n    const usuarios = filas.map((fila) => Usuario.desdeFila(fila));\n\n    return { usuarios, total, pagina, limite };\n  }\n\n  /**\n   * READ (detalle) - Devuelve un usuario por id, con sus relaciones.\n   *\n   * @param {number} id\n   * @param {object} opciones\n   * @param {boolean} opciones.incluirRelaciones  Cargar telefonos y perfiles.\n   * @returns {Promise<Usuario>}\n   * @throws {AppError} 404 si el usuario no existe.\n   */\n  async obtenerPorId(id, opciones = {}) {\n    const { incluirRelaciones = true } = opciones;\n\n    const fila = await db.obtenerUno(\n      `SELECT ${this.#columnasSelect} FROM USUARIO WHERE id = ?`,\n      [id]\n    );\n\n    // Regla de negocio: si no existe, es un 404, no una lista vacia.\n    if (fila === null) {\n      throw AppError.noEncontrado(MENSAJES.NEGOCIO.USUARIO_NO_EXISTE(id));\n    }\n\n    const usuario = Usuario.desdeFila(fila);\n\n    if (incluirRelaciones) {\n      await this.#cargarRelaciones(usuario);\n    }\n\n    return usuario;\n  }\n\n  /**\n   * CREATE - Inserta un usuario nuevo.\n   *\n   * @param {object} datosCrudos  req.body\n   * @returns {Promise<Usuario>}  El usuario creado, ya con su id.\n   */\n  async crear(datosCrudos) {\n    // 1. Normalizar\n    const datos = this.#normalizar(datosCrudos);\n\n    // 2. Validar\n    this.#validarCreacion(datos);\n\n    // 3. Instanciar el objeto del dominio\n    const usuario = Usuario.desdeJSON(datos);\n\n    // La API NUNCA confia en la edad que envie el cliente: la calcula\n    // ella misma a partir de la fecha de nacimiento. Esta es la regla\n    // de negocio mas importante de esta entidad.\n    usuario.recalcularEdad();\n\n    // 4. Persistir. aFilaBaseDatos() traduce el objeto a columnas.\n    const fila = usuario.aFilaBaseDatos();\n\n    const resultado = await db.ejecutar(\n      `INSERT INTO USUARIO\n         (primer_nombre, segundo_nombre, primer_apellido, segundo_apellido,\n          fecha_nacimiento, edad, ciudad_domicilio, estado)\n       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,\n      [\n        fila.primer_nombre,\n        fila.segundo_nombre,\n        fila.primer_apellido,\n        fila.segundo_apellido,\n        fila.fecha_nacimiento,\n        fila.edad,\n        fila.ciudad_domicilio,\n        fila.estado\n      ]\n    );\n\n    // MySQL nos devuelve el id que genero el AUTO_INCREMENT.\n    // Lo asignamos POR EL SETTER, no tocando el atributo privado.\n    usuario.id = resultado.insertId;\n\n    return usuario;\n  }\n\n  /**\n   * UPDATE - Actualiza un usuario existente (actualizacion parcial).\n   *\n   * @param {number} id\n   * @param {object} datosCrudos\n   * @returns {Promise<Usuario>}  El usuario ya actualizado.\n   */\n  async actualizar(id, datosCrudos) {\n    // 1. Verificar que exista. Si no, obtenerPorId lanza el 404.\n    //    Pedimos sin relaciones porque aqui no las necesitamos.\n    const usuario = await this.obtenerPorId(id, { incluirRelaciones: false });\n\n    // 2. Normalizar y validar solo lo que llego.\n    const datos = this.#normalizar(datosCrudos);\n    this.#validarActualizacion(datos);\n\n    // 3. Aplicar los cambios AL OBJETO usando sus SETTERS.\n    //\n    //    Aqui se ve el valor del encapsulamiento: al asignar\n    //    `usuario.fechaNacimiento`, el setter del modelo recalcula la\n    //    edad solo. El service no tiene que acordarse de hacerlo.\n    for (const [campo, valor] of Object.entries(datos)) {\n      usuario[campo] = valor;\n    }\n\n    // Por seguridad forzamos el recalculo (cubre el caso de datos\n    // viejos que vinieran con la edad desincronizada).\n    usuario.recalcularEdad();\n\n    // 4. Construir el UPDATE dinamico.\n    //    Solo actualizamos las columnas que cambiaron, mas `edad`,\n    //    que siempre se recalcula.\n    const camposAActualizar = Object.keys(datos);\n\n    if (Object.hasOwn(datos, 'fechaNacimiento') && !camposAActualizar.includes('edad')) {\n      camposAActualizar.push('edad');\n    }\n\n    const asignaciones = [];\n    const parametros = [];\n    const filaCompleta = usuario.aFilaBaseDatos();\n\n    for (const campo of camposAActualizar) {\n      // El nombre de la columna sale del MAPA, nunca del cliente.\n      const columna = this.#mapaColumnas[campo];\n\n      // Si el campo no esta en el mapa, lo ignoramos en silencio.\n      if (!columna) continue;\n\n      asignaciones.push(`${columna} = ?`);\n      parametros.push(filaCompleta[columna]);\n    }\n\n    // Si tras el filtrado no quedo nada que actualizar, devolvemos el\n    // usuario sin tocar la base de datos.\n    if (asignaciones.length === 0) {\n      return this.obtenerPorId(id);\n    }\n\n    // El id va al final porque es el ultimo ? de la consulta (el WHERE).\n    parametros.push(id);\n\n    await db.ejecutar(\n      `UPDATE USUARIO SET ${asignaciones.join(', ')} WHERE id = ?`,\n      parametros\n    );\n\n    // 5. Devolvemos el estado final leido de la base de datos, para\n    //    que el cliente vea exactamente lo que quedo guardado.\n    return this.obtenerPorId(id);\n  }\n\n  /**\n   * DELETE - Elimina un usuario y todo lo que depende de el.\n   *\n   * POR QUE HACE FALTA UNA TRANSACCION?\n   * El modelo relacional define las llaves foraneas con\n   * ON DELETE NO ACTION, asi que MySQL NO borra en cascada: si\n   * intentamos borrar el usuario con telefonos asociados, falla con el\n   * error ER_ROW_IS_REFERENCED.\n   *\n   * Hay que borrar en orden inverso a la dependencia:\n   *    1. PERFIL_SOCIAL  (depende de USUARIO)\n   *    2. TELEFONO       (depende de USUARIO)\n   *    3. USUARIO\n   *\n   * Si el paso 3 fallara y no usaramos transaccion, el usuario se\n   * quedaria sin telefonos ni perfiles: datos destruidos a medias.\n   * La transaccion garantiza TODO o NADA.\n   *\n   * @param {number} id\n   * @returns {Promise<{id: number, nombreCompleto: string, telefonosEliminados: number, perfilesEliminados: number}>}\n   */\n  async eliminar(id) {\n    // Cargamos el usuario antes de borrarlo, para poder informar al\n    // cliente a quien se elimino (y lanzar 404 si no existe).\n    const usuario = await this.obtenerPorId(id, { incluirRelaciones: false });\n\n    const resumen = await db.conTransaccion(async (conexion) => {\n      // Dentro de la transaccion usamos `conexion.execute`, NO\n      // `db.ejecutar`. Si usaramos db.ejecutar, cada consulta tomaria\n      // una conexion distinta del pool y la transaccion no las cubriria.\n      const [borradoPerfiles] = await conexion.execute(\n        'DELETE FROM PERFIL_SOCIAL WHERE USUARIO_id = ?',\n        [id]\n      );\n\n      const [borradoTelefonos] = await conexion.execute(\n        'DELETE FROM TELEFONO WHERE USUARIO_id = ?',\n        [id]\n      );\n\n      await conexion.execute('DELETE FROM USUARIO WHERE id = ?', [id]);\n\n      // affectedRows dice cuantas filas elimino cada DELETE.\n      return {\n        perfilesEliminados: borradoPerfiles.affectedRows,\n        telefonosEliminados: borradoTelefonos.affectedRows\n      };\n    });\n\n    return {\n      id: usuario.id,\n      nombreCompleto: usuario.obtenerNombreCompleto(),\n      ...resumen\n    };\n  }\n\n  /**\n   * Comprueba si existe un usuario con ese id.\n   * Lo usan los otros services (telefono, perfilSocial) para validar\n   * la llave foranea ANTES de insertar y poder dar un mensaje claro.\n   *\n   * Nota: consultamos `SELECT 1` y no `SELECT *`, porque no nos\n   * interesan los datos, solo si hay fila o no.\n   *\n   * @param {number} id\n   * @returns {Promise<boolean>}\n   */\n  async existe(id) {\n    const fila = await db.obtenerUno('SELECT 1 AS existe FROM USUARIO WHERE id = ?', [id]);\n    return fila !== null;\n  }\n}\n\n// SINGLETON: una sola instancia compartida por toda la aplicacion.\nmodule.exports = new UsuarioService();\n","persona-api/utils/AppError.js":"/**\n * utils/AppError.js\n * ---------------------------------------------------------------------\n * Clase de error propia de la aplicacion.\n *\n * Problema: el Error nativo de JavaScript solo tiene \"message\".\n * No sabe de codigos HTTP ni de listas de campos invalidos.\n *\n * Solucion: HEREDAMOS de Error (extends) y le agregamos lo que\n * necesitamos. Asi, cuando el middleware de errores recibe el objeto,\n * puede decidir si responde 400, 404 o 500 preguntandole al error mismo.\n *\n * Esto es POLIMORFISMO por herencia: AppError \"es un\" Error, entonces\n * funciona con try/catch, con throw y con instanceof como cualquier otro.\n */\n\nconst { HTTP, CODIGO_ERROR } = require('./constants');\n\nclass AppError extends Error {\n  // Atributos privados: solo se leen a traves de los getters.\n  #estadoHttp;\n  #codigo;\n  #detalles;\n  #esOperacional;\n\n  /**\n   * @param {string} mensaje       Texto legible para el usuario final.\n   * @param {number} estadoHttp    Codigo HTTP con el que se respondera.\n   * @param {string} codigo        Codigo interno (ver CODIGO_ERROR).\n   * @param {Array}  detalles      Lista opcional de errores de campo.\n   */\n  constructor(\n    mensaje,\n    estadoHttp = HTTP.ERROR_SERVIDOR,\n    codigo = CODIGO_ERROR.INTERNO,\n    detalles = []\n  ) {\n    // super() llama al constructor de Error y asigna this.message.\n    super(mensaje);\n\n    // El nombre de la clase, util en los logs.\n    this.name = 'AppError';\n\n    this.#estadoHttp = estadoHttp;\n    this.#codigo = codigo;\n    this.#detalles = detalles;\n\n    // true  -> error previsto (validacion, no encontrado). Se le muestra al usuario.\n    // false -> error inesperado (bug). Se registra completo en el log.\n    this.#esOperacional = true;\n\n    // Limpia el stack trace para que apunte a donde se lanzo el error\n    // y no al constructor de esta clase.\n    Error.captureStackTrace(this, this.constructor);\n  }\n\n  // ---------------- Getters ----------------\n  get estadoHttp() {\n    return this.#estadoHttp;\n  }\n\n  get codigo() {\n    return this.#codigo;\n  }\n\n  get detalles() {\n    // Devolvemos una COPIA del arreglo. Si devolvieramos la referencia,\n    // quien la reciba podria modificar el estado interno del error.\n    return [...this.#detalles];\n  }\n\n  get esOperacional() {\n    return this.#esOperacional;\n  }\n\n  // ---------------- Metodos de fabrica (static) ----------------\n  // Son atajos para crear los errores mas comunes sin repetir argumentos.\n  // Se llaman sobre la CLASE, no sobre una instancia:\n  //    throw AppError.noEncontrado('No existe el usuario 9');\n\n  static validacion(mensaje, detalles = []) {\n    return new AppError(\n      mensaje,\n      HTTP.SOLICITUD_INCORRECTA,\n      CODIGO_ERROR.VALIDACION,\n      detalles\n    );\n  }\n\n  static noEncontrado(mensaje) {\n    return new AppError(mensaje, HTTP.NO_ENCONTRADO, CODIGO_ERROR.NO_ENCONTRADO);\n  }\n\n  static conflicto(mensaje) {\n    return new AppError(mensaje, HTTP.CONFLICTO, CODIGO_ERROR.DUPLICADO);\n  }\n\n  static baseDatos(mensaje) {\n    return new AppError(mensaje, HTTP.ERROR_SERVIDOR, CODIGO_ERROR.BASE_DATOS);\n  }\n\n  /**\n   * Convierte el error al formato JSON que viaja al cliente.\n   * Nunca incluye el stack trace: eso se queda en el servidor.\n   */\n  aJSON() {\n    const cuerpo = {\n      ok: false,\n      error: {\n        codigo: this.#codigo,\n        mensaje: this.message\n      }\n    };\n\n    // Solo agregamos \"detalles\" si hay algo que mostrar.\n    if (this.#detalles.length > 0) {\n      cuerpo.error.detalles = this.detalles;\n    }\n\n    return cuerpo;\n  }\n}\n\nmodule.exports = AppError;\n","persona-api/utils/cifrado.js":"/**\n * utils/cifrado.js\n * ---------------------------------------------------------------------\n * Modulo DIDACTICO de cifrado y hashing con el modulo nativo `crypto`\n * de Node.js (no requiere instalar nada).\n *\n * IMPORTANTE PARA EL APRENDIZ:\n * Esta version de la API no maneja contrasenias (la tabla USUARIO no\n * tiene esa columna), asi que estas funciones NO se usan en el flujo\n * actual. Estan aqui como referencia para que entiendas tres conceptos\n * que se confunden mucho:\n *\n *   1. HASH          -> transformacion de UNA sola via. No se puede\n *                       revertir. Se usa para contrasenias.\n *   2. HMAC          -> hash con llave secreta. Sirve para firmar y\n *                       verificar que un dato no fue alterado.\n *   3. ENMASCARADO   -> ocultar parte de un dato visible (un telefono)\n *                       para no exponerlo completo en pantalla o logs.\n *                       NO es seguridad, es privacidad de presentacion.\n *\n * REGLA DE ORO: para contrasenias reales en produccion se usa bcrypt,\n * scrypt o argon2, NUNCA un SHA-256 simple. Aqui usamos scrypt, que SI\n * es apto para contrasenias porque es lento a proposito.\n */\n\nconst crypto = require('node:crypto');\n\n// Parametros del hash. 16 bytes de sal y 64 bytes de llave derivada\n// son los valores recomendados por la documentacion de Node.js.\nconst BYTES_SAL = 16;\nconst BYTES_CLAVE = 64;\n\n/**\n * Calcula el hash SHA-256 de un texto y lo devuelve en hexadecimal.\n *\n * Uso valido: generar una huella (checksum) de un archivo o un dato,\n * para comparar si cambio.\n * Uso INVALIDO: guardar contrasenias. SHA-256 es demasiado rapido y\n * un atacante puede probar millones de claves por segundo.\n *\n * @param {string} texto\n * @returns {string} 64 caracteres hexadecimales\n */\nfunction huellaSHA256(texto) {\n  return crypto.createHash('sha256').update(String(texto), 'utf8').digest('hex');\n}\n\n/**\n * Genera el hash de una contrasenia usando scrypt.\n *\n * Devuelve un solo texto con la sal y el hash separados por ':'\n *   \"a1b2...:f9e8...\"\n * Guardamos la sal junto al hash porque la necesitamos para verificar,\n * y la sal NO es secreta: su unico trabajo es que dos usuarios con la\n * misma contrasenia tengan hashes distintos.\n *\n * @param {string} contrasenia\n * @returns {string} \"sal:hash\" en hexadecimal\n */\nfunction hashearContrasenia(contrasenia) {\n  // randomBytes genera datos aleatorios criptograficamente seguros.\n  const sal = crypto.randomBytes(BYTES_SAL).toString('hex');\n\n  // scryptSync deriva la llave. Es intencionalmente costoso en CPU\n  // y memoria para frenar los ataques de fuerza bruta.\n  const hash = crypto.scryptSync(String(contrasenia), sal, BYTES_CLAVE).toString('hex');\n\n  return `${sal}:${hash}`;\n}\n\n/**\n * Verifica si una contrasenia en texto plano corresponde al hash\n * guardado.\n *\n * Detalle critico: comparamos con timingSafeEqual y NO con ===.\n * El operador === sale del bucle en el primer byte distinto, y medir\n * ese tiempo permite deducir el hash byte por byte (timing attack).\n * timingSafeEqual siempre tarda lo mismo.\n *\n * @param {string} contrasenia  Texto plano que escribio el usuario.\n * @param {string} almacenado   El \"sal:hash\" guardado en la base.\n * @returns {boolean}\n */\nfunction verificarContrasenia(contrasenia, almacenado) {\n  if (typeof almacenado !== 'string' || !almacenado.includes(':')) {\n    return false;\n  }\n\n  const [sal, hashGuardado] = almacenado.split(':');\n\n  const hashCalculado = crypto.scryptSync(String(contrasenia), sal, BYTES_CLAVE);\n  const bufferGuardado = Buffer.from(hashGuardado, 'hex');\n\n  // timingSafeEqual exige que los dos buffers midan lo mismo.\n  if (hashCalculado.length !== bufferGuardado.length) {\n    return false;\n  }\n\n  return crypto.timingSafeEqual(hashCalculado, bufferGuardado);\n}\n\n/**\n * Firma un texto con HMAC-SHA256 y una llave secreta.\n * Sirve, por ejemplo, para firmar un token o un enlace temporal.\n *\n * @param {string} texto\n * @param {string} llaveSecreta\n * @returns {string}\n */\nfunction firmarHMAC(texto, llaveSecreta) {\n  return crypto\n    .createHmac('sha256', String(llaveSecreta))\n    .update(String(texto), 'utf8')\n    .digest('hex');\n}\n\n/**\n * Genera un identificador aleatorio unico (UUID v4).\n * Util para nombres de archivo, tokens de un solo uso, etc.\n *\n * @returns {string} Ejemplo: \"9b1deb4d-3b7d-4bad-9bdd-2b0d7b3dcb6d\"\n */\nfunction generarIdentificadorUnico() {\n  return crypto.randomUUID();\n}\n\n/**\n * Enmascara un dato dejando visibles solo los ultimos N caracteres.\n *\n *   enmascarar(\"3001234567\", 4) -> \"******4567\"\n *\n * Esto NO es cifrado: el dato original sigue en la base de datos.\n * Se usa para no mostrar informacion completa en pantalla ni en logs.\n *\n * @param {string} valor\n * @param {number} visibles\n * @returns {string|null}\n */\nfunction enmascarar(valor, visibles = 4) {\n  if (valor === null || valor === undefined) return null;\n\n  const texto = String(valor);\n\n  // Si el dato es muy corto, lo tapamos completo.\n  if (texto.length <= visibles) {\n    return '*'.repeat(texto.length);\n  }\n\n  const parteOculta = '*'.repeat(texto.length - visibles);\n  const parteVisible = texto.slice(-visibles);\n\n  return parteOculta + parteVisible;\n}\n\nmodule.exports = {\n  huellaSHA256,\n  hashearContrasenia,\n  verificarContrasenia,\n  firmarHMAC,\n  generarIdentificadorUnico,\n  enmascarar\n};\n","persona-api/utils/constants.js":"/**\n * utils/constants.js\n * ---------------------------------------------------------------------\n * Constantes de toda la aplicacion.\n *\n * Por que un archivo de constantes?\n * Para no repetir \"numeros magicos\" ni textos sueltos por el codigo.\n * Si manana el estado activo cambia de 1 a 'A', se cambia en UN solo\n * lugar y toda la aplicacion queda consistente.\n *\n * Object.freeze() congela el objeto: nadie puede modificarlo en tiempo\n * de ejecucion. Es la forma de simular una constante \"de verdad\" en JS.\n */\n\n// Codigos de estado HTTP que usa la API.\nconst HTTP = Object.freeze({\n  OK: 200,                    // Peticion exitosa\n  CREADO: 201,                // Recurso creado (respuesta de POST)\n  SIN_CONTENIDO: 204,         // Exito pero sin cuerpo de respuesta\n  SOLICITUD_INCORRECTA: 400,  // El cliente envio datos invalidos\n  NO_ENCONTRADO: 404,         // El recurso no existe\n  CONFLICTO: 409,             // Choca con una regla de negocio (duplicado)\n  ENTIDAD_NO_PROCESABLE: 422, // Fallo de validacion semantica\n  ERROR_SERVIDOR: 500         // Error inesperado del servidor\n});\n\n// Codigos internos de error. Viajan en la respuesta JSON para que el\n// frontend pueda reaccionar sin tener que leer el texto del mensaje.\nconst CODIGO_ERROR = Object.freeze({\n  VALIDACION: 'VALIDACION',\n  NO_ENCONTRADO: 'NO_ENCONTRADO',\n  DUPLICADO: 'DUPLICADO',\n  LLAVE_FORANEA: 'LLAVE_FORANEA',\n  BASE_DATOS: 'BASE_DATOS',\n  RUTA_NO_ENCONTRADA: 'RUTA_NO_ENCONTRADA',\n  INTERNO: 'INTERNO'\n});\n\n// Estado de un USUARIO (columna `estado`).\nconst ESTADO_USUARIO = Object.freeze({\n  INACTIVO: 0,\n  ACTIVO: 1\n});\n\n// Estado de un TELEFONO (columna `activo`).\nconst ESTADO_TELEFONO = Object.freeze({\n  INACTIVO: 0,\n  ACTIVO: 1\n});\n\n// Valores permitidos para TELEFONO.tipo_telefono.\nconst TIPOS_TELEFONO = Object.freeze(['Celular', 'Fijo', 'Trabajo', 'Casa', 'Otro']);\n\n// Limites que vienen del modelo relacional (VARCHAR(45)).\n// Validamos en la API para dar un error claro ANTES de llegar a MySQL.\nconst LIMITES = Object.freeze({\n  VARCHAR_CORTO: 45,\n  EDAD_MINIMA: 0,\n  EDAD_MAXIMA: 130,\n  PAGINA_DEFECTO: 1,\n  LIMITE_DEFECTO: 50,\n  LIMITE_MAXIMO: 200\n});\n\n// Nombres de las tablas. Evita errores de tipeo en las consultas SQL.\nconst TABLAS = Object.freeze({\n  USUARIO: 'USUARIO',\n  TELEFONO: 'TELEFONO',\n  RED_SOCIAL: 'RED_SOCIAL',\n  PERFIL_SOCIAL: 'PERFIL_SOCIAL'\n});\n\nmodule.exports = {\n  HTTP,\n  CODIGO_ERROR,\n  ESTADO_USUARIO,\n  ESTADO_TELEFONO,\n  TIPOS_TELEFONO,\n  LIMITES,\n  TABLAS\n};\n","persona-api/utils/fechas.js":"/**\n * utils/fechas.js\n * ---------------------------------------------------------------------\n * Todo lo relacionado con fechas en un solo lugar.\n *\n * Por que un modulo aparte? Porque las fechas son la principal fuente\n * de bugs en cualquier aplicacion:\n *   - El frontend trabaja con el formato ISO  \"1995-07-24\"\n *   - MySQL guarda DATETIME                   \"1995-07-24 00:00:00\"\n *   - JavaScript usa objetos Date\n * Si cada capa convierte a su manera, aparecen fechas corridas un dia.\n * Aqui definimos UNA sola forma de convertir y la usamos en toda la app.\n *\n * REGLA IMPORTANTE: usamos los getters LOCALES (getFullYear, getMonth,\n * getDate) y no los UTC. El driver de MySQL devuelve el DATETIME como\n * un Date en la zona horaria local, asi que leerlo en local evita el\n * clasico error de \"me restó un dia\".\n */\n\n// Expresion regular para el formato AAAA-MM-DD exacto.\n// ^        inicio del texto\n// \\d{4}    exactamente 4 digitos (anio)\n// -        guion literal\n// \\d{2}    exactamente 2 digitos (mes)\n// $        fin del texto\nconst PATRON_FECHA_ISO = /^\\d{4}-\\d{2}-\\d{2}$/;\n\nconst MESES_ES = [\n  'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',\n  'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'\n];\n\n/**\n * Agrega un cero a la izquierda si el numero tiene un solo digito.\n * padStart(2, '0') convierte 7 en \"07\".\n */\nfunction dosDigitos(numero) {\n  return String(numero).padStart(2, '0');\n}\n\n/**\n * Valida que el texto sea una fecha real en formato AAAA-MM-DD.\n * No basta con la expresion regular: \"2026-02-31\" cumple el patron\n * pero no existe. Por eso reconstruimos la fecha y comparamos.\n *\n * @param {string} texto\n * @returns {boolean}\n */\nfunction esFechaISOValida(texto) {\n  if (typeof texto !== 'string' || !PATRON_FECHA_ISO.test(texto)) {\n    return false;\n  }\n\n  // Separamos el texto y lo convertimos a numeros.\n  const [anio, mes, dia] = texto.split('-').map(Number);\n\n  // Construimos la fecha. El mes en JavaScript va de 0 a 11,\n  // por eso restamos 1.\n  const fecha = new Date(anio, mes - 1, dia);\n\n  // Si JavaScript \"corrigio\" la fecha (por ejemplo 31 de febrero ->\n  // 2 o 3 de marzo), los componentes ya no coinciden: era invalida.\n  return (\n    fecha.getFullYear() === anio &&\n    fecha.getMonth() === mes - 1 &&\n    fecha.getDate() === dia\n  );\n}\n\n/**\n * Convierte cualquier entrada (Date, \"1995-07-24\" o\n * \"1995-07-24T00:00:00.000Z\") al formato ISO corto \"AAAA-MM-DD\".\n *\n * @param {Date|string|null} valor\n * @returns {string|null}\n */\nfunction aFechaISO(valor) {\n  if (valor === null || valor === undefined || valor === '') {\n    return null;\n  }\n\n  // Si ya es un Date valido lo formateamos directamente.\n  if (valor instanceof Date) {\n    if (Number.isNaN(valor.getTime())) return null;\n    return `${valor.getFullYear()}-${dosDigitos(valor.getMonth() + 1)}-${dosDigitos(valor.getDate())}`;\n  }\n\n  // Si es texto, nos quedamos con los primeros 10 caracteres\n  // (\"1995-07-24T00:00:00Z\" -> \"1995-07-24\").\n  const texto = String(valor).slice(0, 10);\n  return esFechaISOValida(texto) ? texto : null;\n}\n\n/**\n * Convierte \"AAAA-MM-DD\" al formato DATETIME que espera MySQL.\n * La columna fecha_nacimiento es DATETIME, asi que completamos la\n * hora con 00:00:00 (medianoche).\n *\n * @param {Date|string} valor\n * @returns {string|null}  Ejemplo: \"1995-07-24 00:00:00\"\n */\nfunction aFechaMySQL(valor) {\n  const iso = aFechaISO(valor);\n  return iso === null ? null : `${iso} 00:00:00`;\n}\n\n/**\n * Indica si la fecha recibida es posterior a hoy.\n * Sirve para rechazar fechas de nacimiento en el futuro.\n *\n * @param {Date|string} valor\n * @returns {boolean}\n */\nfunction esFechaFutura(valor) {\n  const iso = aFechaISO(valor);\n  if (iso === null) return false;\n\n  const hoy = new Date();\n  const hoyISO = `${hoy.getFullYear()}-${dosDigitos(hoy.getMonth() + 1)}-${dosDigitos(hoy.getDate())}`;\n\n  // Al comparar textos \"AAAA-MM-DD\" alfabeticamente obtenemos el mismo\n  // resultado que comparando fechas, porque el formato es ordenable.\n  return iso > hoyISO;\n}\n\n/**\n * Calcula la edad en anios CUMPLIDOS a partir de la fecha de nacimiento.\n *\n * Regla de negocio: la API nunca confia en la edad que envia el cliente,\n * siempre la recalcula aqui. Asi la columna `edad` jamas queda\n * desincronizada con `fecha_nacimiento`.\n *\n * @param {Date|string} fechaNacimiento\n * @returns {number|null}\n */\nfunction calcularEdad(fechaNacimiento) {\n  const iso = aFechaISO(fechaNacimiento);\n  if (iso === null) return null;\n\n  const [anio, mes, dia] = iso.split('-').map(Number);\n  const hoy = new Date();\n\n  // Diferencia bruta de anios.\n  let edad = hoy.getFullYear() - anio;\n\n  // Si todavia no ha llegado el cumpleanios de este anio, restamos 1.\n  const mesActual = hoy.getMonth() + 1;\n  const diaActual = hoy.getDate();\n  const cumpleYaPaso = mesActual > mes || (mesActual === mes && diaActual >= dia);\n\n  if (!cumpleYaPaso) {\n    edad -= 1;\n  }\n\n  // Nunca devolvemos edades negativas.\n  return edad < 0 ? 0 : edad;\n}\n\n/**\n * Formatea una fecha en texto legible en espanol.\n * Ejemplo: \"1995-07-24\" -> \"24 de julio de 1995\"\n *\n * @param {Date|string} valor\n * @returns {string|null}\n */\nfunction aTextoLargo(valor) {\n  const iso = aFechaISO(valor);\n  if (iso === null) return null;\n\n  const [anio, mes, dia] = iso.split('-').map(Number);\n  return `${dia} de ${MESES_ES[mes - 1]} de ${anio}`;\n}\n\n/**\n * Marca de tiempo actual en formato ISO, para los logs.\n * Ejemplo: \"2026-10-09T21:15:04.512Z\"\n */\nfunction ahoraISO() {\n  return new Date().toISOString();\n}\n\nmodule.exports = {\n  PATRON_FECHA_ISO,\n  esFechaISOValida,\n  aFechaISO,\n  aFechaMySQL,\n  esFechaFutura,\n  calcularEdad,\n  aTextoLargo,\n  ahoraISO\n};\n","persona-api/utils/formato.js":"/**\n * utils/formato.js\n * ---------------------------------------------------------------------\n * Funciones de NORMALIZACION: dejan los datos \"limpios\" antes de\n * validarlos y antes de guardarlos.\n *\n * Diferencia clave que hay que entender:\n *   - FORMATEAR  = transformar el dato      (\"  ana  \" -> \"Ana\")\n *   - VALIDAR    = decidir si es aceptable  (\"Ana\" -> true)\n *\n * Siempre se formatea PRIMERO y se valida DESPUES. Si no, un nombre\n * escrito como \"   \" (solo espacios) pasaria la validacion de\n * \"no esta vacio\" cuando en realidad no tiene contenido.\n */\n\n/**\n * Quita espacios al inicio y al final, y colapsa los espacios\n * internos repetidos en uno solo.\n * Devuelve null si al final no queda nada.\n *\n *   \"  Juan   Carlos  \" -> \"Juan Carlos\"\n *   \"     \"             -> null\n *\n * @param {*} valor\n * @returns {string|null}\n */\nfunction limpiarTexto(valor) {\n  if (valor === null || valor === undefined) return null;\n\n  // replace(/\\s+/g, ' ') cambia cualquier grupo de espacios, tabulaciones\n  // o saltos de linea por un unico espacio.\n  const texto = String(valor).trim().replace(/\\s+/g, ' ');\n\n  return texto.length === 0 ? null : texto;\n}\n\n/**\n * Pasa un texto a \"Titulo Propio\": primera letra de cada palabra en\n * mayuscula y el resto en minuscula.\n *\n *   \"MARIA del carmen\" -> \"Maria Del Carmen\"\n *\n * @param {*} valor\n * @returns {string|null}\n */\nfunction aTituloPropio(valor) {\n  const texto = limpiarTexto(valor);\n  if (texto === null) return null;\n\n  return texto\n    .toLocaleLowerCase('es')\n    .split(' ')\n    .map((palabra) =>\n      palabra.charAt(0).toLocaleUpperCase('es') + palabra.slice(1)\n    )\n    .join(' ');\n}\n\n/**\n * Normaliza un numero de telefono: deja solo digitos, el signo + y\n * guiones, y quita los espacios.\n *\n *   \"+57 (300) 123-4567\" -> \"+57300123-4567\"\n *\n * @param {*} valor\n * @returns {string|null}\n */\nfunction normalizarTelefono(valor) {\n  const texto = limpiarTexto(valor);\n  if (texto === null) return null;\n\n  // [^...] significa \"todo lo que NO este en esta lista\".\n  return texto.replace(/[^\\d+-]/g, '');\n}\n\n/**\n * Normaliza una URL: quita espacios, pasa el dominio a minusculas y\n * elimina la barra final para que no se guarden duplicados del tipo\n * \"https://x.com\" y \"https://x.com/\".\n *\n * @param {*} valor\n * @returns {string|null}\n */\nfunction normalizarURL(valor) {\n  const texto = limpiarTexto(valor);\n  if (texto === null) return null;\n\n  // Quita una o varias barras finales.\n  const sinBarraFinal = texto.replace(/\\/+$/, '');\n  return sinBarraFinal.length === 0 ? null : sinBarraFinal;\n}\n\n/**\n * Convierte el valor a entero. Devuelve null si no es convertible.\n * Number.parseInt(\"12abc\") daria 12, lo cual es peligroso, por eso\n * primero comprobamos con una expresion regular que SOLO haya digitos.\n *\n * @param {*} valor\n * @returns {number|null}\n */\nfunction aEnteroONulo(valor) {\n  if (valor === null || valor === undefined || valor === '') return null;\n\n  const texto = String(valor).trim();\n\n  // Signo opcional seguido de uno o mas digitos, y nada mas.\n  if (!/^[+-]?\\d+$/.test(texto)) return null;\n\n  return Number.parseInt(texto, 10);\n}\n\n/**\n * Convierte valores \"parecidos a booleano\" en 1 o 0, que es lo que\n * guardan las columnas INT `estado` y `activo` del modelo.\n *\n *   1, \"1\", true, \"true\", \"activo\"  -> 1\n *   0, \"0\", false, \"false\"          -> 0\n *   cualquier otra cosa             -> valorPorDefecto\n *\n * @param {*} valor\n * @param {number|null} valorPorDefecto\n * @returns {number|null}\n */\nfunction aBanderaEntera(valor, valorPorDefecto = null) {\n  if (valor === null || valor === undefined || valor === '') return valorPorDefecto;\n\n  const texto = String(valor).trim().toLowerCase();\n\n  if (['1', 'true', 'si', 'activo'].includes(texto)) return 1;\n  if (['0', 'false', 'no', 'inactivo'].includes(texto)) return 0;\n\n  return valorPorDefecto;\n}\n\n/**\n * Deja en el objeto UNICAMENTE las propiedades de la lista blanca.\n *\n * Esto evita el ataque de \"mass assignment\": si el cliente envia\n * { primerNombre: \"Ana\", id: 999, estado: 1 } no queremos que pueda\n * cambiar el id a su antojo. Solo copiamos lo que la API permite.\n *\n * @param {object} objeto\n * @param {string[]} camposPermitidos\n * @returns {object}\n */\nfunction soloCamposPermitidos(objeto, camposPermitidos) {\n  const resultado = {};\n\n  if (objeto === null || typeof objeto !== 'object') return resultado;\n\n  for (const campo of camposPermitidos) {\n    // Object.hasOwn comprueba que la propiedad sea del objeto mismo\n    // y no heredada del prototipo.\n    if (Object.hasOwn(objeto, campo)) {\n      resultado[campo] = objeto[campo];\n    }\n  }\n\n  return resultado;\n}\n\n/**\n * Indica si un objeto no tiene ninguna propiedad propia.\n * Se usa para rechazar peticiones PUT/POST con el cuerpo vacio.\n *\n * @param {object} objeto\n * @returns {boolean}\n */\nfunction estaVacio(objeto) {\n  return (\n    objeto === null ||\n    objeto === undefined ||\n    typeof objeto !== 'object' ||\n    Object.keys(objeto).length === 0\n  );\n}\n\nmodule.exports = {\n  limpiarTexto,\n  aTituloPropio,\n  normalizarTelefono,\n  normalizarURL,\n  aEnteroONulo,\n  aBanderaEntera,\n  soloCamposPermitidos,\n  estaVacio\n};\n","persona-api/utils/mensajes.js":"/**\n * utils/mensajes.js\n * ---------------------------------------------------------------------\n * Catalogo centralizado de mensajes para el usuario final.\n *\n * Ventajas de centralizarlos:\n *  1. Consistencia: el mismo error siempre dice lo mismo.\n *  2. Traduccion: si manana la app debe estar en ingles, se traduce\n *     este archivo y nada mas.\n *  3. Pruebas: los tests comparan contra la constante, no contra texto\n *     escrito a mano.\n *\n * Algunos mensajes son FUNCIONES (plantillas) porque necesitan recibir\n * un dato, por ejemplo el nombre del campo que fallo.\n */\n\nconst MENSAJES = Object.freeze({\n  // ---------- Mensajes de exito ----------\n  EXITO: Object.freeze({\n    LISTA: (entidad) => `Lista de ${entidad} obtenida correctamente.`,\n    DETALLE: (entidad) => `${entidad} encontrado correctamente.`,\n    CREADO: (entidad) => `${entidad} creado correctamente.`,\n    ACTUALIZADO: (entidad) => `${entidad} actualizado correctamente.`,\n    ELIMINADO: (entidad) => `${entidad} eliminado correctamente.`\n  }),\n\n  // ---------- Mensajes de validacion ----------\n  VALIDACION: Object.freeze({\n    CUERPO_VACIO: 'El cuerpo de la peticion no puede estar vacio.',\n    REQUERIDO: (campo) => `El campo \"${campo}\" es obligatorio.`,\n    TEXTO: (campo) => `El campo \"${campo}\" debe ser texto.`,\n    LONGITUD_MAXIMA: (campo, max) =>\n      `El campo \"${campo}\" no puede superar ${max} caracteres.`,\n    SOLO_LETRAS: (campo) =>\n      `El campo \"${campo}\" solo admite letras, espacios, apostrofes y guiones.`,\n    FECHA_INVALIDA: (campo) =>\n      `El campo \"${campo}\" debe tener el formato AAAA-MM-DD (por ejemplo 1995-07-24).`,\n    FECHA_FUTURA: (campo) => `El campo \"${campo}\" no puede ser una fecha futura.`,\n    ENTERO: (campo) => `El campo \"${campo}\" debe ser un numero entero.`,\n    ENTERO_POSITIVO: (campo) =>\n      `El campo \"${campo}\" debe ser un numero entero mayor que cero.`,\n    RANGO: (campo, min, max) =>\n      `El campo \"${campo}\" debe estar entre ${min} y ${max}.`,\n    VALOR_PERMITIDO: (campo, valores) =>\n      `El campo \"${campo}\" solo admite estos valores: ${valores.join(', ')}.`,\n    URL_INVALIDA: (campo) =>\n      `El campo \"${campo}\" debe ser una URL valida que empiece con http:// o https://.`,\n    TELEFONO_INVALIDO:\n      'El numero de telefono solo admite digitos, espacios, signo + y guiones (entre 7 y 20 caracteres).',\n    ID_INVALIDO: (campo) =>\n      `El parametro \"${campo}\" de la URL debe ser un numero entero positivo.`\n  }),\n\n  // ---------- Mensajes de negocio ----------\n  NEGOCIO: Object.freeze({\n    NO_ENCONTRADO: (entidad, id) => `No existe ${entidad} con id ${id}.`,\n    USUARIO_NO_EXISTE: (id) => `No existe un usuario con id ${id}.`,\n    RED_SOCIAL_NO_EXISTE: (id) => `No existe una red social con id ${id}.`,\n    PERFIL_NO_ENCONTRADO: (redSocialId, usuarioId) =>\n      `No existe un perfil social para la red ${redSocialId} y el usuario ${usuarioId}.`,\n    PERFIL_DUPLICADO: (redSocialId, usuarioId) =>\n      `El usuario ${usuarioId} ya tiene un perfil registrado en la red social ${redSocialId}.`,\n    RED_SOCIAL_DUPLICADA: (nombre) => `Ya existe una red social llamada \"${nombre}\".`,\n    TELEFONO_DUPLICADO: (numero) => `El numero de telefono \"${numero}\" ya esta registrado.`,\n    RED_SOCIAL_EN_USO: (id) =>\n      `No se puede eliminar la red social ${id} porque tiene perfiles sociales asociados.`\n  }),\n\n  // ---------- Mensajes de sistema ----------\n  SISTEMA: Object.freeze({\n    RUTA_NO_ENCONTRADA: (metodo, ruta) =>\n      `La ruta ${metodo} ${ruta} no existe en esta API.`,\n    ERROR_INTERNO:\n      'Ocurrio un error inesperado en el servidor. Revisa los logs para mas detalle.',\n    ERROR_BASE_DATOS: 'Ocurrio un error al consultar la base de datos.',\n    JSON_MAL_FORMADO: 'El cuerpo de la peticion no es un JSON valido.',\n    VARIABLE_ENTORNO_FALTANTE: (nombre) =>\n      `Falta la variable de entorno \"${nombre}\". Revisa tu archivo .env`\n  })\n});\n\nmodule.exports = MENSAJES;\n","persona-api/utils/respuesta.js":"/**\n * utils/respuesta.js\n * ---------------------------------------------------------------------\n * Constructor del \"sobre\" (envelope) de respuesta de la API.\n *\n * Por que un formato unico de respuesta?\n * Porque el frontend necesita un contrato ESTABLE. Si cada endpoint\n * responde distinto, el codigo del cliente se llena de condicionales.\n *\n * Contrato de esta API:\n *\n *   Exito:\n *   {\n *     \"ok\": true,\n *     \"mensaje\": \"Usuario creado correctamente.\",\n *     \"datos\": { ... }  o  [ ... ],\n *     \"meta\": { \"total\": 5, \"pagina\": 1, \"limite\": 50 }   <- opcional\n *   }\n *\n *   Error:\n *   {\n *     \"ok\": false,\n *     \"error\": {\n *       \"codigo\": \"VALIDACION\",\n *       \"mensaje\": \"Los datos enviados no son validos.\",\n *       \"detalles\": [ { \"campo\": \"edad\", \"mensaje\": \"...\" } ]\n *     }\n *   }\n *\n * La bandera \"ok\" permite al frontend hacer `if (respuesta.ok)` sin\n * tener que interpretar el codigo HTTP.\n */\n\nconst { HTTP } = require('./constants');\n\n/**\n * Envia una respuesta exitosa.\n *\n * @param {import('express').Response} res  Objeto response de Express.\n * @param {object} opciones\n * @param {number} opciones.estado    Codigo HTTP (defecto 200).\n * @param {string} opciones.mensaje   Texto para el usuario.\n * @param {*}      opciones.datos     Carga util (objeto o arreglo).\n * @param {object} opciones.meta      Metadatos opcionales (paginacion).\n */\nfunction exito(res, { estado = HTTP.OK, mensaje = '', datos = null, meta = null } = {}) {\n  const cuerpo = { ok: true, mensaje };\n\n  // Incluimos \"datos\" aunque sea null, para que el frontend siempre\n  // encuentre la propiedad y no tenga que preguntar si existe.\n  cuerpo.datos = datos;\n\n  // \"meta\" solo aparece cuando tiene sentido (listados paginados).\n  if (meta !== null) {\n    cuerpo.meta = meta;\n  }\n\n  return res.status(estado).json(cuerpo);\n}\n\n/**\n * Atajo para respuestas 201 Created (resultado de un POST).\n */\nfunction creado(res, { mensaje = '', datos = null } = {}) {\n  return exito(res, { estado: HTTP.CREADO, mensaje, datos });\n}\n\n/**\n * Envia una respuesta de error ya formateada.\n * Normalmente NO se llama directo: el middleware de errores la usa.\n *\n * @param {import('express').Response} res\n * @param {object} opciones\n */\nfunction error(res, { estado = HTTP.ERROR_SERVIDOR, codigo = 'INTERNO', mensaje = '', detalles = [] } = {}) {\n  const cuerpo = {\n    ok: false,\n    error: { codigo, mensaje }\n  };\n\n  if (Array.isArray(detalles) && detalles.length > 0) {\n    cuerpo.error.detalles = detalles;\n  }\n\n  return res.status(estado).json(cuerpo);\n}\n\n/**\n * Construye el objeto \"meta\" de un listado paginado.\n *\n * @param {object} opciones\n * @param {number} opciones.total    Total de registros en la tabla.\n * @param {number} opciones.pagina   Pagina solicitada.\n * @param {number} opciones.limite   Registros por pagina.\n * @param {number} opciones.devueltos Registros en esta respuesta.\n */\nfunction construirMeta({ total, pagina, limite, devueltos }) {\n  // Math.ceil redondea hacia arriba: 11 registros de 5 en 5 -> 3 paginas.\n  const totalPaginas = limite > 0 ? Math.ceil(total / limite) : 0;\n\n  return {\n    total,\n    pagina,\n    limite,\n    devueltos,\n    totalPaginas,\n    hayPaginaSiguiente: pagina < totalPaginas,\n    hayPaginaAnterior: pagina > 1\n  };\n}\n\nmodule.exports = { exito, creado, error, construirMeta };\n","persona-api/utils/validadores.js":"/**\n * utils/validadores.js\n * ---------------------------------------------------------------------\n * Validadores personalizados + la clase ColectorErrores.\n *\n * Filosofia de validacion de esta API:\n *   NO cortamos en el primer error. Revisamos TODOS los campos y\n *   devolvemos la lista completa de problemas en una sola respuesta.\n *   Asi el usuario corrige el formulario una vez y no de a un campo.\n *\n * Para lograrlo usamos la clase ColectorErrores, que va acumulando\n * los errores encontrados (patron \"Notification\" de Martin Fowler).\n */\n\nconst MENSAJES = require('./mensajes');\nconst { LIMITES } = require('./constants');\n\n// ---------------------------------------------------------------------\n// Expresiones regulares reutilizables\n// ---------------------------------------------------------------------\n\n// Letras del espanol (incluye tildes y enie), espacios, apostrofe y guion.\n// À-ɏ cubre los caracteres latinos acentuados en Unicode.\nconst PATRON_NOMBRE = /^[A-Za-zÀ-ɏḀ-ỿ\\s'.-]+$/;\n\n// Digitos, signo +, guiones y espacios. Entre 7 y 20 caracteres.\nconst PATRON_TELEFONO = /^[+]?[\\d\\s-]{7,20}$/;\n\n// URL que empieza obligatoriamente con http:// o https://\nconst PATRON_URL = /^https?:\\/\\/[^\\s/$.?#].[^\\s]*$/i;\n\n// ---------------------------------------------------------------------\n// Validadores atomicos: cada funcion responde true o false\n// ---------------------------------------------------------------------\n\n/** El valor es un texto con al menos un caracter visible. */\nfunction esTextoNoVacio(valor) {\n  return typeof valor === 'string' && valor.trim().length > 0;\n}\n\n/** El texto NO supera el maximo de caracteres. */\nfunction cumpleLongitud(valor, maximo = LIMITES.VARCHAR_CORTO) {\n  return typeof valor === 'string' && valor.length <= maximo;\n}\n\n/** El texto solo contiene letras, espacios, apostrofes, puntos y guiones. */\nfunction esSoloLetras(valor) {\n  return typeof valor === 'string' && PATRON_NOMBRE.test(valor);\n}\n\n/** El valor es un numero entero (positivo, negativo o cero). */\nfunction esEntero(valor) {\n  return Number.isInteger(Number(valor)) && String(valor).trim() !== '';\n}\n\n/** El valor es un numero entero mayor que cero. Se usa para los id. */\nfunction esEnteroPositivo(valor) {\n  const numero = Number(valor);\n  return Number.isInteger(numero) && numero > 0;\n}\n\n/** El numero esta dentro del rango inclusivo [minimo, maximo]. */\nfunction estaEnRango(valor, minimo, maximo) {\n  const numero = Number(valor);\n  return Number.isFinite(numero) && numero >= minimo && numero <= maximo;\n}\n\n/** El valor pertenece a una lista cerrada de opciones. */\nfunction estaEnLista(valor, listaPermitida) {\n  return listaPermitida.includes(valor);\n}\n\n/** El texto tiene forma de URL http(s). */\nfunction esURLValida(valor) {\n  return typeof valor === 'string' && PATRON_URL.test(valor);\n}\n\n/** El texto tiene forma de numero telefonico. */\nfunction esTelefonoValido(valor) {\n  return typeof valor === 'string' && PATRON_TELEFONO.test(valor);\n}\n\n// ---------------------------------------------------------------------\n// Clase ColectorErrores\n// ---------------------------------------------------------------------\n\n/**\n * Acumula errores de validacion en forma de { campo, mensaje }.\n *\n * Uso tipico dentro de un service:\n *\n *   const errores = new ColectorErrores();\n *   errores.exigirTexto('primerNombre', datos.primerNombre);\n *   errores.exigirFecha('fechaNacimiento', datos.fechaNacimiento);\n *   errores.lanzarSiHay('Los datos del usuario no son validos.');\n *\n * Fijate en el patron: encadenamos comprobaciones y al final una sola\n * linea decide si lanzar la excepcion o continuar.\n */\nclass ColectorErrores {\n  // Atributo privado: nadie puede manipular la lista desde afuera.\n  #errores;\n\n  constructor() {\n    this.#errores = [];\n  }\n\n  // -------- Getters --------\n\n  /** Copia de la lista de errores (para no exponer el arreglo interno). */\n  get errores() {\n    return [...this.#errores];\n  }\n\n  /** Cantidad de errores acumulados. */\n  get cantidad() {\n    return this.#errores.length;\n  }\n\n  /** true si no se encontro ningun error. */\n  get esValido() {\n    return this.#errores.length === 0;\n  }\n\n  // -------- Metodos de registro --------\n\n  /**\n   * Agrega un error a la lista.\n   * Devuelve `this` para poder encadenar llamadas (patron fluent).\n   */\n  agregar(campo, mensaje) {\n    this.#errores.push({ campo, mensaje });\n    return this;\n  }\n\n  /**\n   * Agrega el error solo si la condicion es verdadera.\n   * Es azucar sintactico para no escribir `if` en cada validacion.\n   */\n  agregarSi(condicion, campo, mensaje) {\n    if (condicion) {\n      this.agregar(campo, mensaje);\n    }\n    return this;\n  }\n\n  // -------- Validaciones de alto nivel --------\n  // Cada metodo valida un tipo de dato completo y agrega todos los\n  // errores que encuentre para ese campo.\n\n  /**\n   * Campo de texto. Valida presencia, longitud y (opcional) que sean\n   * solo letras.\n   *\n   * @param {string}  campo        Nombre del campo, para el mensaje.\n   * @param {*}       valor        Valor a validar.\n   * @param {object}  opciones\n   * @param {boolean} opciones.requerido   Si es obligatorio (defecto true).\n   * @param {number}  opciones.maximo      Longitud maxima (defecto 45).\n   * @param {boolean} opciones.soloLetras  Si debe ser solo letras (defecto false).\n   */\n  exigirTexto(campo, valor, opciones = {}) {\n    const {\n      requerido = true,\n      maximo = LIMITES.VARCHAR_CORTO,\n      soloLetras = false\n    } = opciones;\n\n    // Caso 1: el campo viene vacio o nulo.\n    const estaAusente = valor === null || valor === undefined || valor === '';\n\n    if (estaAusente) {\n      // Solo es error si el campo era obligatorio.\n      if (requerido) {\n        this.agregar(campo, MENSAJES.VALIDACION.REQUERIDO(campo));\n      }\n      // Si era opcional y no vino, no hay nada mas que validar.\n      return this;\n    }\n\n    // Caso 2: vino algo pero no es texto.\n    if (typeof valor !== 'string') {\n      return this.agregar(campo, MENSAJES.VALIDACION.TEXTO(campo));\n    }\n\n    // Caso 3: vino texto. Validamos sus reglas.\n    this.agregarSi(\n      !esTextoNoVacio(valor),\n      campo,\n      MENSAJES.VALIDACION.REQUERIDO(campo)\n    );\n\n    this.agregarSi(\n      !cumpleLongitud(valor, maximo),\n      campo,\n      MENSAJES.VALIDACION.LONGITUD_MAXIMA(campo, maximo)\n    );\n\n    if (soloLetras && esTextoNoVacio(valor)) {\n      this.agregarSi(\n        !esSoloLetras(valor),\n        campo,\n        MENSAJES.VALIDACION.SOLO_LETRAS(campo)\n      );\n    }\n\n    return this;\n  }\n\n  /**\n   * Campo de fecha en formato AAAA-MM-DD.\n   * Importamos fechas.js aqui dentro (y no arriba del archivo) para\n   * evitar una dependencia circular entre los dos modulos de utils.\n   */\n  exigirFecha(campo, valor, opciones = {}) {\n    const { requerido = true, permitirFutura = false } = opciones;\n    const fechas = require('./fechas');\n\n    const estaAusente = valor === null || valor === undefined || valor === '';\n\n    if (estaAusente) {\n      if (requerido) {\n        this.agregar(campo, MENSAJES.VALIDACION.REQUERIDO(campo));\n      }\n      return this;\n    }\n\n    const iso = fechas.aFechaISO(valor);\n\n    if (iso === null) {\n      return this.agregar(campo, MENSAJES.VALIDACION.FECHA_INVALIDA(campo));\n    }\n\n    if (!permitirFutura && fechas.esFechaFutura(iso)) {\n      this.agregar(campo, MENSAJES.VALIDACION.FECHA_FUTURA(campo));\n    }\n\n    return this;\n  }\n\n  /** Campo entero, con rango opcional. */\n  exigirEntero(campo, valor, opciones = {}) {\n    const { requerido = true, minimo = null, maximo = null } = opciones;\n\n    const estaAusente = valor === null || valor === undefined || valor === '';\n\n    if (estaAusente) {\n      if (requerido) {\n        this.agregar(campo, MENSAJES.VALIDACION.REQUERIDO(campo));\n      }\n      return this;\n    }\n\n    if (!esEntero(valor)) {\n      return this.agregar(campo, MENSAJES.VALIDACION.ENTERO(campo));\n    }\n\n    if (minimo !== null && maximo !== null && !estaEnRango(valor, minimo, maximo)) {\n      this.agregar(campo, MENSAJES.VALIDACION.RANGO(campo, minimo, maximo));\n    }\n\n    return this;\n  }\n\n  /** Identificador: entero positivo obligatorio. */\n  exigirId(campo, valor) {\n    if (!esEnteroPositivo(valor)) {\n      this.agregar(campo, MENSAJES.VALIDACION.ID_INVALIDO(campo));\n    }\n    return this;\n  }\n\n  /** Campo URL http(s), con tope de longitud. */\n  exigirURL(campo, valor, opciones = {}) {\n    const { requerido = true, maximo = LIMITES.VARCHAR_CORTO } = opciones;\n\n    const estaAusente = valor === null || valor === undefined || valor === '';\n\n    if (estaAusente) {\n      if (requerido) {\n        this.agregar(campo, MENSAJES.VALIDACION.REQUERIDO(campo));\n      }\n      return this;\n    }\n\n    if (!esURLValida(valor)) {\n      return this.agregar(campo, MENSAJES.VALIDACION.URL_INVALIDA(campo));\n    }\n\n    this.agregarSi(\n      !cumpleLongitud(valor, maximo),\n      campo,\n      MENSAJES.VALIDACION.LONGITUD_MAXIMA(campo, maximo)\n    );\n\n    return this;\n  }\n\n  /** Campo de numero telefonico. */\n  exigirTelefono(campo, valor, opciones = {}) {\n    const { requerido = true } = opciones;\n\n    const estaAusente = valor === null || valor === undefined || valor === '';\n\n    if (estaAusente) {\n      if (requerido) {\n        this.agregar(campo, MENSAJES.VALIDACION.REQUERIDO(campo));\n      }\n      return this;\n    }\n\n    this.agregarSi(\n      !esTelefonoValido(String(valor)),\n      campo,\n      MENSAJES.VALIDACION.TELEFONO_INVALIDO\n    );\n\n    return this;\n  }\n\n  /** El valor debe pertenecer a una lista cerrada. */\n  exigirValorDeLista(campo, valor, listaPermitida, opciones = {}) {\n    const { requerido = true } = opciones;\n\n    const estaAusente = valor === null || valor === undefined || valor === '';\n\n    if (estaAusente) {\n      if (requerido) {\n        this.agregar(campo, MENSAJES.VALIDACION.REQUERIDO(campo));\n      }\n      return this;\n    }\n\n    this.agregarSi(\n      !estaEnLista(valor, listaPermitida),\n      campo,\n      MENSAJES.VALIDACION.VALOR_PERMITIDO(campo, listaPermitida)\n    );\n\n    return this;\n  }\n\n  // -------- Cierre --------\n\n  /**\n   * Si hay errores acumulados, lanza un AppError de validacion con la\n   * lista completa. Si no hay errores, no hace nada y la ejecucion sigue.\n   *\n   * Requerimos AppError aqui dentro para evitar dependencia circular.\n   */\n  lanzarSiHay(mensaje = 'Los datos enviados no son validos.') {\n    if (!this.esValido) {\n      const AppError = require('./AppError');\n      throw AppError.validacion(mensaje, this.errores);\n    }\n  }\n}\n\nmodule.exports = {\n  PATRON_NOMBRE,\n  PATRON_TELEFONO,\n  PATRON_URL,\n  esTextoNoVacio,\n  cumpleLongitud,\n  esSoloLetras,\n  esEntero,\n  esEnteroPositivo,\n  estaEnRango,\n  estaEnLista,\n  esURLValida,\n  esTelefonoValido,\n  ColectorErrores\n};\n","persona-frontend/css/01-tokens/_colores.css":"/* =====================================================================\n   01-tokens/_colores.css\n   ---------------------------------------------------------------------\n   PALETA DEL SISTEMA DE DISENIO, basada en Material Design 3.\n\n   QUE ES UN TOKEN DE DISENIO?\n   Es una variable con un nombre SEMANTICO en lugar de un valor suelto.\n\n     MAL:  color: #6750a4;        <- que es ese color? donde mas se usa?\n     BIEN: color: var(--color-primario);\n\n   Si el cliente pide cambiar el morado por un azul, se cambia UNA\n   linea aqui y toda la aplicacion se actualiza. Sin tokens habria que\n   buscar y reemplazar el hexadecimal en 30 archivos.\n\n   NOMENCLATURA DE MATERIAL DESIGN 3 (roles de color):\n     primario            -> acciones principales (botones, enlaces)\n     sobre-primario      -> texto que va ENCIMA del primario\n     contenedor-primario -> fondos suaves con el tono del primario\n     superficie          -> fondo de tarjetas y paneles\n     contorno            -> bordes y separadores\n\n   La palabra \"sobre\" (del ingles \"on\") indica que ese color esta\n   pensado para ir ENCIMA del otro, con contraste suficiente para\n   cumplir la norma de accesibilidad WCAG AA (relacion 4.5:1).\n   ===================================================================== */\n\n:root {\n  /* ---------- Color primario (morado Material) ---------- */\n  --color-primario: #6750a4;\n  --color-sobre-primario: #ffffff;\n  --color-contenedor-primario: #eaddff;\n  --color-sobre-contenedor-primario: #21005d;\n\n  /* ---------- Color secundario (acentos y chips) ---------- */\n  --color-secundario: #625b71;\n  --color-sobre-secundario: #ffffff;\n  --color-contenedor-secundario: #e8def8;\n  --color-sobre-contenedor-secundario: #1d192b;\n\n  /* ---------- Color terciario (datos y graficos) ---------- */\n  --color-terciario: #7d5260;\n  --color-contenedor-terciario: #ffd8e4;\n  --color-sobre-contenedor-terciario: #31111d;\n\n  /* ---------- Error ---------- */\n  --color-error: #b3261e;\n  --color-sobre-error: #ffffff;\n  --color-contenedor-error: #f9dedc;\n  --color-sobre-contenedor-error: #410e0b;\n\n  /* ---------- Exito y advertencia (no son de Material 3,\n                los agregamos porque la app los necesita) ---------- */\n  --color-exito: #1b6b3a;\n  --color-contenedor-exito: #d7f5e2;\n  --color-sobre-contenedor-exito: #042913;\n\n  --color-advertencia: #8a5300;\n  --color-contenedor-advertencia: #ffeccd;\n  --color-sobre-contenedor-advertencia: #2b1700;\n\n  /* ---------- Superficies (fondos) ---------- */\n  --color-fondo: #fef7ff;\n  --color-sobre-fondo: #1d1b20;\n  --color-superficie: #ffffff;\n  --color-sobre-superficie: #1d1b20;\n\n  /* Variantes de superficie para crear jerarquia por elevacion. */\n  --color-superficie-variante: #e7e0ec;\n  --color-sobre-superficie-variante: #49454f;\n  --color-superficie-contenedor-bajo: #f7f2fa;\n  --color-superficie-contenedor: #f3edf7;\n  --color-superficie-contenedor-alto: #ece6f0;\n\n  /* ---------- Contornos ---------- */\n  --color-contorno: #79747e;\n  --color-contorno-variante: #cac4d0;\n\n  /* ---------- Capas de estado (state layers) ---------- */\n  /* Material superpone el color del elemento con una opacidad baja\n     para indicar hover, focus o pressed. Estos son los valores\n     oficiales de la especificacion. */\n  --opacidad-hover: 0.08;\n  --opacidad-foco: 0.12;\n  --opacidad-presionado: 0.12;\n  --opacidad-deshabilitado: 0.38;\n\n  /* Sombra base para las elevaciones. */\n  --color-sombra: 0 0 0;\n}\n\n/* ---------------------------------------------------------------------\n   TEMA OSCURO\n   ---------------------------------------------------------------------\n   Se aplica con DOS selectores, y el orden importa:\n\n   1. @media (prefers-color-scheme: dark) + :root:not([data-tema=\"light\"])\n      -> sigue la preferencia del sistema operativo, salvo que el\n         usuario haya elegido explicitamente el tema claro.\n\n   2. :root[data-tema=\"dark\"]\n      -> el usuario eligio oscuro a mano con el boton de la barra.\n\n   Fijate que en Material 3 el tema oscuro NO es \"invertir los colores\":\n   el primario se vuelve mas claro y menos saturado, porque un morado\n   oscuro sobre fondo negro no tendria contraste suficiente.\n   --------------------------------------------------------------------- */\n@media (prefers-color-scheme: dark) {\n  :root:not([data-tema=\"light\"]) {\n    --color-primario: #d0bcff;\n    --color-sobre-primario: #381e72;\n    --color-contenedor-primario: #4f378b;\n    --color-sobre-contenedor-primario: #eaddff;\n\n    --color-secundario: #ccc2dc;\n    --color-sobre-secundario: #332d41;\n    --color-contenedor-secundario: #4a4458;\n    --color-sobre-contenedor-secundario: #e8def8;\n\n    --color-terciario: #efb8c8;\n    --color-contenedor-terciario: #633b48;\n    --color-sobre-contenedor-terciario: #ffd8e4;\n\n    --color-error: #f2b8b5;\n    --color-sobre-error: #601410;\n    --color-contenedor-error: #8c1d18;\n    --color-sobre-contenedor-error: #f9dedc;\n\n    --color-exito: #7adf9f;\n    --color-contenedor-exito: #0f4d28;\n    --color-sobre-contenedor-exito: #d7f5e2;\n\n    --color-advertencia: #ffcf8b;\n    --color-contenedor-advertencia: #5d3a00;\n    --color-sobre-contenedor-advertencia: #ffeccd;\n\n    --color-fondo: #141218;\n    --color-sobre-fondo: #e6e0e9;\n    --color-superficie: #1d1b20;\n    --color-sobre-superficie: #e6e0e9;\n\n    --color-superficie-variante: #49454f;\n    --color-sobre-superficie-variante: #cac4d0;\n    --color-superficie-contenedor-bajo: #1d1b20;\n    --color-superficie-contenedor: #211f26;\n    --color-superficie-contenedor-alto: #2b2930;\n\n    --color-contorno: #938f99;\n    --color-contorno-variante: #49454f;\n  }\n}\n\n/* Tema oscuro forzado por el usuario. Repetimos los valores porque un\n   @media no se puede \"reutilizar\" desde otro selector en CSS puro. */\n:root[data-tema=\"dark\"] {\n  --color-primario: #d0bcff;\n  --color-sobre-primario: #381e72;\n  --color-contenedor-primario: #4f378b;\n  --color-sobre-contenedor-primario: #eaddff;\n\n  --color-secundario: #ccc2dc;\n  --color-sobre-secundario: #332d41;\n  --color-contenedor-secundario: #4a4458;\n  --color-sobre-contenedor-secundario: #e8def8;\n\n  --color-terciario: #efb8c8;\n  --color-contenedor-terciario: #633b48;\n  --color-sobre-contenedor-terciario: #ffd8e4;\n\n  --color-error: #f2b8b5;\n  --color-sobre-error: #601410;\n  --color-contenedor-error: #8c1d18;\n  --color-sobre-contenedor-error: #f9dedc;\n\n  --color-exito: #7adf9f;\n  --color-contenedor-exito: #0f4d28;\n  --color-sobre-contenedor-exito: #d7f5e2;\n\n  --color-advertencia: #ffcf8b;\n  --color-contenedor-advertencia: #5d3a00;\n  --color-sobre-contenedor-advertencia: #ffeccd;\n\n  --color-fondo: #141218;\n  --color-sobre-fondo: #e6e0e9;\n  --color-superficie: #1d1b20;\n  --color-sobre-superficie: #e6e0e9;\n\n  --color-superficie-variante: #49454f;\n  --color-sobre-superficie-variante: #cac4d0;\n  --color-superficie-contenedor-bajo: #1d1b20;\n  --color-superficie-contenedor: #211f26;\n  --color-superficie-contenedor-alto: #2b2930;\n\n  --color-contorno: #938f99;\n  --color-contorno-variante: #49454f;\n}\n","persona-frontend/css/02-base/_reset.css":"/* =====================================================================\n   02-base/_reset.css\n   ---------------------------------------------------------------------\n   REINICIO (reset) de los estilos por defecto del navegador.\n\n   POR QUE HACE FALTA?\n   Cada navegador trae su propia hoja de estilos. Chrome, Firefox y\n   Safari ponen margenes distintos a un <h1> y rellenos distintos a un\n   <button>. El reset los pone a todos en el mismo punto de partida,\n   para que lo que disenamos se vea igual en todos.\n\n   Este reset es moderno y minimo: no borra TODO (como el viejo\n   reset de Eric Meyer), solo normaliza lo que de verdad estorba.\n   ===================================================================== */\n\n/* ---------------------------------------------------------------------\n   1. Modelo de caja predecible\n   ---------------------------------------------------------------------\n   Por defecto, un elemento con width: 200px y padding: 20px mide\n   240px en total. Es contraintuitivo y produce desbordes constantes.\n\n   Con border-box, el padding y el borde van DENTRO del ancho\n   declarado: width: 200px mide 200px, punto. Es la primera regla que\n   escribe cualquier desarrollador frontend.\n   --------------------------------------------------------------------- */\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\n/* ---------------------------------------------------------------------\n   2. Quitar los margenes por defecto\n   ---------------------------------------------------------------------\n   Los navegadores ponen margin a titulos, parrafos y listas. Preferimos\n   partir de cero y declarar el espaciado nosotros con los tokens, para\n   no andar \"peleando\" con margenes que no pedimos.\n   --------------------------------------------------------------------- */\n* {\n  margin: 0;\n}\n\n/* ---------------------------------------------------------------------\n   3. Base del documento\n   --------------------------------------------------------------------- */\nhtml {\n  /* Desplazamiento suave al navegar con enlaces internos. */\n  scroll-behavior: smooth;\n\n  /* -webkit-text-size-adjust evita que Safari en iOS agrande el texto\n     solo al girar el telefono a horizontal. */\n  -webkit-text-size-adjust: 100%;\n}\n\nbody {\n  /* min-height: 100dvh usa la unidad \"dynamic viewport height\", que SI\n     descuenta la barra de direcciones del navegador movil. Con 100vh,\n     en iOS quedaba un hueco al final de la pagina. */\n  min-height: 100dvh;\n\n  /* Suavizado de fuentes: hace el texto mas nitido en pantallas Retina. */\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\n/* ---------------------------------------------------------------------\n   4. Contenido multimedia\n   ---------------------------------------------------------------------\n   display: block quita el espacio fantasma que deja el navegador\n   debajo de una imagen (porque la trata como texto en linea).\n   max-width: 100% evita que una imagen grande rompa el diseno.\n   --------------------------------------------------------------------- */\nimg,\npicture,\nvideo,\ncanvas,\nsvg {\n  display: block;\n  max-width: 100%;\n}\n\n/* ---------------------------------------------------------------------\n   5. Formularios\n   ---------------------------------------------------------------------\n   Los controles de formulario NO heredan la fuente del documento: el\n   navegador les pone su propia fuente del sistema. Hay que decirselo\n   de forma explicita o los inputs se ven distintos al resto del texto.\n   --------------------------------------------------------------------- */\ninput,\nbutton,\ntextarea,\nselect {\n  font: inherit;\n  color: inherit;\n}\n\nbutton {\n  /* Reiniciamos el aspecto nativo para construir el nuestro. */\n  background: none;\n  border: none;\n  padding: 0;\n  cursor: pointer;\n\n  /* Evita la seleccion accidental del texto al hacer doble clic. */\n  user-select: none;\n\n  /* Quita el retardo de 300ms al tocar en moviles. */\n  touch-action: manipulation;\n}\n\n/* ---------------------------------------------------------------------\n   6. Texto largo sin espacios\n   ---------------------------------------------------------------------\n   overflow-wrap: break-word parte las palabras larguisimas (una URL\n   sin espacios, por ejemplo) para que no desborden su contenedor.\n   --------------------------------------------------------------------- */\np,\nh1, h2, h3, h4, h5, h6,\nli,\ntd, th {\n  overflow-wrap: break-word;\n}\n\n/* Los titulos no deben heredar tamanios gigantes del navegador: los\n   definimos nosotros en cada componente. */\nh1, h2, h3, h4, h5, h6 {\n  font-size: inherit;\n  font-weight: inherit;\n  line-height: var(--linea-ajustada);\n}\n\n/* ---------------------------------------------------------------------\n   7. Listas\n   ---------------------------------------------------------------------\n   Solo quitamos los puntos cuando la lista lleva la clase .lista-limpia.\n   Si los quitaramos de TODAS, los lectores de pantalla de Safari\n   dejarian de anunciarlas como listas, lo que perjudica la\n   accesibilidad.\n   --------------------------------------------------------------------- */\nul.lista-limpia,\nol.lista-limpia {\n  list-style: none;\n  padding: 0;\n}\n\n/* ---------------------------------------------------------------------\n   8. Tablas\n   --------------------------------------------------------------------- */\ntable {\n  /* Sin esto, cada celda tendria su propio borde separado. */\n  border-collapse: collapse;\n  width: 100%;\n}\n\n/* ---------------------------------------------------------------------\n   9. Enlaces\n   --------------------------------------------------------------------- */\na {\n  color: inherit;\n  text-decoration: none;\n}\n\n/* ---------------------------------------------------------------------\n   10. FOCO VISIBLE: accesibilidad obligatoria\n   ---------------------------------------------------------------------\n   Nunca, jamas, se escribe `outline: none` sin poner un reemplazo.\n   Quien navega con teclado (por discapacidad motriz, o simplemente\n   por rapidez) depende del contorno para saber donde esta parado.\n\n   :focus-visible es mejor que :focus porque el navegador decide: solo\n   muestra el contorno cuando se navega con TECLADO, no al hacer clic\n   con el raton. Asi se cuida la accesibilidad sin \"ensuciar\" la\n   interfaz del usuario de mouse.\n   --------------------------------------------------------------------- */\n:focus-visible {\n  outline: 3px solid var(--color-primario);\n  outline-offset: 2px;\n  border-radius: var(--radio-extra-pequeno);\n}\n\n/* ---------------------------------------------------------------------\n   11. Respeto por quien prefiere menos movimiento\n   ---------------------------------------------------------------------\n   Algunas personas sufren mareo o migranias con las animaciones.\n   El sistema operativo tiene un ajuste para pedir menos movimiento, y\n   es nuestra obligacion respetarlo.\n\n   No lo ponemos en 0s sino en 0.01ms: asi los eventos\n   transitionend y animationend SIGUEN disparandose y el JavaScript\n   que dependa de ellos no se rompe.\n   --------------------------------------------------------------------- */\n@media (prefers-reduced-motion: reduce) {\n  *,\n  *::before,\n  *::after {\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: 0.01ms !important;\n    scroll-behavior: auto !important;\n  }\n}\n","persona-frontend/css/03-atomos/_a-boton.css":"/* =====================================================================\n   03-atomos/_a-boton.css\n   ---------------------------------------------------------------------\n   ATOMO: Boton\n\n   ATOMIC DESIGN - NIVEL 1: ATOMOS\n   Un atomo es el componente mas pequeno que ya no se puede dividir sin\n   perder su sentido. Un boton, un campo de texto, una etiqueta, un\n   icono. No depende de ningun otro componente para funcionar.\n\n   NOMENCLATURA DEL PROYECTO: prefijo + BEM\n   ---------------------------------------------------------------------\n     a-  atomo        .a-boton\n     m-  molecula     .m-campo-formulario\n     o-  organismo    .o-tabla-datos\n     t-  plantilla    .t-panel-administracion\n     p-  pagina       .p-usuarios\n\n   Y dentro de cada componente usamos BEM:\n\n     .a-boton            <- BLOQUE   (el componente)\n     .a-boton__icono     <- ELEMENTO (una parte interna, con __)\n     .a-boton--primario  <- MODIFICADOR (una variante, con --)\n\n   Ventaja practica: al leer una clase en el HTML sabes de inmediato\n   su nivel, si es una parte o una variante, y en que archivo buscarla.\n   El archivo de .a-boton es, siempre, 03-atomos/_a-boton.css\n   ===================================================================== */\n\n.a-boton {\n  /* Flex para alinear el icono con el texto. */\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: var(--espacio-2);\n\n  /* Altura minima de 44px: el area de toque recomendada para que un\n     dedo acierte sin fallar (criterio WCAG 2.5.5). */\n  min-height: var(--altura-objetivo-toque);\n  padding: var(--espacio-2) var(--espacio-6);\n\n  /* Pildora: el rasgo visual mas caracteristico de Material 3. */\n  border-radius: var(--radio-completo);\n\n  font-size: var(--texto-etiqueta-grande);\n  font-weight: var(--peso-medio);\n  letter-spacing: var(--letra-amplia);\n  line-height: 1.25;\n  white-space: nowrap;\n\n  cursor: pointer;\n  transition: var(--transicion-normal);\n\n  /* position: relative prepara el terreno para la \"capa de estado\"\n     (el ::before de abajo), que se posiciona de forma absoluta. */\n  position: relative;\n  overflow: hidden;\n}\n\n/* ---------------------------------------------------------------------\n   CAPA DE ESTADO (state layer)\n   ---------------------------------------------------------------------\n   Material no cambia el color del boton al pasar el puntero: le\n   superpone una capa del color del TEXTO con una opacidad baja.\n\n   Por que es mejor que cambiar el background?\n   Porque funciona igual para todas las variantes del boton sin tener\n   que calcular un color de hover distinto para cada una. Una sola\n   regla cubre el boton relleno, el de contorno y el de texto.\n   --------------------------------------------------------------------- */\n.a-boton::before {\n  content: \"\";\n  position: absolute;\n  inset: 0; /* atajo de top/right/bottom/left: 0 */\n\n  background-color: currentColor;\n  opacity: 0;\n  transition: opacity var(--duracion-corta) var(--curva-estandar);\n\n  /* Sin esto, la capa robaria los clics destinados al boton. */\n  pointer-events: none;\n}\n\n.a-boton:hover::before {\n  opacity: var(--opacidad-hover);\n}\n\n.a-boton:active::before {\n  opacity: var(--opacidad-presionado);\n}\n\n/* ---------------------------------------------------------------------\n   VARIANTE: relleno (filled). Es el boton de la accion PRINCIPAL.\n   Regla de oro: solo UN boton relleno por pantalla o por dialogo. Si\n   todo es principal, nada lo es.\n   --------------------------------------------------------------------- */\n.a-boton--primario {\n  background-color: var(--color-primario);\n  color: var(--color-sobre-primario);\n  box-shadow: var(--elevacion-0);\n}\n\n.a-boton--primario:hover {\n  box-shadow: var(--elevacion-1);\n}\n\n/* ---------------------------------------------------------------------\n   VARIANTE: tonal. Menos peso que el relleno, mas que el de contorno.\n   Para acciones secundarias importantes.\n   --------------------------------------------------------------------- */\n.a-boton--tonal {\n  background-color: var(--color-contenedor-secundario);\n  color: var(--color-sobre-contenedor-secundario);\n}\n\n/* ---------------------------------------------------------------------\n   VARIANTE: contorno (outlined). Acciones secundarias.\n   --------------------------------------------------------------------- */\n.a-boton--contorno {\n  background-color: transparent;\n  color: var(--color-primario);\n  border: 1px solid var(--color-contorno);\n}\n\n.a-boton--contorno:hover {\n  border-color: var(--color-primario);\n}\n\n/* ---------------------------------------------------------------------\n   VARIANTE: texto. La de menor jerarquia. Para \"Cancelar\", \"Ver mas\".\n   --------------------------------------------------------------------- */\n.a-boton--texto {\n  background-color: transparent;\n  color: var(--color-primario);\n  padding-inline: var(--espacio-3);\n}\n\n/* ---------------------------------------------------------------------\n   VARIANTE: peligro. Para acciones destructivas (eliminar).\n   El color rojo funciona como advertencia visual antes del clic.\n   --------------------------------------------------------------------- */\n.a-boton--peligro {\n  background-color: var(--color-error);\n  color: var(--color-sobre-error);\n}\n\n/* ---------------------------------------------------------------------\n   VARIANTE: icono. Un boton cuadrado que solo contiene un icono.\n   SIEMPRE necesita aria-label, porque no tiene texto visible que el\n   lector de pantalla pueda anunciar.\n   --------------------------------------------------------------------- */\n.a-boton--icono {\n  width: var(--altura-objetivo-toque);\n  min-width: var(--altura-objetivo-toque);\n  padding: 0;\n  border-radius: var(--radio-completo);\n  color: var(--color-sobre-superficie-variante);\n}\n\n.a-boton--icono-pequeno {\n  width: 2.25rem;\n  min-width: 2.25rem;\n  min-height: 2.25rem;\n}\n\n/* ---------------------------------------------------------------------\n   MODIFICADOR: ancho completo. Util en moviles y dentro de modales.\n   --------------------------------------------------------------------- */\n.a-boton--bloque {\n  display: flex;\n  width: 100%;\n}\n\n/* ---------------------------------------------------------------------\n   ESTADO: deshabilitado\n   ---------------------------------------------------------------------\n   Usamos el atributo [disabled] y no una clase, porque el atributo\n   tambien impide el clic y saca el boton del orden de tabulacion.\n   Una clase solo cambiaria el aspecto: el boton seguiria siendo\n   funcional, lo cual es un error de accesibilidad.\n   --------------------------------------------------------------------- */\n.a-boton[disabled],\n.a-boton[aria-disabled=\"true\"] {\n  opacity: var(--opacidad-deshabilitado);\n  cursor: not-allowed;\n  box-shadow: none;\n}\n\n/* Un boton deshabilitado no reacciona al puntero. */\n.a-boton[disabled]::before,\n.a-boton[aria-disabled=\"true\"]::before {\n  display: none;\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: icono interno del boton\n   --------------------------------------------------------------------- */\n.a-boton__icono {\n  width: 1.125rem;\n  height: 1.125rem;\n\n  /* flex-shrink: 0 evita que el icono se achique si el texto es largo. */\n  flex-shrink: 0;\n}\n","persona-frontend/css/04-moleculas/_m-campo-formulario.css":"/* =====================================================================\n   04-moleculas/_m-campo-formulario.css\n   ---------------------------------------------------------------------\n   MOLECULA: Campo de formulario completo\n\n   ATOMIC DESIGN - NIVEL 2: MOLECULAS\n   Una molecula es un grupo de atomos que trabajan juntos para cumplir\n   UNA funcion concreta. Por si solos, un <label>, un <input> y un\n   mensaje de error no hacen nada util; juntos forman \"un campo de\n   formulario que valida\".\n\n   COMPOSICION DE ESTA MOLECULA:\n     .a-etiqueta                 (atomo)\n     .a-campo-texto              (atomo)\n     .m-campo-formulario__ayuda  (parte propia de la molecula)\n     .m-campo-formulario__error  (parte propia de la molecula)\n\n   REGLA CLAVE DEL ATOMIC DESIGN: la molecula NO redefine el estilo de\n   sus atomos. Solo los ORGANIZA en el espacio. Si aqui escribieramos\n   `.m-campo-formulario .a-boton { background: red; }` romperiamos el\n   sistema: el mismo atomo se veria distinto en cada contexto y ya no\n   seria predecible.\n   ===================================================================== */\n\n.m-campo-formulario {\n  display: flex;\n  flex-direction: column;\n\n  /* min-width: 0 es indispensable dentro de un grid o flex. Sin esto,\n     un campo con contenido largo se niega a encogerse y desborda la\n     cuadricula del formulario. Es uno de los bugs mas comunes de CSS. */\n  min-width: 0;\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: texto de ayuda\n   ---------------------------------------------------------------------\n   Pista permanente bajo el campo (\"Formato: AAAA-MM-DD\").\n   Se conecta al input con aria-describedby para que el lector de\n   pantalla la lea despues del nombre del campo.\n   --------------------------------------------------------------------- */\n.m-campo-formulario__ayuda {\n  margin-top: var(--espacio-1);\n  padding-inline: var(--espacio-1);\n\n  font-size: var(--texto-cuerpo-pequeno);\n  color: var(--color-sobre-superficie-variante);\n  line-height: var(--linea-normal);\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: mensaje de error\n   ---------------------------------------------------------------------\n   Arranca oculto y se muestra cuando el JavaScript le pone el\n   modificador --visible, al mismo tiempo que pone aria-invalid=\"true\"\n   en el campo.\n\n   Lleva role=\"alert\" para que el lector de pantalla lo anuncie en\n   cuanto aparece, sin esperar a que el usuario llegue navegando.\n   --------------------------------------------------------------------- */\n.m-campo-formulario__error {\n  display: none;\n  align-items: flex-start;\n  gap: var(--espacio-1);\n\n  margin-top: var(--espacio-1);\n  padding-inline: var(--espacio-1);\n\n  font-size: var(--texto-cuerpo-pequeno);\n  font-weight: var(--peso-medio);\n  color: var(--color-error);\n  line-height: var(--linea-normal);\n}\n\n.m-campo-formulario__error--visible {\n  display: flex;\n}\n\n/* Icono de advertencia junto al mensaje. Refuerza el error sin\n   depender solo del color rojo. */\n.m-campo-formulario__error-icono {\n  width: 0.875rem;\n  height: 0.875rem;\n\n  /* El pequeno desplazamiento alinea el icono con la primera linea\n     del texto, no con el centro del bloque. */\n  margin-top: 0.15rem;\n  flex-shrink: 0;\n}\n\n/* ---------------------------------------------------------------------\n   MODIFICADOR: campo que ocupa las dos columnas de la cuadricula\n   --------------------------------------------------------------------- */\n.m-campo-formulario--ancho-completo {\n  grid-column: 1 / -1;\n}\n","persona-frontend/css/05-organismos/_o-formulario.css":"/* =====================================================================\n   05-organismos/_o-formulario.css\n   ---------------------------------------------------------------------\n   ORGANISMO: Formulario\n\n   Compone varias moleculas .m-campo-formulario en una cuadricula.\n\n   CUADRICULA RESPONSIVA SIN MEDIA QUERIES\n   ---------------------------------------------------------------------\n   Esta linea hace toda la magia:\n\n     grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));\n\n   Significa: \"crea tantas columnas como quepan; cada una mide al\n   menos 14rem y como maximo reparte el espacio sobrante en partes\n   iguales\".\n\n   Resultado automatico:\n     - pantalla de 360px -> 1 columna\n     - pantalla de 700px -> 2 columnas\n     - pantalla de 1100px-> 3 columnas\n\n   Sin escribir ni una media query. Si manana cambia el ancho del\n   modal, la cuadricula se reacomoda sola.\n   ===================================================================== */\n\n.o-formulario {\n  display: flex;\n  flex-direction: column;\n  gap: var(--espacio-5);\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: grupo de campos\n   ---------------------------------------------------------------------\n   Usamos <fieldset> y <legend>, que son los elementos semanticos\n   correctos para agrupar campos relacionados. El lector de pantalla\n   anuncia la leyenda al entrar al grupo: \"Datos personales, grupo\".\n   --------------------------------------------------------------------- */\n.o-formulario__grupo {\n  /* El <fieldset> trae borde y padding propios; los quitamos. */\n  border: none;\n  padding: 0;\n  margin: 0;\n\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));\n  gap: var(--espacio-4);\n}\n\n.o-formulario__leyenda {\n  /* grid-column: 1 / -1 hace que la leyenda ocupe TODAS las columnas,\n     sin importar cuantas haya generado el auto-fit. */\n  grid-column: 1 / -1;\n\n  padding: 0 0 var(--espacio-2);\n  margin-bottom: var(--espacio-1);\n\n  font-size: var(--texto-titulo-medio);\n  font-weight: var(--peso-semi);\n  color: var(--color-primario);\n  border-bottom: 1px solid var(--color-contorno-variante);\n  width: 100%;\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: resumen de errores del servidor\n   ---------------------------------------------------------------------\n   Cuando la API responde 400 con la lista de campos invalidos, la\n   mostramos completa arriba del formulario, ademas de marcar cada\n   campo.\n\n   Por que repetir la informacion? Porque si el formulario es largo,\n   el campo con error puede quedar fuera de la pantalla. El resumen\n   arriba garantiza que el usuario SEPA que algo fallo.\n\n   Lleva role=\"alert\" y tabindex=\"-1\" para que el JavaScript pueda\n   enfocarlo y el lector de pantalla lo lea de inmediato.\n   --------------------------------------------------------------------- */\n.o-formulario__resumen-errores {\n  display: none;\n\n  padding: var(--espacio-4);\n  border-radius: var(--radio-pequeno);\n  border-left: 4px solid var(--color-error);\n\n  background-color: var(--color-contenedor-error);\n  color: var(--color-sobre-contenedor-error);\n  font-size: var(--texto-cuerpo-medio);\n}\n\n.o-formulario__resumen-errores--visible {\n  display: block;\n}\n\n.o-formulario__resumen-titulo {\n  display: flex;\n  align-items: center;\n  gap: var(--espacio-2);\n\n  font-weight: var(--peso-semi);\n  margin-bottom: var(--espacio-2);\n}\n\n.o-formulario__resumen-lista {\n  margin: 0;\n  padding-left: var(--espacio-5);\n  line-height: var(--linea-amplia);\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: nota informativa\n   ---------------------------------------------------------------------\n   Para explicar reglas de negocio al aprendiz, como que la edad se\n   calcula automaticamente.\n   --------------------------------------------------------------------- */\n.o-formulario__nota {\n  display: flex;\n  align-items: flex-start;\n  gap: var(--espacio-3);\n\n  padding: var(--espacio-3) var(--espacio-4);\n  border-radius: var(--radio-pequeno);\n\n  background-color: var(--color-contenedor-primario);\n  color: var(--color-sobre-contenedor-primario);\n  font-size: var(--texto-cuerpo-pequeno);\n  line-height: var(--linea-normal);\n}\n\n.o-formulario__nota-icono {\n  width: 1rem;\n  height: 1rem;\n  margin-top: 0.15rem;\n  flex-shrink: 0;\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: campo calculado (solo lectura)\n   ---------------------------------------------------------------------\n   Muestra la edad que la aplicacion deduce de la fecha de nacimiento.\n   No es editable: se calcula en vivo con JavaScript y el servidor la\n   vuelve a calcular. Es un ejemplo visible de regla de negocio.\n   --------------------------------------------------------------------- */\n.o-formulario__calculado {\n  display: flex;\n  align-items: center;\n  gap: var(--espacio-2);\n\n  min-height: var(--altura-objetivo-toque);\n  padding: var(--espacio-3) var(--espacio-4);\n  border-radius: var(--radio-extra-pequeno);\n\n  background-color: var(--color-superficie-variante);\n  color: var(--color-sobre-superficie-variante);\n  font-size: var(--texto-cuerpo-grande);\n}\n\n.o-formulario__calculado strong {\n  color: var(--color-sobre-superficie);\n  font-variant-numeric: tabular-nums;\n}\n","persona-frontend/css/05-organismos/_o-modal.css":"/* =====================================================================\n   05-organismos/_o-modal.css\n   ---------------------------------------------------------------------\n   ORGANISMO: Ventana modal (dialogo)\n\n   USAMOS EL ELEMENTO NATIVO <dialog> DE HTML. Por que?\n   Porque el navegador nos regala gratis cosas que a mano cuestan\n   mucho codigo y se hacen mal casi siempre:\n\n     - showModal() atrapa el foco DENTRO del dialogo (focus trap).\n     - La tecla Escape lo cierra sola.\n     - El resto de la pagina queda inerte: no se puede tabular hacia\n       atras ni hacer clic por error.\n     - El velo lo dibuja el pseudo-elemento ::backdrop.\n     - Al cerrar, el foco vuelve solo al elemento que lo abrio.\n\n   Implementar todo eso con <div> y JavaScript son ~150 lineas y es la\n   fuente numero uno de modales inaccesibles en la web.\n   ===================================================================== */\n\n.o-modal {\n  /* El <dialog> nativo trae estilos propios del navegador; los\n     reiniciamos para poner los nuestros. */\n  padding: 0;\n  border: none;\n\n  /* ------------------------------------------------------------------\n     POR QUE HAY QUE REPONER margin: auto AQUI?\n     ------------------------------------------------------------------\n     El navegador centra el <dialog> con su hoja de estilos interna:\n     le pone inset: 0 y margin: auto, y ese margen automatico es lo\n     que lo deja en el centro de la pantalla.\n\n     Pero nuestro reset (02-base/_reset.css) incluye `* { margin: 0 }`,\n     que PISA ese margin: auto. Resultado: el modal aparece pegado a la\n     esquina superior izquierda.\n\n     Es un efecto secundario clasico de los resets agresivos: quitan\n     algo que el navegador necesitaba. La solucion no es renunciar al\n     reset, sino reponer el valor en el componente que lo necesita.\n     ------------------------------------------------------------------ */\n  margin: auto;\n\n  width: min(42rem, calc(100vw - 2rem));\n  max-height: calc(100dvh - 4rem);\n\n  border-radius: var(--radio-extra-grande);\n  background-color: var(--color-superficie-contenedor-alto);\n  color: var(--color-sobre-superficie);\n  box-shadow: var(--elevacion-4);\n\n  overflow: hidden;\n}\n\n/* ---------------------------------------------------------------------\n   El velo: ::backdrop es un pseudo-elemento que solo existe para\n   <dialog> y para los elementos en pantalla completa.\n   --------------------------------------------------------------------- */\n.o-modal::backdrop {\n  background-color: rgb(0 0 0 / 0.5);\n\n  /* backdrop-filter difumina el fondo. Es un efecto caro para la GPU,\n     asi que lo usamos solo aqui, donde aporta profundidad real. */\n  backdrop-filter: blur(2px);\n}\n\n/* Animacion de entrada. El selector [open] es el atributo que\n   showModal() agrega al elemento. */\n.o-modal[open] {\n  animation: o-modal-entrar var(--duracion-larga) var(--curva-enfatizada);\n}\n\n@keyframes o-modal-entrar {\n  from {\n    opacity: 0;\n    /* Escala ligeramente menor: el modal \"crece\" hacia el usuario. */\n    transform: scale(0.92) translateY(1rem);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n}\n\n/* ---------------------------------------------------------------------\n   Estructura interna: cabecera fija, cuerpo con desplazamiento,\n   pie fijo. Es el patron correcto para un formulario largo: los\n   botones de accion siempre quedan visibles.\n   --------------------------------------------------------------------- */\n.o-modal__contenido {\n  display: flex;\n  flex-direction: column;\n  max-height: inherit;\n}\n\n.o-modal__cabecera {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: var(--espacio-4);\n\n  padding: var(--espacio-5) var(--espacio-6) var(--espacio-4);\n  flex-shrink: 0;\n}\n\n.o-modal__titulo {\n  font-size: var(--texto-titular-pequeno);\n  font-weight: var(--peso-medio);\n  color: var(--color-sobre-superficie);\n  line-height: var(--linea-ajustada);\n}\n\n.o-modal__descripcion {\n  margin-top: var(--espacio-2);\n  font-size: var(--texto-cuerpo-medio);\n  color: var(--color-sobre-superficie-variante);\n  line-height: var(--linea-normal);\n}\n\n.o-modal__cuerpo {\n  padding-inline: var(--espacio-6);\n\n  /* flex: 1 + overflow-y: auto = solo el cuerpo se desplaza. */\n  flex: 1;\n  overflow-y: auto;\n\n  /* Un poco de espacio abajo para que el ultimo campo no quede pegado\n     al pie al desplazar. */\n  padding-bottom: var(--espacio-4);\n}\n\n.o-modal__pie {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: var(--espacio-2);\n\n  padding: var(--espacio-4) var(--espacio-6) var(--espacio-6);\n  flex-shrink: 0;\n}\n\n/* ---------------------------------------------------------------------\n   VARIANTE: dialogo de confirmacion (mas pequeno)\n   ---------------------------------------------------------------------\n   Para preguntar \"Seguro que quieres eliminar?\". Un borrado nunca\n   debe ocurrir con un solo clic sin confirmacion.\n   --------------------------------------------------------------------- */\n.o-modal--confirmacion {\n  width: min(28rem, calc(100vw - 2rem));\n}\n\n.o-modal--confirmacion .o-modal__cabecera {\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n  gap: var(--espacio-3);\n}\n\n/* Icono de advertencia dentro de un circulo tonal. */\n.o-modal__icono-alerta {\n  display: grid;\n  place-items: center;\n\n  width: 3.5rem;\n  height: 3.5rem;\n  border-radius: var(--radio-completo);\n\n  background-color: var(--color-contenedor-error);\n  color: var(--color-error);\n}\n\n.o-modal--confirmacion .o-modal__pie {\n  justify-content: center;\n}\n\n/* ---------------------------------------------------------------------\n   MOVIL: el modal ocupa casi toda la pantalla (\"hoja inferior\")\n   --------------------------------------------------------------------- */\n@media (max-width: 599px) {\n  .o-modal {\n    width: 100vw;\n    max-width: 100vw;\n    max-height: 92dvh;\n\n    /* Pegado al fondo y solo con las esquinas de arriba redondeadas:\n       es el patron \"bottom sheet\" de Material. */\n    margin: auto auto 0;\n    border-radius: var(--radio-extra-grande) var(--radio-extra-grande) 0 0;\n  }\n\n  .o-modal__cabecera,\n  .o-modal__cuerpo,\n  .o-modal__pie {\n    padding-inline: var(--espacio-4);\n  }\n\n  /* Los botones del pie a ancho completo y en columna invertida, para\n     que la accion principal quede arriba, al alcance del pulgar. */\n  .o-modal__pie {\n    flex-direction: column-reverse;\n  }\n\n  .o-modal__pie .a-boton {\n    width: 100%;\n  }\n}\n","persona-frontend/css/05-organismos/_o-tabla-datos.css":"/* =====================================================================\n   05-organismos/_o-tabla-datos.css\n   ---------------------------------------------------------------------\n   ORGANISMO: Tabla de datos\n\n   EL PROBLEMA MAS DIFICIL DE UNA TABLA: EL MOVIL.\n   Una tabla de 8 columnas no cabe en 360px de ancho. Hay tres\n   soluciones posibles:\n\n     1. Desplazamiento horizontal -> simple, pero incomodo de usar.\n     2. Ocultar columnas          -> se pierde informacion.\n     3. Transformar en tarjetas   -> cada fila se convierte en una\n                                     tarjeta apilada. <- la que usamos\n\n   La opcion 3 se logra con el truco de los atributos data-etiqueta:\n   el <td> guarda el nombre de su columna en data-etiqueta=\"Nombre\" y\n   en movil lo mostramos con content: attr(data-etiqueta). Asi el\n   mismo HTML sirve para tabla y para tarjetas.\n\n   ACCESIBILIDAD: usamos <table> de verdad, no <div>. Los lectores de\n   pantalla saben navegar tablas por filas y columnas y anuncian los\n   encabezados, pero solo si el HTML es semantico.\n   ===================================================================== */\n\n.o-tabla-datos-envoltura {\n  background-color: var(--color-superficie);\n  border-radius: var(--radio-medio);\n  box-shadow: var(--elevacion-1);\n  overflow: hidden;\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: cabecera del organismo (titulo + acciones)\n   --------------------------------------------------------------------- */\n.o-tabla-datos__cabecera {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--espacio-3);\n\n  padding: var(--espacio-4) var(--espacio-5);\n  border-bottom: 1px solid var(--color-contorno-variante);\n}\n\n.o-tabla-datos__titulo {\n  display: flex;\n  align-items: center;\n  gap: var(--espacio-3);\n\n  font-size: var(--texto-titulo-grande);\n  font-weight: var(--peso-medio);\n}\n\n/* ---------------------------------------------------------------------\n   Contenedor con desplazamiento\n   ---------------------------------------------------------------------\n   tabindex=\"0\" en este div (lo pone el JavaScript) permite desplazar\n   la tabla con el teclado. Sin eso, quien no usa raton no puede ver\n   las columnas de la derecha.\n   --------------------------------------------------------------------- */\n.o-tabla-datos__contenedor {\n  width: 100%;\n  overflow-x: auto;\n\n  /* Desplazamiento con inercia en iOS. */\n  -webkit-overflow-scrolling: touch;\n}\n\n.o-tabla-datos {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: var(--texto-cuerpo-medio);\n}\n\n/* ---------------------------------------------------------------------\n   Encabezado de la tabla\n   --------------------------------------------------------------------- */\n.o-tabla-datos__encabezado {\n  background-color: var(--color-superficie-contenedor);\n}\n\n.o-tabla-datos__celda-encabezado {\n  padding: var(--espacio-3) var(--espacio-4);\n  text-align: left;\n  white-space: nowrap;\n\n  font-size: var(--texto-etiqueta-medio);\n  font-weight: var(--peso-semi);\n  text-transform: uppercase;\n  letter-spacing: var(--letra-amplia);\n  color: var(--color-sobre-superficie-variante);\n\n  border-bottom: 1px solid var(--color-contorno-variante);\n}\n\n/* Columna de acciones: alineada a la derecha y sin estirarse. */\n.o-tabla-datos__celda-encabezado--acciones {\n  text-align: right;\n  width: 1%;\n}\n\n/* ---------------------------------------------------------------------\n   Filas y celdas\n   --------------------------------------------------------------------- */\n.o-tabla-datos__fila {\n  border-bottom: 1px solid var(--color-contorno-variante);\n  transition: background-color var(--duracion-corta) var(--curva-estandar);\n}\n\n.o-tabla-datos__fila:last-child {\n  border-bottom: none;\n}\n\n.o-tabla-datos__fila:hover {\n  background-color: var(--color-superficie-contenedor-bajo);\n}\n\n/* Fila seleccionada (al abrir su panel de detalle). */\n.o-tabla-datos__fila--seleccionada {\n  background-color: var(--color-contenedor-primario);\n}\n\n.o-tabla-datos__celda {\n  padding: var(--espacio-3) var(--espacio-4);\n  vertical-align: middle;\n  color: var(--color-sobre-superficie);\n}\n\n/* Celda con el id: monoespaciada para que los numeros se alineen. */\n.o-tabla-datos__celda--id {\n  font-family: var(--fuente-mono);\n  font-size: var(--texto-cuerpo-pequeno);\n  color: var(--color-sobre-superficie-variante);\n  white-space: nowrap;\n}\n\n.o-tabla-datos__celda--principal {\n  font-weight: var(--peso-medio);\n}\n\n.o-tabla-datos__celda--numero {\n  text-align: right;\n  font-variant-numeric: tabular-nums;\n}\n\n.o-tabla-datos__celda--acciones {\n  text-align: right;\n  white-space: nowrap;\n}\n\n/* Grupo de botones de accion de la fila. */\n.o-tabla-datos__acciones {\n  display: inline-flex;\n  gap: var(--espacio-1);\n  justify-content: flex-end;\n}\n\n/* Texto secundario dentro de una celda (ciudad bajo el nombre). */\n.o-tabla-datos__celda-secundario {\n  display: block;\n  margin-top: 2px;\n  font-size: var(--texto-cuerpo-pequeno);\n  color: var(--color-sobre-superficie-variante);\n}\n\n/* =====================================================================\n   MOVIL: la tabla se convierte en tarjetas\n   =====================================================================\n   Esta es la parte interesante. Cambiamos el display de los elementos\n   de la tabla para que dejen de comportarse como tabla:\n\n     thead -> se oculta (los nombres de columna pasan a cada celda)\n     tr    -> se vuelve un bloque con aspecto de tarjeta\n     td    -> se vuelve una fila de \"etiqueta | valor\"\n   ===================================================================== */\n@media (max-width: 904px) {\n  /* Escondemos el encabezado, pero con la tecnica accesible: sigue\n     existiendo para el lector de pantalla. */\n  .o-tabla-datos__encabezado {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    overflow: hidden;\n    clip-path: inset(50%);\n  }\n\n  .o-tabla-datos,\n  .o-tabla-datos tbody,\n  .o-tabla-datos__fila,\n  .o-tabla-datos__celda {\n    display: block;\n    width: 100%;\n  }\n\n  /* Cada fila es ahora una tarjeta. */\n  .o-tabla-datos__fila {\n    margin-bottom: var(--espacio-3);\n    padding: var(--espacio-3);\n    border: 1px solid var(--color-contorno-variante);\n    border-radius: var(--radio-pequeno);\n    background-color: var(--color-superficie);\n  }\n\n  .o-tabla-datos__fila:last-child {\n    margin-bottom: 0;\n  }\n\n  /* Cada celda es una fila de dos columnas: etiqueta y valor. */\n  .o-tabla-datos__celda {\n    display: grid;\n    grid-template-columns: 8rem 1fr;\n    gap: var(--espacio-3);\n    align-items: baseline;\n\n    /* justify-items: start evita que los elementos se estiren a todo\n       el ancho de su columna.\n\n       Por defecto, un elemento dentro de una celda de grid se ESTIRA\n       (justify-items: stretch). Una insignia es inline-flex, pero al\n       convertirse en item de grid pierde su ancho natural y se vuelve\n       una barra de color de lado a lado. Con `start` conserva el\n       ancho de su contenido, como se ve en la vista de escritorio. */\n    justify-items: start;\n\n    padding: var(--espacio-2) 0;\n    border-bottom: 1px solid var(--color-contorno-variante);\n  }\n\n  /* AQUI ESTA EL TRUCO: attr(data-etiqueta) lee el atributo\n     data-etiqueta del <td> y lo imprime como contenido generado.\n     Por eso en el JavaScript cada celda se crea con\n     data-etiqueta=\"Nombre completo\". */\n  .o-tabla-datos__celda::before {\n    content: attr(data-etiqueta);\n\n    font-size: var(--texto-etiqueta-medio);\n    font-weight: var(--peso-semi);\n    text-transform: uppercase;\n    letter-spacing: var(--letra-amplia);\n    color: var(--color-sobre-superficie-variante);\n  }\n\n  /* La celda de acciones no necesita etiqueta ni borde. */\n  .o-tabla-datos__celda--acciones {\n    display: flex;\n    justify-content: flex-end;\n    border-bottom: none;\n    padding-top: var(--espacio-3);\n  }\n\n  .o-tabla-datos__celda--acciones::before {\n    content: none;\n  }\n\n  .o-tabla-datos__celda--numero {\n    text-align: left;\n  }\n}\n","persona-frontend/css/06-plantillas/_t-panel-administracion.css":"/* =====================================================================\n   06-plantillas/_t-panel-administracion.css\n   ---------------------------------------------------------------------\n   PLANTILLA: Panel de administracion\n\n   ATOMIC DESIGN - NIVEL 4: PLANTILLAS\n   Una plantilla define la ESTRUCTURA de la pagina: donde va cada\n   organismo. No define el contenido ni los colores de los\n   componentes, solo la distribucion en el espacio.\n\n   Dicho de otra forma: la plantilla es el esqueleto; los organismos\n   son los organos. La plantilla no sabe si la tabla muestra usuarios\n   o redes sociales, solo sabe que \"aqui va el contenido principal\".\n\n   ESTRUCTURA (CSS Grid con areas nombradas):\n\n     MOVIL (< 905px)              ESCRITORIO (>= 905px)\n     +--------------------+       +---------+--------------+\n     |    barra           |       | barra   |    barra     |\n     +--------------------+       +---------+--------------+\n     |                    |       | nav     |              |\n     |    contenido       |       | lateral |  contenido   |\n     |                    |       |         |              |\n     +--------------------+       +---------+--------------+\n\n   El panel lateral es fixed en movil (flota sobre el contenido), asi\n   que en la cuadricula de movil no ocupa ninguna celda.\n   ===================================================================== */\n\n.t-panel-administracion {\n  display: grid;\n\n  /* ------------------------------------------------------------------\n     POR QUE minmax(0, 1fr) Y NO SOLO 1fr?\n     ------------------------------------------------------------------\n     Esta es LA trampa mas famosa de CSS Grid, y produce un desborde\n     horizontal muy difícil de diagnosticar.\n\n     `1fr` equivale en realidad a `minmax(auto, 1fr)`, y ese `auto`\n     significa \"nunca mas angosto que el min-content de su contenido\".\n\n     El titulo de la barra superior lleva white-space: nowrap, asi que\n     su min-content es el ancho del texto COMPLETO. En una pantalla de\n     390px, la columna se negaba a bajar de 408px y la pagina entera\n     se desplazaba en horizontal.\n\n     minmax(0, 1fr) pone el minimo en 0 y autoriza a la columna a\n     encogerse. El recorte con puntos suspensivos del titulo\n     (text-overflow: ellipsis) hace el resto.\n\n     Regla practica: en una cuadricula cuyo contenido puede ser ancho\n     (tablas, textos sin cortes), usa SIEMPRE minmax(0, 1fr).\n     ------------------------------------------------------------------ */\n  grid-template-columns: minmax(0, 1fr);\n\n  /* ------------------------------------------------------------------\n     TODAS las areas que usan los hijos tienen que estar declaradas\n     aqui, incluida \"navegacion\".\n\n     Si un hijo pide `grid-area: navegacion` y ese nombre NO existe en\n     la cuadricula, CSS Grid le crea COLUMNAS IMPLICITAS para\n     acomodarlo. Eso deformaba el layout en movil.\n\n     En movil la fila \"navegacion\" mide 0 porque el panel que contiene\n     es position: fixed (esta fuera del flujo), asi que no estorba.\n     ------------------------------------------------------------------ */\n  grid-template-rows: auto auto 1fr;\n\n  /* Las areas nombradas hacen el layout LEGIBLE: se ve el dibujo de\n     la pagina en el codigo. Es mucho mas claro que decir\n     grid-column: 2 / 3; grid-row: 1 / 2. */\n  grid-template-areas:\n    \"barra\"\n    \"navegacion\"\n    \"contenido\";\n\n  /* 100dvh asegura que la pagina ocupe el alto real de la ventana,\n     descontando la barra del navegador movil. */\n  min-height: 100dvh;\n\n  /* Red de seguridad: si algun dia un componente nuevo se pasa de\n     ancho, se recorta en lugar de romper toda la pagina. */\n  overflow-x: clip;\n}\n\n.t-panel-administracion__barra {\n  grid-area: barra;\n}\n\n.t-panel-administracion__navegacion {\n  grid-area: navegacion;\n}\n\n.t-panel-administracion__contenido {\n  grid-area: contenido;\n\n  /* min-width: 0 en una celda de grid es imprescindible cuando el\n     contenido puede ser ancho (una tabla). Sin esto, la tabla estira\n     la columna y rompe el layout en lugar de desplazarse. */\n  min-width: 0;\n\n  padding: var(--espacio-4);\n  overflow-x: hidden;\n}\n\n/* ---------------------------------------------------------------------\n   ESCRITORIO: aparece la columna del panel lateral\n   --------------------------------------------------------------------- */\n@media (min-width: 905px) {\n  .t-panel-administracion {\n    /* Primera columna del ancho del panel, segunda con el resto.\n       De nuevo minmax(0, 1fr) en la columna del contenido: ahi va la\n       tabla, que es el elemento mas ancho de la aplicacion. */\n    grid-template-columns: var(--ancho-navegacion-lateral) minmax(0, 1fr);\n    grid-template-rows: auto 1fr;\n\n    grid-template-areas:\n      \"barra      barra\"\n      \"navegacion contenido\";\n  }\n\n  .t-panel-administracion__contenido {\n    padding: var(--espacio-6);\n\n    /* Si el contenido es mas alto que la ventana, se desplaza SOLO\n       esta celda y la barra lateral queda fija. */\n    overflow-y: auto;\n  }\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: cabecera de la pagina (titulo + accion principal)\n   --------------------------------------------------------------------- */\n.t-panel-administracion__cabecera {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: var(--espacio-4);\n\n  margin-bottom: var(--espacio-5);\n}\n\n.t-panel-administracion__titulo {\n  font-size: var(--texto-titular-medio);\n  font-weight: var(--peso-medio);\n  color: var(--color-sobre-fondo);\n  line-height: var(--linea-ajustada);\n}\n\n.t-panel-administracion__descripcion {\n  margin-top: var(--espacio-2);\n  max-width: var(--ancho-maximo-texto);\n\n  font-size: var(--texto-cuerpo-medio);\n  color: var(--color-sobre-superficie-variante);\n  line-height: var(--linea-normal);\n}\n\n/* ---------------------------------------------------------------------\n   ELEMENTO: pila vertical de secciones\n   ---------------------------------------------------------------------\n   El patron \"owl selector\" (* + *) aplica el margen solo a los\n   elementos que TIENEN un hermano antes. Asi el primer elemento no\n   recibe margen superior y no hay que corregirlo con :first-child.\n   --------------------------------------------------------------------- */\n.t-panel-administracion__pila > * + * {\n  margin-top: var(--espacio-5);\n}\n","persona-frontend/css/main.css":"/* =====================================================================\n   main.css\n   ---------------------------------------------------------------------\n   PUNTO DE ENTRADA DE TODOS LOS ESTILOS.\n\n   Es el unico archivo CSS que enlaza el index.html. Importa el resto\n   en un ORDEN ESTRICTO, que es la clave de todo el sistema.\n\n   POR QUE IMPORTA EL ORDEN?\n   Por la CASCADA de CSS: cuando dos reglas tienen la misma\n   especificidad, GANA LA ULTIMA que se declaro. Si los atomos se\n   cargaran despues de los organismos, un organismo no podria\n   organizar nada.\n\n   El orden va de lo mas GENERICO a lo mas ESPECIFICO:\n\n     1. 01-tokens      variables (no generan ni una regla visible)\n     2. 02-base        reset y estilos de elementos HTML\n     3. 03-atomos      componentes indivisibles\n     4. 04-moleculas   grupos de atomos\n     5. 05-organismos  secciones completas\n     6. 06-plantillas  estructura de la pagina\n     7. 07-paginas     ajustes puntuales de cada vista\n\n   Esta estructura es una adaptacion del Atomic Design de Brad Frost\n   sobre la arquitectura ITCSS (Inverted Triangle CSS) de Harry\n   Roberts: el \"triangulo invertido\" describe justamente eso, que el\n   alcance de las reglas se va estrechando a medida que se baja.\n\n   NOTA DE RENDIMIENTO\n   ---------------------------------------------------------------------\n   @import dispara una peticion HTTP por archivo (aqui, 23). En\n   desarrollo es perfecto: cada componente en su archivo, facil de\n   encontrar y de explicar.\n\n   Para produccion se usaria una herramienta (PostCSS, Vite, o incluso\n   el comando `cat`) que concatene los 23 archivos en uno solo\n   minificado. Mantenemos @import a proposito: el objetivo de este\n   proyecto es que se VEA la arquitectura, no exprimir milisegundos.\n   ===================================================================== */\n\n/* ---------- 1. TOKENS: el sistema de diseno ---------- */\n@import url(\"01-tokens/_colores.css\");\n@import url(\"01-tokens/_tipografia.css\");\n@import url(\"01-tokens/_espaciado.css\");\n@import url(\"01-tokens/_elevacion.css\");\n\n/* ---------- 2. BASE: reset y elementos HTML ---------- */\n@import url(\"02-base/_reset.css\");\n@import url(\"02-base/_base.css\");\n\n/* ---------- 3. ATOMOS ---------- */\n@import url(\"03-atomos/_a-boton.css\");\n@import url(\"03-atomos/_a-campo-texto.css\");\n@import url(\"03-atomos/_a-etiqueta.css\");\n@import url(\"03-atomos/_a-icono.css\");\n@import url(\"03-atomos/_a-insignia.css\");\n@import url(\"03-atomos/_a-cargador.css\");\n\n/* ---------- 4. MOLECULAS ---------- */\n@import url(\"04-moleculas/_m-campo-formulario.css\");\n@import url(\"04-moleculas/_m-tarjeta.css\");\n@import url(\"04-moleculas/_m-notificacion.css\");\n@import url(\"04-moleculas/_m-barra-busqueda.css\");\n@import url(\"04-moleculas/_m-paginador.css\");\n@import url(\"04-moleculas/_m-estado-vacio.css\");\n\n/* ---------- 5. ORGANISMOS ---------- */\n@import url(\"05-organismos/_o-barra-superior.css\");\n@import url(\"05-organismos/_o-navegacion-lateral.css\");\n@import url(\"05-organismos/_o-tabla-datos.css\");\n@import url(\"05-organismos/_o-modal.css\");\n@import url(\"05-organismos/_o-formulario.css\");\n@import url(\"05-organismos/_o-panel-detalle.css\");\n\n/* ---------- 6. PLANTILLAS ---------- */\n@import url(\"06-plantillas/_t-panel-administracion.css\");\n\n/* ---------- 7. PAGINAS ---------- */\n@import url(\"07-paginas/_p-recursos.css\");\n","persona-frontend/index.html":"<!doctype html>\n<!--\n  index.html\n  =====================================================================\n  UNICA pagina HTML de la aplicacion.\n\n  Es una SPA (Single Page Application, aplicacion de una sola pagina):\n  todo el contenido lo construye JavaScript dentro de #aplicacion y la\n  navegacion cambia el fragmento de la URL (#usuarios, #telefonos)\n  sin recargar nada.\n\n  POR QUE EL HTML ES TAN CORTO?\n  Porque los componentes del Atomic Design generan el DOM en\n  JavaScript. Este archivo solo aporta:\n    - los metadatos de la pagina (<head>),\n    - el contenedor raiz,\n    - el mensaje para quien tenga JavaScript desactivado.\n\n  ============== IMPORTANTE: NO ABRIR CON DOBLE CLIC ==============\n  Este archivo usa modulos ES (<script type=\"module\">), que el\n  navegador BLOQUEA con el protocolo file:// por la politica de mismo\n  origen. Hay que servirlo por HTTP:\n\n      cd persona-frontend\n      npx serve -l 5500\n\n  y abrir http://localhost:5500\n  =================================================================\n-->\n<html lang=\"es\">\n  <head>\n    <!--\n      charset tiene que ser una de las primeras cosas del <head>: si\n      se declara despues, el navegador ya empezo a interpretar los\n      bytes con otra codificacion y las tildes y enies salen mal.\n    -->\n    <meta charset=\"utf-8\" />\n\n    <!--\n      La etiqueta viewport es OBLIGATORIA para el diseno responsivo.\n      Sin ella, el movil finge una pantalla de 980px y \"aleja\" la\n      pagina: las media queries de movil nunca se activan.\n\n        width=device-width -> usa el ancho real del dispositivo\n        initial-scale=1    -> sin zoom inicial\n\n      Nunca se pone maximum-scale=1 ni user-scalable=no: eso impide\n      al usuario ampliar la pagina, y para alguien con baja vision es\n      una barrera de accesibilidad grave.\n    -->\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n\n    <meta\n      name=\"description\"\n      content=\"Aplicacion formativa de gestion de usuarios, telefonos, redes sociales y perfiles sociales. Consume una API REST hecha con Node.js, Express y MySQL.\"\n    />\n\n    <!--\n      color-scheme le avisa al navegador que la pagina soporta los dos\n      temas. Con eso, los controles nativos (barras de desplazamiento,\n      calendarios, desplegables) se pintan oscuros en tema oscuro.\n      Sin esta linea queda un calendario blanco sobre fondo negro.\n    -->\n    <meta name=\"color-scheme\" content=\"light dark\" />\n\n    <title>Usuarios · Personal Management</title>\n\n    <!--\n      Favicon en linea (data URI con un SVG). No genera ninguna\n      peticion de red y evita el 404 de /favicon.ico que ensucia la\n      consola del navegador.\n    -->\n    <link\n      rel=\"icon\"\n      href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Ctext y='20' font-size='20'%3E%F0%9F%91%A4%3C/text%3E%3C/svg%3E\"\n    />\n\n    <!--\n      Una sola hoja de estilos. main.css importa los 26 archivos del\n      sistema de diseno en el orden correcto del Atomic Design:\n      tokens, base, atomos, moleculas, organismos, plantillas, paginas.\n    -->\n    <link rel=\"stylesheet\" href=\"css/main.css\" />\n  </head>\n\n  <body>\n    <!--\n      Contenedor raiz. JavaScript monta aqui toda la aplicacion.\n      Arranca con un mensaje de carga por si los modulos tardan.\n    -->\n    <div id=\"aplicacion\">\n      <div class=\"a-cargador-bloque\" role=\"status\" aria-live=\"polite\">\n        <span class=\"a-cargador a-cargador--grande\" aria-hidden=\"true\"></span>\n        <p>Cargando la aplicacion...</p>\n      </div>\n    </div>\n\n    <!--\n      <noscript> solo se muestra si el usuario tiene JavaScript\n      desactivado. Es una cortesia importante: sin este bloque veria\n      una pagina en blanco, sin ninguna explicacion.\n    -->\n    <noscript>\n      <div style=\"padding: 2rem; font-family: system-ui, sans-serif; max-width: 40rem; margin: 0 auto\">\n        <h1>JavaScript es necesario</h1>\n        <p>\n          Esta aplicacion construye su interfaz con JavaScript y consume una API REST,\n          asi que necesita que JavaScript este activado en el navegador.\n        </p>\n        <p>\n          Si solo quieres ver los datos, puedes consultar la API directamente en\n          <code>http://localhost:3000/api/usuarios</code>\n        </p>\n      </div>\n    </noscript>\n\n    <!--\n      type=\"module\" hace tres cosas:\n        1. Habilita import y export dentro del archivo.\n        2. Activa el modo estricto de JavaScript de forma automatica.\n        3. Aplica `defer`: el script corre cuando el HTML ya se parseo,\n           asi que el DOM siempre esta listo.\n\n      Solo cargamos UN archivo: main.js importa todo lo demas. El\n      navegador resuelve el arbol de dependencias por su cuenta.\n    -->\n    <script type=\"module\" src=\"js/main.js\"></script>\n  </body>\n</html>\n","persona-frontend/js/atomos/boton.js":"/**\n * js/atomos/boton.js\n * ---------------------------------------------------------------------\n * ATOMO: Boton\n *\n * ATOMIC DESIGN APLICADO AL JAVASCRIPT\n * La jerarquia del Atomic Design no es solo para el CSS: tambien\n * organiza los componentes de JavaScript, en las mismas carpetas y\n * con las mismas reglas.\n *\n * Un componente atomo cumple tres condiciones:\n *   1. No importa ningun otro componente (solo utilidades).\n *   2. No sabe nada de la API ni del estado de la aplicacion.\n *   3. Es una funcion PURA de presentacion: con las mismas\n *      propiedades siempre produce el mismo elemento.\n *\n * Esa pureza es lo que lo hace reutilizable y facil de probar.\n */\n\nimport { crear, crearIcono } from '../utiles/dom.js';\nimport { ICONOS } from '../utiles/iconos.js';\n\n/**\n * Crea un boton.\n *\n * @param {object} propiedades\n * @param {string} propiedades.texto     Texto visible.\n * @param {string} propiedades.variante  primario | tonal | contorno | texto | peligro\n * @param {string} propiedades.icono     Nombre de un icono de ICONOS.\n * @param {function} propiedades.onClick Manejador del clic.\n * @param {boolean} propiedades.deshabilitado\n * @param {boolean} propiedades.bloque   Ocupa todo el ancho.\n * @param {string} propiedades.tipo      button | submit | reset\n * @param {string} propiedades.titulo    Texto del tooltip.\n * @returns {HTMLButtonElement}\n */\nexport function Boton({\n  texto = '',\n  variante = 'primario',\n  icono = null,\n  onClick = null,\n  deshabilitado = false,\n  bloque = false,\n  tipo = 'button',\n  titulo = null\n} = {}) {\n  // Armamos la lista de clases desde las propiedades. filter(Boolean)\n  // descarta los false, asi no quedan espacios dobles en el atributo.\n  const clases = [\n    'a-boton',\n    `a-boton--${variante}`,\n    bloque && 'a-boton--bloque'\n  ]\n    .filter(Boolean)\n    .join(' ');\n\n  const hijos = [];\n\n  // El icono va antes del texto.\n  if (icono !== null && ICONOS[icono]) {\n    hijos.push(crearIcono(ICONOS[icono], 'a-icono a-boton__icono'));\n  }\n\n  if (texto !== '') {\n    hijos.push(crear('span', { texto }));\n  }\n\n  return crear(\n    'button',\n    {\n      clase: clases,\n\n      // type=\"button\" es importante: sin el, un boton dentro de un\n      // <form> actua como submit y envia el formulario sin querer.\n      // Es un bug clasico y muy molesto de encontrar.\n      type: tipo,\n\n      disabled: deshabilitado,\n      title: titulo,\n      onClick\n    },\n    hijos\n  );\n}\n\n/**\n * Crea un boton que solo contiene un icono.\n *\n * ACCESIBILIDAD OBLIGATORIA: un boton sin texto necesita aria-label.\n * Sin el, el lector de pantalla anuncia solo \"boton\" y la persona no\n * tiene forma de saber que hace.\n *\n * Por eso aqui `etiqueta` NO tiene valor por defecto: si falta, el\n * desarrollador vera un aria-label vacio y se dara cuenta del error.\n *\n * @param {object} propiedades\n * @param {string} propiedades.icono     Nombre del icono (obligatorio).\n * @param {string} propiedades.etiqueta  Descripcion para aria-label.\n */\nexport function BotonIcono({\n  icono,\n  etiqueta,\n  variante = 'icono',\n  onClick = null,\n  deshabilitado = false,\n  pequeno = false,\n  titulo = null\n} = {}) {\n  const clases = [\n    'a-boton',\n    `a-boton--${variante}`,\n    pequeno && 'a-boton--icono-pequeno'\n  ]\n    .filter(Boolean)\n    .join(' ');\n\n  return crear(\n    'button',\n    {\n      clase: clases,\n      type: 'button',\n\n      // El lector de pantalla lee este texto.\n      ariaLabel: etiqueta,\n\n      // El usuario de raton ve este tooltip. Si no se pasa titulo,\n      // reutilizamos la etiqueta: dos usuarios, una sola fuente.\n      title: titulo ?? etiqueta,\n\n      disabled: deshabilitado,\n      onClick\n    },\n    crearIcono(ICONOS[icono] ?? ICONOS.informacion, 'a-icono a-boton__icono')\n  );\n}\n","persona-frontend/js/main.js":"/**\n * js/main.js\n * ---------------------------------------------------------------------\n * PUNTO DE ENTRADA del frontend.\n *\n * Es el equivalente de index.js en el backend: no contiene logica de\n * negocio, solo ORQUESTA el arranque de la aplicacion.\n *\n *   1. Crea la plantilla (la estructura de la pagina).\n *   2. Registra las paginas disponibles.\n *   3. Verifica que la API responda.\n *   4. Muestra la primera seccion.\n *   5. Atiende la navegacion.\n *\n * ENRUTAMIENTO CON EL HASH DE LA URL\n * ---------------------------------------------------------------------\n * Usamos el fragmento de la URL (lo que va despues de #) para saber\n * que seccion mostrar:\n *\n *   index.html#usuarios\n *   index.html#telefonos\n *\n * Por que el hash y no rutas normales como /usuarios?\n * Porque cambiar el hash NO recarga la pagina y no necesita ninguna\n * configuracion del servidor. Con rutas reales, al recargar\n * /usuarios el servidor estatico buscaria un archivo llamado\n * \"usuarios\" y devolveria 404. El hash es la forma mas simple de\n * tener enlaces compartibles y que el boton Atras funcione, sin\n * backend de por medio.\n */\n\nimport { buscar } from './utiles/dom.js';\nimport { PanelAdministracion } from './plantillas/panelAdministracion.js';\nimport { notificador } from './moleculas/notificacion.js';\nimport { clienteApi } from './servicios/clienteApi.js';\n\nimport { PaginaUsuarios } from './paginas/paginaUsuarios.js';\nimport { PaginaTelefonos } from './paginas/paginaTelefonos.js';\nimport { PaginaRedesSociales } from './paginas/paginaRedesSociales.js';\nimport { PaginaPerfilesSociales } from './paginas/paginaPerfilesSociales.js';\n\nimport { CONFIGURACION } from './config/configuracion.js';\n\n// ---------------------------------------------------------------------\n// Definicion del menu de navegacion\n// ---------------------------------------------------------------------\nconst SECCIONES = [\n  {\n    grupo: 'Gestion',\n    elementos: [\n      { id: 'usuarios', etiqueta: 'Usuarios', icono: 'usuarios' },\n      { id: 'telefonos', etiqueta: 'Telefonos', icono: 'telefono' }\n    ]\n  },\n  {\n    grupo: 'Catalogos y relaciones',\n    elementos: [\n      { id: 'redes-sociales', etiqueta: 'Redes sociales', icono: 'redSocial' },\n      { id: 'perfiles-sociales', etiqueta: 'Perfiles sociales', icono: 'perfilSocial' }\n    ]\n  }\n];\n\n/** Seccion que se muestra si el hash esta vacio o no se reconoce. */\nconst SECCION_POR_DEFECTO = 'usuarios';\n\n/**\n * Arranca la aplicacion.\n */\nfunction iniciar() {\n  const raiz = buscar('#aplicacion');\n\n  if (raiz === null) {\n    // Si falta el contenedor, el HTML esta mal: avisamos en consola\n    // porque todavia no hay interfaz donde mostrar el error.\n    console.error('[main.js] No se encontro el elemento #aplicacion en el HTML.');\n    return;\n  }\n\n  // ---- 1. Plantilla ----\n  const panel = PanelAdministracion({\n    secciones: SECCIONES,\n    seccionActiva: SECCION_POR_DEFECTO,\n\n    // Al pulsar un enlace del menu solo cambiamos el hash. El oyente\n    // de 'hashchange' se encarga del resto.\n    //\n    // Por que asi y no navegando directo? Porque de este modo hay UN\n    // solo camino para cambiar de seccion: el hash. Da igual si el\n    // usuario pulso el menu, escribio la URL o uso el boton Atras del\n    // navegador: el comportamiento es siempre el mismo.\n    onNavegar: (idSeccion) => {\n      window.location.hash = idSeccion;\n    }\n  });\n\n  panel.montarEn(raiz);\n\n  /** Envia el contenido de una pagina a la zona principal. */\n  const mostrarContenido = (...nodos) => panel.establecerContenido(...nodos);\n\n  // ---- 2. Paginas ----\n  // Cada pagina recibe la funcion para pintar y la funcion para\n  // actualizar su contador en el menu. No conocen la plantilla ni\n  // entre si: solo reciben dos funciones.\n  const paginas = {\n    usuarios: PaginaUsuarios({\n      onContenido: mostrarContenido,\n      onTotalCambiado: (total) => panel.navegacion.actualizarContador('usuarios', total)\n    }),\n    telefonos: PaginaTelefonos({\n      onContenido: mostrarContenido,\n      onTotalCambiado: (total) => panel.navegacion.actualizarContador('telefonos', total)\n    }),\n    'redes-sociales': PaginaRedesSociales({\n      onContenido: mostrarContenido,\n      onTotalCambiado: (total) =>\n        panel.navegacion.actualizarContador('redes-sociales', total)\n    }),\n    'perfiles-sociales': PaginaPerfilesSociales({\n      onContenido: mostrarContenido,\n      onTotalCambiado: (total) =>\n        panel.navegacion.actualizarContador('perfiles-sociales', total)\n    })\n  };\n\n  /**\n   * Lee el hash de la URL y devuelve el id de la seccion.\n   * slice(1) quita el caracter '#'.\n   */\n  function seccionDesdeHash() {\n    const hash = window.location.hash.slice(1);\n\n    // Si el hash no corresponde a ninguna pagina conocida, caemos en\n    // la seccion por defecto. Asi un enlace viejo o mal escrito no\n    // deja la pantalla en blanco.\n    return Object.hasOwn(paginas, hash) ? hash : SECCION_POR_DEFECTO;\n  }\n\n  /** Muestra la seccion indicada por el hash. */\n  async function navegar() {\n    const idSeccion = seccionDesdeHash();\n\n    panel.navegacion.marcarActiva(idSeccion);\n\n    // Actualizamos el titulo de la pestania del navegador. Es un\n    // detalle pequeno que ayuda cuando el usuario tiene varias\n    // pestanias abiertas.\n    const etiqueta = SECCIONES.flatMap((seccion) => seccion.elementos).find(\n      (elemento) => elemento.id === idSeccion\n    )?.etiqueta;\n\n    document.title = `${etiqueta ?? 'Inicio'} · Personal Management`;\n\n    await paginas[idSeccion].cargar();\n  }\n\n  // ---- 3. Oyente de navegacion ----\n  // El evento 'hashchange' se dispara al cambiar el hash, venga del\n  // menu, de la barra de direcciones o del boton Atras.\n  window.addEventListener('hashchange', navegar);\n\n  // ---- 4. Verificacion de la API ----\n  // Lo hacemos en paralelo a la primera carga: no bloqueamos la\n  // interfaz esperando el resultado del chequeo de salud.\n  verificarApi(panel);\n\n  // ---- 5. Primera carga ----\n  navegar();\n}\n\n/**\n * Comprueba si la API responde y actualiza el indicador de la barra.\n *\n * Esta funcion es muy util para el aprendiz: si el punto esta rojo,\n * el problema es el backend y no vale la pena depurar el frontend.\n */\nasync function verificarApi(panel) {\n  const disponible = await clienteApi.verificarSalud();\n\n  panel.barraSuperior.actualizarEstadoApi(disponible);\n\n  if (!disponible) {\n    notificador.mostrar({\n      titulo: 'La API no responde',\n      mensaje:\n        `No se pudo contactar con ${CONFIGURACION.urlApi}. ` +\n        'Verifica que MySQL este encendido y que hayas ejecutado \"npm start\" ' +\n        'en la carpeta persona-api.',\n      variante: 'error',\n\n      // duracion 0: este aviso no se cierra solo. El usuario tiene\n      // que verlo y actuar.\n      duracion: 0\n    });\n  }\n\n  // Revisamos cada 30 segundos, para detectar si la API se cae\n  // mientras el usuario trabaja.\n  setTimeout(() => verificarApi(panel), 30_000);\n}\n\n/**\n * ARRANQUE\n * ---------------------------------------------------------------------\n * Con <script type=\"module\">, el navegador aplica `defer` de forma\n * automatica: el modulo se ejecuta cuando el HTML ya esta parseado.\n *\n * Aun asi comprobamos document.readyState, porque es un habito que\n * evita el error mas comun del JavaScript de navegador: intentar\n * manipular un elemento que todavia no existe en el DOM.\n */\nif (document.readyState === 'loading') {\n  document.addEventListener('DOMContentLoaded', iniciar);\n} else {\n  iniciar();\n}\n","persona-frontend/js/moleculas/campoFormulario.js":"/**\n * js/moleculas/campoFormulario.js\n * ---------------------------------------------------------------------\n * MOLECULA: Campo de formulario completo\n *\n * Combina tres atomos para formar una unidad funcional:\n *   etiqueta + control + mensaje de error (y texto de ayuda opcional)\n *\n * DEVUELVE UN OBJETO, NO SOLO UN ELEMENTO\n * ---------------------------------------------------------------------\n * Las moleculas con estado devuelven un objeto con el elemento y los\n * metodos para manipularlo:\n *\n *   const campo = CampoFormulario({ ... });\n *   formulario.appendChild(campo.elemento);\n *   campo.mostrarError('El nombre es obligatorio');\n *   const valor = campo.obtenerValor();\n *\n * Por que? Porque si solo devolvieramos el <div>, quien lo use tendria\n * que buscar el input por dentro con querySelector y conocer su\n * estructura interna. Eso rompe el encapsulamiento: el dia que\n * cambiemos el HTML de la molecula, se romperian todos sus usos.\n *\n * Con el objeto, la estructura interna queda escondida detras de una\n * interfaz estable. Es el MISMO principio de los getters y setters de\n * las clases del backend, aplicado a un componente de interfaz.\n */\n\nimport { crear, crearIcono } from '../utiles/dom.js';\nimport { ICONOS } from '../utiles/iconos.js';\nimport { EntradaTexto, AreaTexto, Seleccion } from '../atomos/campos.js';\n\n/**\n * @param {object} propiedades\n * @param {string} propiedades.id          id unico del control.\n * @param {string} propiedades.nombre      Atributo name.\n * @param {string} propiedades.etiqueta    Texto visible de la etiqueta.\n * @param {string} propiedades.control     texto | area | seleccion\n * @param {string} propiedades.ayuda       Texto de ayuda permanente.\n * @param {boolean} propiedades.anchoCompleto  Ocupa las dos columnas.\n * @returns {{elemento: HTMLElement, obtenerValor: function, establecerValor: function,\n *            mostrarError: function, limpiarError: function, enfocar: function,\n *            control: HTMLElement}}\n */\nexport function CampoFormulario({\n  id,\n  nombre,\n  etiqueta,\n  control = 'texto',\n  tipo = 'text',\n  valor = '',\n  sugerencia = '',\n  requerido = false,\n  maximo = null,\n  maximoValor = null,\n  opciones = [],\n  textoVacio = null,\n  ayuda = null,\n  anchoCompleto = false,\n  deshabilitado = false,\n  autocompletar = null,\n  onInput = null,\n  onChange = null\n} = {}) {\n  // id derivados, para conectar el control con sus textos por ARIA.\n  const idAyuda = ayuda ? `${id}-ayuda` : null;\n  const idError = `${id}-error`;\n\n  // ---- Atomo 1: la etiqueta ----\n  const elementoEtiqueta = crear('label', {\n    clase: `a-etiqueta${requerido ? ' a-etiqueta--obligatoria' : ''}`,\n\n    // htmlFor genera el atributo `for`. Se llama asi porque `for` es\n    // una palabra reservada de JavaScript y no se puede usar como\n    // nombre de propiedad.\n    htmlFor: id,\n\n    texto: etiqueta\n  });\n\n  // ---- Atomo 2: el control ----\n  let elementoControl;\n\n  const propiedadesComunes = {\n    id,\n    nombre,\n    valor,\n    sugerencia,\n    requerido,\n    maximo,\n    deshabilitado,\n    idAyuda\n  };\n\n  if (control === 'area') {\n    elementoControl = AreaTexto({ ...propiedadesComunes, onInput });\n  } else if (control === 'seleccion') {\n    elementoControl = Seleccion({\n      ...propiedadesComunes,\n      opciones,\n      textoVacio,\n      onChange\n    });\n  } else {\n    elementoControl = EntradaTexto({\n      ...propiedadesComunes,\n      tipo,\n      maximoValor,\n      autocompletar,\n      onInput\n    });\n  }\n\n  // ---- Parte propia: texto de ayuda ----\n  const elementoAyuda = ayuda\n    ? crear('p', {\n        clase: 'm-campo-formulario__ayuda',\n        id: idAyuda,\n        texto: ayuda\n      })\n    : null;\n\n  // ---- Parte propia: mensaje de error ----\n  const textoError = crear('span', {});\n\n  const elementoError = crear(\n    'p',\n    {\n      clase: 'm-campo-formulario__error',\n      id: idError,\n\n      // role=\"alert\" hace que el lector de pantalla lo anuncie en\n      // cuanto se vuelve visible, sin esperar a que el usuario\n      // navegue hasta el.\n      role: 'alert'\n    },\n    crearIcono(ICONOS.error, 'a-icono m-campo-formulario__error-icono'),\n    textoError\n  );\n\n  // ---- Ensamblado de la molecula ----\n  const elemento = crear(\n    'div',\n    {\n      clase: `m-campo-formulario${anchoCompleto ? ' m-campo-formulario--ancho-completo' : ''}`\n    },\n    elementoEtiqueta,\n    elementoControl,\n    elementoAyuda,\n    elementoError\n  );\n\n  // =====================================================================\n  // INTERFAZ PUBLICA de la molecula\n  // =====================================================================\n  return {\n    /** El nodo del DOM, para insertarlo en el formulario. */\n    elemento,\n\n    /** El control interno. Se expone para casos puntuales (enfocar,\n     *  escuchar un evento propio), pero se prefieren los metodos. */\n    control: elementoControl,\n\n    /** Valor actual, ya con los espacios recortados. */\n    obtenerValor() {\n      return elementoControl.value.trim();\n    },\n\n    /** Asigna un valor al control. */\n    establecerValor(nuevoValor) {\n      elementoControl.value = nuevoValor ?? '';\n    },\n\n    /**\n     * Muestra un mensaje de error.\n     *\n     * Hace TRES cosas, y las tres importan:\n     *   1. Escribe el texto del mensaje.\n     *   2. Muestra el bloque de error (modificador --visible).\n     *   3. Marca el control con aria-invalid=\"true\", que a la vez\n     *      informa al lector de pantalla y activa el borde rojo del CSS.\n     */\n    mostrarError(mensaje) {\n      textoError.textContent = mensaje;\n      elementoError.classList.add('m-campo-formulario__error--visible');\n      elementoControl.setAttribute('aria-invalid', 'true');\n\n      // Al marcar el error, conectamos el control con el mensaje para\n      // que el lector de pantalla lo lea como parte del campo.\n      const descripciones = [idAyuda, idError].filter(Boolean).join(' ');\n      elementoControl.setAttribute('aria-describedby', descripciones);\n    },\n\n    /** Quita el estado de error. */\n    limpiarError() {\n      textoError.textContent = '';\n      elementoError.classList.remove('m-campo-formulario__error--visible');\n\n      // removeAttribute, no setAttribute('aria-invalid', 'false'):\n      // ausente es mas limpio y evita confundir al lector de pantalla.\n      elementoControl.removeAttribute('aria-invalid');\n\n      if (idAyuda) {\n        elementoControl.setAttribute('aria-describedby', idAyuda);\n      } else {\n        elementoControl.removeAttribute('aria-describedby');\n      }\n    },\n\n    /** Pone el foco en el control. Se usa para llevar al usuario al\n     *  primer campo con error. */\n    enfocar() {\n      elementoControl.focus();\n    },\n\n    /** Nombre del campo, para emparejarlo con los errores del servidor. */\n    nombre\n  };\n}\n","persona-frontend/js/organismos/modal.js":"/**\n * js/organismos/modal.js\n * ---------------------------------------------------------------------\n * ORGANISMO: Ventana modal\n *\n * USAMOS EL ELEMENTO NATIVO <dialog> DE HTML5\n * ---------------------------------------------------------------------\n * Esta es una de las decisiones mas importantes del frontend. El\n * metodo showModal() nos regala, gratis y bien hecho:\n *\n *   1. ATRAPAR EL FOCO (focus trap): con el modal abierto, la\n *      tabulacion no puede salir de el. Implementarlo a mano exige\n *      detectar todos los elementos enfocables, ordenarlos y\n *      reciclar el foco en los extremos. Son ~80 lineas delicadas.\n *\n *   2. LA TECLA ESCAPE cierra el dialogo sin escribir ni una linea.\n *\n *   3. EL RESTO DE LA PAGINA QUEDA INERTE: no se puede hacer clic ni\n *      tabular hacia el contenido de atras.\n *\n *   4. EL VELO lo dibuja el pseudo-elemento ::backdrop.\n *\n *   5. EL FOCO VUELVE SOLO al boton que abrio el modal al cerrarse.\n *\n * Hacer todo eso con <div> es la causa numero uno de modales\n * inaccesibles en la web. Si el navegador ya lo resuelve, se usa.\n */\n\nimport { crear, crearIcono } from '../utiles/dom.js';\nimport { ICONOS } from '../utiles/iconos.js';\nimport { Boton, BotonIcono } from '../atomos/boton.js';\n\n/**\n * Crea una ventana modal.\n *\n * @param {object} propiedades\n * @param {string} propiedades.titulo\n * @param {string} propiedades.descripcion\n * @param {HTMLElement} propiedades.cuerpo    Contenido (un formulario).\n * @param {Array} propiedades.acciones        [{ texto, variante, onClick, icono }]\n * @param {function} propiedades.onCerrar     Se llama al cerrar.\n * @returns {{elemento, abrir, cerrar, establecerCargando}}\n */\nexport function Modal({\n  titulo = '',\n  descripcion = null,\n  cuerpo = null,\n  acciones = [],\n  onCerrar = null,\n  variante = null\n} = {}) {\n  // Id unico para conectar el dialogo con su titulo por ARIA.\n  const idTitulo = `modal-titulo-${Math.random().toString(36).slice(2, 9)}`;\n\n  const botonCerrar = BotonIcono({\n    icono: 'cerrar',\n    etiqueta: 'Cerrar',\n    onClick: () => cerrar()\n  });\n\n  // Guardamos los botones para poder deshabilitarlos mientras se\n  // envia el formulario (evita el doble envio por doble clic).\n  const botonesAccion = acciones.map((accion) =>\n    Boton({\n      texto: accion.texto,\n      variante: accion.variante ?? 'texto',\n      icono: accion.icono ?? null,\n      onClick: accion.onClick,\n      tipo: accion.tipo ?? 'button'\n    })\n  );\n\n  const cabecera =\n    variante === 'confirmacion'\n      ? crear(\n          'div',\n          { clase: 'o-modal__cabecera' },\n          crear(\n            'div',\n            { clase: 'o-modal__icono-alerta' },\n            crearIcono(ICONOS.advertencia, 'a-icono a-icono--grande')\n          ),\n          crear(\n            'div',\n            {},\n            crear('h2', { clase: 'o-modal__titulo', id: idTitulo, texto: titulo }),\n            descripcion\n              ? crear('p', { clase: 'o-modal__descripcion', texto: descripcion })\n              : null\n          )\n        )\n      : crear(\n          'div',\n          { clase: 'o-modal__cabecera' },\n          crear(\n            'div',\n            {},\n            crear('h2', { clase: 'o-modal__titulo', id: idTitulo, texto: titulo }),\n            descripcion\n              ? crear('p', { clase: 'o-modal__descripcion', texto: descripcion })\n              : null\n          ),\n          botonCerrar\n        );\n\n  const elemento = crear(\n    'dialog',\n    {\n      clase: `o-modal${variante ? ` o-modal--${variante}` : ''}`,\n\n      // aria-labelledby conecta el dialogo con su titulo. El lector de\n      // pantalla anuncia \"Crear usuario, dialogo\" al abrirlo.\n      ariaLabelledby: idTitulo,\n\n      /**\n       * El evento 'close' del <dialog> se dispara tanto si cerramos\n       * con close() como si el usuario pulsa Escape. Enganchar aqui\n       * la limpieza garantiza que se ejecute en los dos casos.\n       */\n      onClose: () => {\n        if (onCerrar !== null) {\n          onCerrar();\n        }\n        // Quitamos el dialogo del DOM. Si no lo hicieramos, cada\n        // apertura dejaria un <dialog> huerfano acumulandose.\n        elemento.remove();\n      },\n\n      /**\n       * Cerrar al hacer clic fuera del contenido.\n       *\n       * Truco: el <dialog> ocupa toda la pantalla, pero su contenido\n       * visible es solo la caja central. Si el clic fue exactamente\n       * sobre el <dialog> (y no sobre un hijo), significa que cayo en\n       * el velo, asi que cerramos.\n       */\n      onClick: (evento) => {\n        if (evento.target === elemento) {\n          cerrar();\n        }\n      }\n    },\n    crear(\n      'div',\n      { clase: 'o-modal__contenido' },\n      cabecera,\n      cuerpo ? crear('div', { clase: 'o-modal__cuerpo' }, cuerpo) : null,\n      botonesAccion.length > 0\n        ? crear('div', { clase: 'o-modal__pie' }, botonesAccion)\n        : null\n    )\n  );\n\n  /** Abre el modal. */\n  function abrir() {\n    // El <dialog> tiene que estar en el DOM antes de llamar a\n    // showModal(), o el navegador lanza un error.\n    if (!elemento.isConnected) {\n      document.body.appendChild(elemento);\n    }\n\n    // showModal() (no show()) es el que atrapa el foco y dibuja el\n    // velo. show() abre el dialogo \"no modal\", sin esas ventajas.\n    elemento.showModal();\n  }\n\n  /** Cierra el modal. Dispara el evento 'close'. */\n  function cerrar() {\n    if (elemento.open) {\n      elemento.close();\n    }\n  }\n\n  return {\n    elemento,\n    abrir,\n    cerrar,\n\n    /**\n     * Pone el modal en estado \"guardando\": deshabilita los botones\n     * para que el usuario no envie el formulario dos veces.\n     *\n     * El doble envio es un bug muy comun: el usuario hace doble clic\n     * en \"Guardar\" y se crean DOS registros identicos.\n     *\n     * @param {boolean} cargando\n     */\n    establecerCargando(cargando) {\n      for (const boton of botonesAccion) {\n        boton.disabled = cargando;\n      }\n      botonCerrar.disabled = cargando;\n    }\n  };\n}\n\n/**\n * Dialogo de confirmacion para acciones destructivas.\n *\n * POR QUE CONFIRMAR ANTES DE BORRAR?\n * Porque un DELETE no se puede deshacer. El costo de un clic extra es\n * minimo frente al de perder datos por error.\n *\n * Y por que no window.confirm()? Porque bloquea el navegador entero,\n * no se puede estilizar y, sobre todo, no permite explicar las\n * CONSECUENCIAS. Aqui si podemos avisar: \"esto tambien borrara sus 2\n * telefonos y 1 perfil social\".\n *\n * @param {object} propiedades\n * @param {string} propiedades.titulo\n * @param {string} propiedades.mensaje\n * @param {string} propiedades.textoConfirmar\n * @param {function} propiedades.onConfirmar  Puede ser async.\n * @returns {{abrir: function}}\n */\nexport function ModalConfirmacion({\n  titulo = 'Confirmar la accion',\n  mensaje = 'Esta accion no se puede deshacer.',\n  textoConfirmar = 'Eliminar',\n  onConfirmar = null\n} = {}) {\n  let modal = null;\n\n  modal = Modal({\n    titulo,\n    descripcion: mensaje,\n    variante: 'confirmacion',\n    acciones: [\n      {\n        texto: 'Cancelar',\n        variante: 'texto',\n        onClick: () => modal.cerrar()\n      },\n      {\n        texto: textoConfirmar,\n        variante: 'peligro',\n        icono: 'eliminar',\n        onClick: async () => {\n          // Deshabilitamos los botones mientras corre la peticion.\n          modal.establecerCargando(true);\n\n          try {\n            if (onConfirmar !== null) {\n              await onConfirmar();\n            }\n            modal.cerrar();\n          } catch (error) {\n            // Si falla, reactivamos los botones para que el usuario\n            // pueda reintentar o cancelar. Quien llama se encarga de\n            // mostrar la notificacion del error.\n            modal.establecerCargando(false);\n            throw error;\n          }\n        }\n      }\n    ]\n  });\n\n  return modal;\n}\n","persona-frontend/js/organismos/tablaDatos.js":"/**\n * js/organismos/tablaDatos.js\n * ---------------------------------------------------------------------\n * ORGANISMO: Tabla de datos generica\n *\n * UN SOLO COMPONENTE PARA LAS CUATRO ENTIDADES\n * ---------------------------------------------------------------------\n * En lugar de escribir TablaUsuarios, TablaTelefonos, TablaRedes y\n * TablaPerfiles (cuatro archivos casi iguales), escribimos UNA tabla\n * que recibe la DESCRIPCION de sus columnas:\n *\n *   TablaDatos({\n *     columnas: [\n *       { etiqueta: 'Id',     obtener: (fila) => fila.id, clase: 'id' },\n *       { etiqueta: 'Nombre', obtener: (fila) => fila.nombreCompleto }\n *     ],\n *     filas: usuarios\n *   })\n *\n * La propiedad `obtener` es una FUNCION que extrae el valor de cada\n * fila. Puede devolver texto o un nodo del DOM (una insignia, un\n * enlace), asi que la tabla sirve para cualquier dato.\n *\n * Esto es un ejemplo practico de dos principios:\n *   - DRY (Don't Repeat Yourself): no repetir la misma estructura.\n *   - Inversion de control: el componente no decide QUE mostrar, solo\n *     COMO mostrarlo. Lo que se muestra lo decide quien lo usa.\n */\n\nimport { crear, crearIcono } from '../utiles/dom.js';\nimport { ICONOS } from '../utiles/iconos.js';\nimport { BotonIcono } from '../atomos/boton.js';\n\n/**\n * @param {object} propiedades\n * @param {string} propiedades.titulo\n * @param {Array} propiedades.columnas  [{ etiqueta, obtener, clase }]\n * @param {Array} propiedades.filas     Los datos.\n * @param {function} propiedades.acciones  (fila) => [{icono, etiqueta, onClick, variante}]\n * @param {function} propiedades.claveFila  (fila) => string unico. Para data-clave.\n * @param {HTMLElement} propiedades.encabezadoAcciones  Botones de la cabecera.\n * @param {HTMLElement} propiedades.pie   El paginador.\n * @returns {HTMLElement}\n */\nexport function TablaDatos({\n  titulo = '',\n  columnas = [],\n  filas = [],\n  acciones = null,\n  claveFila = null,\n  encabezadoAcciones = null,\n  pie = null,\n  onClicFila = null\n} = {}) {\n  // ---- Encabezado de la tabla ----\n  const celdasEncabezado = columnas.map((columna) =>\n    crear('th', {\n      clase: 'o-tabla-datos__celda-encabezado',\n\n      // scope=\"col\" le dice al lector de pantalla que este th\n      // encabeza una COLUMNA (no una fila). Es lo que le permite\n      // anunciar \"Nombre: Grace Hopper\" al navegar por las celdas.\n      scope: 'col',\n\n      texto: columna.etiqueta\n    })\n  );\n\n  if (acciones !== null) {\n    celdasEncabezado.push(\n      crear(\n        'th',\n        {\n          clase:\n            'o-tabla-datos__celda-encabezado o-tabla-datos__celda-encabezado--acciones',\n          scope: 'col'\n        },\n        // El encabezado de acciones no necesita texto visible, pero el\n        // lector de pantalla si tiene que poder anunciarlo.\n        crear('span', { clase: 'solo-lectores', texto: 'Acciones' })\n      )\n    );\n  }\n\n  // ---- Cuerpo de la tabla ----\n  const filasCuerpo = filas.map((fila) => {\n    const celdas = columnas.map((columna) => {\n      const valor = columna.obtener(fila);\n\n      return crear(\n        'td',\n        {\n          clase: `o-tabla-datos__celda${columna.clase ? ` o-tabla-datos__celda--${columna.clase}` : ''}`,\n\n          // AQUI ESTA LA CLAVE DEL DISENIO RESPONSIVO DE LA TABLA.\n          // En movil, el CSS lee este atributo con\n          // content: attr(data-etiqueta) y lo muestra como el nombre\n          // del campo. Asi la tabla se convierte en tarjetas sin\n          // duplicar el HTML.\n          dataEtiqueta: columna.etiqueta,\n\n          title: columna.titulo ? columna.titulo(fila) : null\n        },\n        // El valor puede ser texto o un nodo del DOM (una insignia,\n        // un enlace). `crear` sabe manejar los dos casos.\n        valor\n      );\n    });\n\n    if (acciones !== null) {\n      const botonesFila = acciones(fila).map((accion) =>\n        BotonIcono({\n          icono: accion.icono,\n          etiqueta: accion.etiqueta,\n          variante: accion.variante ?? 'icono',\n          pequeno: true,\n          onClick: (evento) => {\n            // stopPropagation evita que el clic en el boton dispare\n            // tambien el onClicFila de la fila entera. Sin esto, al\n            // pulsar \"Eliminar\" se abriria el detalle ademas del\n            // dialogo de confirmacion.\n            evento.stopPropagation();\n            accion.onClick(fila);\n          }\n        })\n      );\n\n      celdas.push(\n        crear(\n          'td',\n          { clase: 'o-tabla-datos__celda o-tabla-datos__celda--acciones' },\n          crear('div', { clase: 'o-tabla-datos__acciones' }, botonesFila)\n        )\n      );\n    }\n\n    return crear(\n      'tr',\n      {\n        clase: 'o-tabla-datos__fila',\n        dataClave: claveFila ? claveFila(fila) : null,\n        onClick: onClicFila ? () => onClicFila(fila) : null,\n\n        // Si la fila es clicable, el cursor tiene que avisarlo.\n        estilo: onClicFila ? { cursor: 'pointer' } : null\n      },\n      celdas\n    );\n  });\n\n  // ---- Cabecera del organismo ----\n  const cabecera = crear(\n    'div',\n    { clase: 'o-tabla-datos__cabecera' },\n    crear(\n      'h2',\n      { clase: 'o-tabla-datos__titulo' },\n      titulo,\n      crear('span', {\n        clase: 'a-insignia a-insignia--primaria',\n        texto: String(filas.length)\n      })\n    ),\n    encabezadoAcciones\n  );\n\n  // ---- Ensamblado ----\n  return crear(\n    'section',\n    { clase: 'o-tabla-datos-envoltura' },\n    cabecera,\n    crear(\n      'div',\n      {\n        clase: 'o-tabla-datos__contenedor',\n\n        // tabindex=\"0\" hace que el contenedor sea enfocable, para que\n        // se pueda desplazar la tabla con las flechas del teclado.\n        // Sin esto, quien no usa raton no puede ver las columnas de\n        // la derecha en una pantalla angosta.\n        tabIndex: 0,\n\n        role: 'region',\n        ariaLabel: `Tabla de ${titulo}`\n      },\n      crear(\n        'table',\n        { clase: 'o-tabla-datos' },\n\n        // <caption> es el titulo semantico de la tabla. Lo ocultamos\n        // visualmente (ya esta en el h2) pero el lector de pantalla\n        // lo anuncia al entrar, lo que da contexto inmediato.\n        crear('caption', { clase: 'solo-lectores', texto: titulo }),\n\n        crear(\n          'thead',\n          { clase: 'o-tabla-datos__encabezado' },\n          crear('tr', {}, celdasEncabezado)\n        ),\n        crear('tbody', {}, filasCuerpo)\n      )\n    ),\n    pie\n  );\n}\n\n/**\n * Celda con un texto principal y un texto secundario debajo.\n * Patron muy util para ahorrar columnas: \"Grace Hopper\" con\n * \"Nueva York\" en pequeno debajo.\n *\n * @param {string} principal\n * @param {string} secundario\n */\nexport function CeldaDoble(principal, secundario) {\n  return crear(\n    'div',\n    {},\n    crear('span', { texto: principal }),\n    secundario\n      ? crear('span', { clase: 'o-tabla-datos__celda-secundario', texto: secundario })\n      : null\n  );\n}\n\n/**\n * Celda con un enlace externo.\n *\n * SEGURIDAD: target=\"_blank\" SIEMPRE va con rel=\"noopener noreferrer\".\n *\n *   noopener   -> impide que la pagina abierta acceda a window.opener\n *                 y pueda redirigir la nuestra (ataque \"tabnabbing\").\n *   noreferrer -> no envia la cabecera Referer, asi el sitio destino\n *                 no sabe de donde viene el usuario.\n *\n * Es una de esas reglas que hay que aplicar siempre, sin excepcion.\n */\nexport function CeldaEnlace(url, textoVisible) {\n  if (!url) {\n    return '—';\n  }\n\n  return crear(\n    'a',\n    {\n      clase: 'p-recursos__url',\n      href: url,\n      target: '_blank',\n      rel: 'noopener noreferrer',\n\n      // El title muestra la URL completa al pasar el puntero, porque\n      // el texto visible va recortado.\n      title: url\n    },\n    textoVisible,\n    crearIcono(ICONOS.enlaceExterno, 'a-icono a-icono--pequeno')\n  );\n}\n","persona-frontend/js/paginas/paginaUsuarios.js":"/**\n * js/paginas/paginaUsuarios.js\n * ---------------------------------------------------------------------\n * PAGINA: Gestion de usuarios\n *\n * ATOMIC DESIGN - NIVEL 5: PAGINAS\n * Una pagina es una plantilla con CONTENIDO REAL. Es el unico nivel\n * que tiene permiso para:\n *   - llamar a los servicios (y por lo tanto a la API);\n *   - guardar estado (que pagina, que filtros, que usuario se edita);\n *   - orquestar los organismos entre si.\n *\n * Los niveles de abajo (atomos, moleculas, organismos) son \"tontos\" a\n * proposito: reciben datos y manejadores, y no saben de donde vienen.\n * Esa es justamente la razon por la que se pueden reutilizar.\n *\n * EL CICLO COMPLETO DE UN CRUD EN ESTA PAGINA\n * ---------------------------------------------------------------------\n *   1. cargar()          -> GET,  pinta la tabla\n *   2. abrirFormulario() -> abre el modal (crear o editar)\n *   3. guardar()         -> POST o PUT, notifica y recarga\n *   4. confirmarBorrado()-> DELETE con confirmacion previa\n *\n * LOS CUATRO ESTADOS DE LA VISTA, que siempre hay que manejar:\n *   cargando / vacio / error / con datos\n */\n\nimport { crear } from '../utiles/dom.js';\nimport { CabeceraPagina } from '../plantillas/panelAdministracion.js';\nimport { TablaDatos, CeldaDoble } from '../organismos/tablaDatos.js';\nimport { Modal, ModalConfirmacion } from '../organismos/modal.js';\nimport { Formulario } from '../organismos/formulario.js';\nimport { PanelDetalleUsuario } from '../organismos/panelDetalleUsuario.js';\nimport { BarraBusqueda } from '../moleculas/barraBusqueda.js';\nimport { Paginador } from '../moleculas/paginador.js';\nimport { EstadoVacio, EstadoError } from '../moleculas/estadoVacio.js';\nimport { notificador } from '../moleculas/notificacion.js';\nimport { Boton } from '../atomos/boton.js';\nimport { Insignia, InsigniaEstado } from '../atomos/insignia.js';\nimport { CargadorBloque } from '../atomos/cargador.js';\n\nimport { usuarioServicio } from '../servicios/usuario.servicio.js';\nimport { telefonoServicio } from '../servicios/telefono.servicio.js';\nimport { redSocialServicio } from '../servicios/redSocial.servicio.js';\nimport { perfilSocialServicio } from '../servicios/perfilSocial.servicio.js';\n\nimport { fechaCorta, numero } from '../utiles/formato.js';\nimport {\n  validarTexto,\n  validarFecha,\n  validarTelefono,\n  validarURL,\n  validarOpcion,\n  calcularEdad\n} from '../utiles/validadores.js';\nimport { CONFIGURACION } from '../config/configuracion.js';\n\n/**\n * @param {object} propiedades\n * @param {function} propiedades.onContenido  Recibe los nodos a mostrar.\n * @param {function} propiedades.onTotalCambiado  Avisa el total, para el menu.\n */\nexport function PaginaUsuarios({ onContenido, onTotalCambiado = null } = {}) {\n  // =====================================================================\n  // ESTADO DE LA PAGINA\n  // ---------------------------------------------------------------------\n  // Son variables del closure: viven mientras la pagina exista y no\n  // contaminan el ambito global. Es el equivalente de los atributos\n  // privados de una clase.\n  // =====================================================================\n  let filtros = { pagina: 1, limite: CONFIGURACION.limitePorPagina };\n  let ultimaRespuesta = { usuarios: [], meta: null };\n\n  // La barra de busqueda se crea UNA sola vez, fuera de la funcion de\n  // pintado. Si la recrearamos en cada render, el campo perderia el\n  // foco y el texto a medio escribir en cada pulsacion de tecla. Es\n  // un bug muy comun al renderizar de nuevo toda la vista.\n  const barraBusqueda = BarraBusqueda({\n    sugerencia: 'Buscar por nombre o apellido...',\n    filtros: [\n      {\n        id: 'filtro-estado',\n        nombre: 'estado',\n        etiqueta: 'Filtrar por estado',\n        opciones: [\n          { valor: '1', texto: 'Activos' },\n          { valor: '0', texto: 'Inactivos' }\n        ],\n        textoVacio: 'Todo estado'\n      }\n    ],\n    onCambio: (valores) => {\n      // Al cambiar un filtro, volvemos a la pagina 1. Si no, el\n      // usuario podria quedar en la pagina 5 de un resultado que solo\n      // tiene 2 paginas y ver la lista vacia sin entender por que.\n      filtros = { ...valores, pagina: 1, limite: filtros.limite };\n      cargar();\n    },\n    onRecargar: () => cargar()\n  });\n\n  // =====================================================================\n  // CARGA DE DATOS\n  // =====================================================================\n\n  /** Pide los usuarios a la API y pinta el resultado. */\n  async function cargar() {\n    // ---- ESTADO 1: CARGANDO ----\n    pintar(CargadorBloque({ mensaje: 'Consultando usuarios en la API...' }));\n\n    try {\n      ultimaRespuesta = await usuarioServicio.listar(filtros);\n\n      if (onTotalCambiado !== null) {\n        onTotalCambiado(ultimaRespuesta.meta?.total ?? 0);\n      }\n\n      pintarTabla();\n    } catch (error) {\n      // ---- ESTADO 3: ERROR ----\n      pintar(EstadoError({ error, onReintentar: cargar }));\n      notificador.desdeErrorApi(error);\n    }\n  }\n\n  /** Envia los nodos a la plantilla, junto con la cabecera y la barra. */\n  function pintar(...nodos) {\n    onContenido(\n      CabeceraPagina({\n        titulo: 'Usuarios',\n        descripcion:\n          'Cada usuario corresponde a una fila de la tabla USUARIO. Al eliminarlo, ' +\n          'la API borra tambien sus telefonos y perfiles sociales dentro de una transaccion.',\n        accion: Boton({\n          texto: 'Nuevo usuario',\n          variante: 'primario',\n          icono: 'agregar',\n          onClick: () => abrirFormulario(null)\n        })\n      }),\n      barraBusqueda.elemento,\n      ...nodos\n    );\n  }\n\n  /** Pinta la tabla o el estado vacio. */\n  function pintarTabla() {\n    const { usuarios, meta } = ultimaRespuesta;\n\n    // ---- ESTADO 2: VACIO ----\n    if (usuarios.length === 0) {\n      // Distinguimos \"no hay nada\" de \"la busqueda no encontro nada\".\n      // Son situaciones distintas y necesitan mensajes distintos.\n      const hayFiltros = Boolean(filtros.buscar || filtros.estado);\n\n      pintar(\n        EstadoVacio({\n          titulo: hayFiltros ? 'Sin resultados' : 'No hay usuarios registrados',\n          mensaje: hayFiltros\n            ? 'Ningun usuario coincide con los filtros aplicados. Prueba a limpiarlos.'\n            : 'Crea el primer usuario para empezar a usar la aplicacion.',\n          icono: hayFiltros ? 'buscar' : 'usuarios',\n          accion: hayFiltros\n            ? {\n                texto: 'Limpiar filtros',\n                icono: 'limpiar',\n                onClick: () => {\n                  barraBusqueda.limpiar();\n                  filtros = { pagina: 1, limite: filtros.limite };\n                  cargar();\n                }\n              }\n            : {\n                texto: 'Crear el primer usuario',\n                onClick: () => abrirFormulario(null)\n              }\n        })\n      );\n      return;\n    }\n\n    // ---- ESTADO 4: CON DATOS ----\n    pintar(\n      TablaDatos({\n        titulo: 'Usuarios',\n        columnas: [\n          {\n            etiqueta: 'Id',\n            clase: 'id',\n            obtener: (usuario) => String(usuario.id)\n          },\n          {\n            etiqueta: 'Nombre completo',\n            clase: 'principal',\n            obtener: (usuario) =>\n              CeldaDoble(usuario.nombreCompleto, usuario.ciudadDomicilio)\n          },\n          {\n            etiqueta: 'Nacimiento',\n            obtener: (usuario) => fechaCorta(usuario.fechaNacimiento)\n          },\n          {\n            etiqueta: 'Edad',\n            clase: 'numero',\n            obtener: (usuario) => String(usuario.edad)\n          },\n          {\n            // El listado NO trae los arreglos de telefonos ni de\n            // perfiles: seria carisimo. Trae los CONTEOS, que la API\n            // calcula con subconsultas correlacionadas en la misma\n            // consulta (ver #columnasSelectListado del service).\n            etiqueta: 'Telefonos',\n            clase: 'numero',\n            obtener: (usuario) =>\n              Insignia({\n                texto: String(usuario.totalTelefonos ?? 0),\n                variante: 'primaria'\n              })\n          },\n          {\n            etiqueta: 'Perfiles',\n            clase: 'numero',\n            obtener: (usuario) =>\n              Insignia({\n                texto: String(usuario.totalPerfilesSociales ?? 0),\n                variante: 'terciaria'\n              })\n          },\n          {\n            etiqueta: 'Estado',\n            obtener: (usuario) => InsigniaEstado(usuario.estado)\n          }\n        ],\n        filas: ultimaRespuesta.usuarios,\n        claveFila: (usuario) => String(usuario.id),\n        onClicFila: (usuario) => abrirDetalle(usuario.id),\n        acciones: (usuario) => [\n          {\n            icono: 'ver',\n            etiqueta: `Ver el detalle de ${usuario.nombreCompleto}`,\n            onClick: () => abrirDetalle(usuario.id)\n          },\n          {\n            icono: 'editar',\n            etiqueta: `Editar a ${usuario.nombreCompleto}`,\n            onClick: () => abrirFormulario(usuario)\n          },\n          {\n            icono: 'eliminar',\n            etiqueta: `Eliminar a ${usuario.nombreCompleto}`,\n            onClick: () => confirmarBorrado(usuario)\n          }\n        ],\n        pie: Paginador({\n          meta,\n          onCambiarPagina: (pagina) => {\n            filtros = { ...filtros, pagina };\n            cargar();\n          },\n          onCambiarLimite: (limite) => {\n            filtros = { ...filtros, limite, pagina: 1 };\n            cargar();\n          }\n        })\n      })\n    );\n  }\n\n  // =====================================================================\n  // FORMULARIO DE CREAR / EDITAR\n  // =====================================================================\n\n  /**\n   * Abre el modal del formulario.\n   *\n   * @param {object|null} usuario  null para crear, el objeto para editar.\n   */\n  function abrirFormulario(usuario) {\n    const esEdicion = usuario !== null;\n\n    // Campo calculado: muestra la edad en vivo mientras se escribe la\n    // fecha. Es informativo; el valor real lo calcula el servidor.\n    const valorEdad = crear('strong', {\n      texto: esEdicion ? String(usuario.edad) : '—'\n    });\n\n    const campoEdad = crear(\n      'div',\n      { clase: 'm-campo-formulario' },\n      crear('span', { clase: 'a-etiqueta', texto: 'Edad (calculada)' }),\n      crear(\n        'div',\n        { clase: 'o-formulario__calculado' },\n        valorEdad,\n        crear('span', { texto: 'anios' })\n      ),\n      crear('p', {\n        clase: 'm-campo-formulario__ayuda',\n        texto: 'No se envia a la API: el servidor la recalcula desde la fecha de nacimiento.'\n      })\n    );\n\n    // Fecha de hoy en formato ISO, para el atributo max del calendario.\n    const hoy = new Date();\n    const hoyISO = `${hoy.getFullYear()}-${String(hoy.getMonth() + 1).padStart(2, '0')}-${String(hoy.getDate()).padStart(2, '0')}`;\n\n    const formulario = Formulario({\n      nota:\n        'La edad NO se envia: la calcula el servidor a partir de la fecha de nacimiento ' +\n        '(utils/fechas.js). Asi la columna edad nunca queda desincronizada.',\n      grupos: [\n        {\n          leyenda: 'Datos personales',\n          campos: [\n            {\n              id: 'usuario-primer-nombre',\n              nombre: 'primerNombre',\n              etiqueta: 'Primer nombre',\n              valor: usuario?.primerNombre ?? '',\n              requerido: true,\n              maximo: CONFIGURACION.longitudMaximaTexto,\n              autocompletar: 'given-name',\n              validar: (valor) =>\n                validarTexto(valor, {\n                  etiqueta: 'El primer nombre',\n                  soloLetras: true\n                })\n            },\n            {\n              id: 'usuario-segundo-nombre',\n              nombre: 'segundoNombre',\n              etiqueta: 'Segundo nombre',\n              valor: usuario?.segundoNombre ?? '',\n              maximo: CONFIGURACION.longitudMaximaTexto,\n              ayuda: 'Opcional (la columna admite NULL).',\n              validar: (valor) =>\n                validarTexto(valor, {\n                  etiqueta: 'El segundo nombre',\n                  requerido: false,\n                  soloLetras: true\n                })\n            },\n            {\n              id: 'usuario-primer-apellido',\n              nombre: 'primerApellido',\n              etiqueta: 'Primer apellido',\n              valor: usuario?.primerApellido ?? '',\n              requerido: true,\n              maximo: CONFIGURACION.longitudMaximaTexto,\n              autocompletar: 'family-name',\n              validar: (valor) =>\n                validarTexto(valor, {\n                  etiqueta: 'El primer apellido',\n                  soloLetras: true\n                })\n            },\n            {\n              id: 'usuario-segundo-apellido',\n              nombre: 'segundoApellido',\n              etiqueta: 'Segundo apellido',\n              valor: usuario?.segundoApellido ?? '',\n              maximo: CONFIGURACION.longitudMaximaTexto,\n              ayuda: 'Opcional (la columna admite NULL).',\n              validar: (valor) =>\n                validarTexto(valor, {\n                  etiqueta: 'El segundo apellido',\n                  requerido: false,\n                  soloLetras: true\n                })\n            }\n          ]\n        },\n        {\n          leyenda: 'Nacimiento y residencia',\n          campos: [\n            {\n              id: 'usuario-fecha-nacimiento',\n              nombre: 'fechaNacimiento',\n              etiqueta: 'Fecha de nacimiento',\n              tipo: 'date',\n              valor: usuario?.fechaNacimiento ?? '',\n              requerido: true,\n\n              // max = hoy: el calendario no deja elegir el futuro.\n              maximoValor: hoyISO,\n\n              ayuda: 'Formato AAAA-MM-DD. No puede ser una fecha futura.',\n\n              // Al escribir la fecha, actualizamos la edad en vivo.\n              onInput: (evento) => {\n                const edad = calcularEdad(evento.target.value);\n                valorEdad.textContent = edad === null ? '—' : String(edad);\n              },\n\n              validar: (valor) =>\n                validarFecha(valor, { etiqueta: 'La fecha de nacimiento' })\n            },\n            { elementoPersonalizado: campoEdad },\n            {\n              id: 'usuario-ciudad',\n              nombre: 'ciudadDomicilio',\n              etiqueta: 'Ciudad de domicilio',\n              valor: usuario?.ciudadDomicilio ?? '',\n              requerido: true,\n              maximo: CONFIGURACION.longitudMaximaTexto,\n              autocompletar: 'address-level2',\n              validar: (valor) =>\n                validarTexto(valor, {\n                  etiqueta: 'La ciudad de domicilio',\n                  soloLetras: true\n                })\n            },\n            {\n              id: 'usuario-estado',\n              nombre: 'estado',\n              etiqueta: 'Estado',\n              control: 'seleccion',\n              valor: String(usuario?.estado ?? 1),\n              opciones: [\n                { valor: '1', texto: 'Activo' },\n                { valor: '0', texto: 'Inactivo' }\n              ],\n              ayuda: 'Columna estado: 1 activo, 0 inactivo.'\n            }\n          ]\n        }\n      ]\n    });\n\n    const modal = Modal({\n      titulo: esEdicion ? `Editar usuario ${usuario.id}` : 'Nuevo usuario',\n      descripcion: esEdicion\n        ? 'PUT /api/usuarios/' + usuario.id + ' · solo se envian los campos modificados.'\n        : 'POST /api/usuarios',\n      cuerpo: formulario.elemento,\n      acciones: [\n        { texto: 'Cancelar', variante: 'texto', onClick: () => modal.cerrar() },\n        {\n          texto: esEdicion ? 'Guardar cambios' : 'Crear usuario',\n          variante: 'primario',\n          icono: 'guardar',\n          onClick: () => guardar({ modal, formulario, usuario })\n        }\n      ]\n    });\n\n    modal.abrir();\n\n    // Enfocamos el primer campo para que el usuario pueda escribir de\n    // inmediato, sin tener que hacer clic.\n    formulario.enfocarPrimero();\n  }\n\n  /**\n   * Envia el formulario a la API.\n   *\n   * Observa el orden de los pasos: validacion local, deshabilitar\n   * botones, peticion, y manejo diferenciado del error.\n   */\n  async function guardar({ modal, formulario, usuario }) {\n    // 1. Validacion LOCAL. Si falla, no gastamos una peticion.\n    if (!formulario.validar()) {\n      return;\n    }\n\n    const datos = formulario.obtenerDatos();\n\n    // 2. Bloqueamos los botones: evita el doble envio por doble clic.\n    modal.establecerCargando(true);\n\n    try {\n      if (usuario !== null) {\n        await usuarioServicio.actualizar(usuario.id, datos);\n        notificador.exito(`Usuario ${usuario.id} actualizado correctamente.`);\n      } else {\n        const creado = await usuarioServicio.crear(datos);\n        notificador.exito(\n          `Usuario \"${creado.nombreCompleto}\" creado con id ${creado.id}. ` +\n            `El servidor calculo su edad: ${creado.edad} anios.`\n        );\n      }\n\n      modal.cerrar();\n\n      // 3. Recargamos para ver el estado real guardado en la base.\n      await cargar();\n    } catch (error) {\n      modal.establecerCargando(false);\n\n      // Si la API devolvio errores de campo, los pintamos EN el\n      // formulario, junto a cada campo. Para cualquier otro error,\n      // una notificacion basta.\n      if (error.esValidacion) {\n        formulario.mostrarErroresServidor(error);\n      } else {\n        notificador.desdeErrorApi(error);\n      }\n    }\n  }\n\n  // =====================================================================\n  // BORRADO\n  // =====================================================================\n\n  /**\n   * Pide confirmacion y elimina el usuario.\n   *\n   * El mensaje avisa de las CONSECUENCIAS: cuantos telefonos y\n   * perfiles se van a borrar en cascada. Un dialogo que solo dice\n   * \"Seguro?\" no le da al usuario informacion para decidir.\n   */\n  function confirmarBorrado(usuario) {\n    const totalTelefonos = usuario.totalTelefonos ?? 0;\n    const totalPerfiles = usuario.totalPerfilesSociales ?? 0;\n\n    const consecuencias = [];\n    if (totalTelefonos > 0) {\n      consecuencias.push(`${totalTelefonos} telefono(s)`);\n    }\n    if (totalPerfiles > 0) {\n      consecuencias.push(`${totalPerfiles} perfil(es) social(es)`);\n    }\n\n    const detalle =\n      consecuencias.length > 0\n        ? ` La API tambien eliminara, dentro de una transaccion, ${consecuencias.join(' y ')}.`\n        : '';\n\n    const modal = ModalConfirmacion({\n      titulo: `Eliminar a ${usuario.nombreCompleto}?`,\n      mensaje:\n        `Se ejecutara DELETE /api/usuarios/${usuario.id}.${detalle} ` +\n        'Esta accion no se puede deshacer.',\n      textoConfirmar: 'Si, eliminar',\n      onConfirmar: async () => {\n        try {\n          const resumen = await usuarioServicio.eliminar(usuario.id);\n\n          notificador.exito(\n            `Usuario \"${resumen.nombreCompleto}\" eliminado. ` +\n              `Telefonos borrados: ${resumen.telefonosEliminados}. ` +\n              `Perfiles borrados: ${resumen.perfilesEliminados}.`\n          );\n\n          await cargar();\n        } catch (error) {\n          notificador.desdeErrorApi(error);\n          throw error;\n        }\n      }\n    });\n\n    modal.abrir();\n  }\n\n  // =====================================================================\n  // DETALLE (con telefonos y perfiles sociales)\n  // =====================================================================\n\n  /** Abre el modal de detalle de un usuario. */\n  async function abrirDetalle(id) {\n    const contenedor = crear('div', {}, CargadorBloque({ mensaje: 'Cargando el detalle...' }));\n\n    const modal = Modal({\n      titulo: `Detalle del usuario ${id}`,\n      descripcion: `GET /api/usuarios/${id} · una sola peticion trae el usuario, sus telefonos y sus perfiles sociales.`,\n      cuerpo: contenedor,\n      acciones: [{ texto: 'Cerrar', variante: 'tonal', onClick: () => modal.cerrar() }]\n    });\n\n    modal.abrir();\n\n    /** Recarga el contenido del modal sin cerrarlo. */\n    async function refrescarDetalle() {\n      try {\n        const usuario = await usuarioServicio.obtener(id);\n\n        contenedor.replaceChildren(\n          PanelDetalleUsuario({\n            usuario,\n            acciones: {\n              onAgregarTelefono: () =>\n                abrirFormularioTelefono(null, usuario, refrescarDetalle),\n              onEditarTelefono: (telefono) =>\n                abrirFormularioTelefono(telefono, usuario, refrescarDetalle),\n              onCambiarEstadoTelefono: async (telefono, activar) => {\n                try {\n                  await telefonoServicio.cambiarEstado(telefono.id, activar);\n                  notificador.exito(\n                    `Telefono ${telefono.numeroTelefono} ${activar ? 'activado' : 'desactivado'}.`\n                  );\n                  await refrescarDetalle();\n                  await cargar();\n                } catch (error) {\n                  notificador.desdeErrorApi(error);\n                }\n              },\n              onEliminarTelefono: (telefono) =>\n                confirmarBorradoTelefono(telefono, refrescarDetalle),\n              onAgregarPerfil: () =>\n                abrirFormularioPerfil(null, usuario, refrescarDetalle),\n              onEditarPerfil: (perfil) =>\n                abrirFormularioPerfil(perfil, usuario, refrescarDetalle),\n              onEliminarPerfil: (perfil) =>\n                confirmarBorradoPerfil(perfil, refrescarDetalle)\n            }\n          })\n        );\n      } catch (error) {\n        contenedor.replaceChildren(\n          EstadoError({ error, onReintentar: refrescarDetalle })\n        );\n      }\n    }\n\n    await refrescarDetalle();\n  }\n\n  // =====================================================================\n  // SUBRECURSOS: telefonos y perfiles sociales del usuario\n  // =====================================================================\n\n  /** Formulario de telefono dentro del detalle del usuario. */\n  function abrirFormularioTelefono(telefono, usuario, alTerminar) {\n    const esEdicion = telefono !== null;\n\n    const formulario = Formulario({\n      nota:\n        esEdicion\n          ? `PUT /api/telefonos/${telefono.id}`\n          : `POST /api/usuarios/${usuario.id}/telefonos · el usuarioId viaja en la URL, no en el cuerpo.`,\n      grupos: [\n        {\n          campos: [\n            {\n              id: 'telefono-numero',\n              nombre: 'numeroTelefono',\n              etiqueta: 'Numero de telefono',\n              tipo: 'tel',\n              valor: telefono?.numeroTelefono ?? '',\n              requerido: true,\n              maximo: CONFIGURACION.longitudMaximaTexto,\n              autocompletar: 'tel',\n              ayuda: 'Digitos, espacios, + y guiones. Entre 7 y 20 caracteres.',\n              validar: (valor) => validarTelefono(valor)\n            },\n            {\n              id: 'telefono-tipo',\n              nombre: 'tipoTelefono',\n              etiqueta: 'Tipo de telefono',\n              control: 'seleccion',\n              valor: telefono?.tipoTelefono ?? '',\n              requerido: true,\n              textoVacio: 'Selecciona un tipo',\n              opciones: CONFIGURACION.tiposTelefono.map((tipo) => ({\n                valor: tipo,\n                texto: tipo\n              })),\n              validar: (valor) =>\n                validarOpcion(valor, CONFIGURACION.tiposTelefono, {\n                  etiqueta: 'El tipo de telefono'\n                })\n            },\n            {\n              id: 'telefono-activo',\n              nombre: 'activo',\n              etiqueta: 'Estado',\n              control: 'seleccion',\n              valor: String(telefono?.activo ?? 1),\n              opciones: [\n                { valor: '1', texto: 'Activo' },\n                { valor: '0', texto: 'Inactivo' }\n              ]\n            }\n          ]\n        }\n      ]\n    });\n\n    const modal = Modal({\n      titulo: esEdicion ? `Editar el telefono ${telefono.id}` : 'Nuevo telefono',\n      descripcion: `Usuario: ${usuario.nombreCompleto} (id ${usuario.id})`,\n      cuerpo: formulario.elemento,\n      acciones: [\n        { texto: 'Cancelar', variante: 'texto', onClick: () => modal.cerrar() },\n        {\n          texto: esEdicion ? 'Guardar' : 'Crear telefono',\n          variante: 'primario',\n          icono: 'guardar',\n          onClick: async () => {\n            if (!formulario.validar()) return;\n\n            modal.establecerCargando(true);\n\n            try {\n              const datos = formulario.obtenerDatos();\n\n              if (esEdicion) {\n                await telefonoServicio.actualizar(telefono.id, datos);\n                notificador.exito('Telefono actualizado correctamente.');\n              } else {\n                // Usamos la ruta de subrecurso: el usuarioId va en la URL.\n                await telefonoServicio.crearParaUsuario(usuario.id, datos);\n                notificador.exito('Telefono creado correctamente.');\n              }\n\n              modal.cerrar();\n              await alTerminar();\n              await cargar();\n            } catch (error) {\n              modal.establecerCargando(false);\n\n              if (error.esValidacion) {\n                formulario.mostrarErroresServidor(error);\n              } else {\n                notificador.desdeErrorApi(error);\n              }\n            }\n          }\n        }\n      ]\n    });\n\n    modal.abrir();\n    formulario.enfocarPrimero();\n  }\n\n  /** Confirma y borra un telefono. */\n  function confirmarBorradoTelefono(telefono, alTerminar) {\n    const modal = ModalConfirmacion({\n      titulo: 'Eliminar este telefono?',\n      mensaje: `Se ejecutara DELETE /api/telefonos/${telefono.id} (${telefono.numeroTelefono}).`,\n      onConfirmar: async () => {\n        try {\n          await telefonoServicio.eliminar(telefono.id);\n          notificador.exito('Telefono eliminado correctamente.');\n          await alTerminar();\n          await cargar();\n        } catch (error) {\n          notificador.desdeErrorApi(error);\n          throw error;\n        }\n      }\n    });\n\n    modal.abrir();\n  }\n\n  /**\n   * Formulario de perfil social.\n   *\n   * CASO INTERESANTE DE LA LLAVE COMPUESTA:\n   * al CREAR hay que elegir la red social (es la mitad de la llave),\n   * pero al EDITAR ese campo queda deshabilitado, porque la llave\n   * identifica el recurso y no se puede cambiar. Si el usuario\n   * necesita moverlo a otra red, tiene que borrar y crear de nuevo.\n   */\n  async function abrirFormularioPerfil(perfil, usuario, alTerminar) {\n    const esEdicion = perfil !== null;\n\n    // Necesitamos el catalogo de redes para llenar el desplegable.\n    // El servicio lo trae de su cache si ya lo pidio antes.\n    let catalogoRedes = [];\n\n    try {\n      catalogoRedes = await redSocialServicio.obtenerCatalogo();\n    } catch (error) {\n      notificador.desdeErrorApi(error);\n      return;\n    }\n\n    if (catalogoRedes.length === 0) {\n      notificador.advertencia(\n        'Primero crea al menos una red social en la seccion \"Redes sociales\".'\n      );\n      return;\n    }\n\n    const formulario = Formulario({\n      nota: esEdicion\n        ? `PUT /api/perfiles-sociales/${perfil.redSocialId}/${perfil.usuarioId} · solo se puede cambiar urlPerfil, porque la llave compuesta identifica el recurso.`\n        : `POST /api/usuarios/${usuario.id}/perfiles-sociales · la llave primaria es (RED_SOCIAL_id, USUARIO_id), asi que un usuario solo puede tener un perfil por red.`,\n      grupos: [\n        {\n          campos: [\n            {\n              id: 'perfil-red-social',\n              nombre: 'redSocialId',\n              etiqueta: 'Red social',\n              control: 'seleccion',\n              valor: String(perfil?.redSocialId ?? ''),\n              requerido: !esEdicion,\n              textoVacio: 'Selecciona una red social',\n\n              // Al editar, la mitad de la llave compuesta es inmutable.\n              deshabilitado: esEdicion,\n\n              opciones: catalogoRedes.map((red) => ({\n                valor: red.id,\n                texto: `${red.nombre} (id ${red.id})`\n              })),\n              ayuda: esEdicion\n                ? 'No se puede cambiar: forma parte de la llave primaria.'\n                : 'Mitad de la llave compuesta (RED_SOCIAL_id).',\n              validar: esEdicion ? null : (valor) =>\n                valor === '' ? 'Debes elegir una red social.' : null\n            },\n            {\n              id: 'perfil-url',\n              nombre: 'urlPerfil',\n              etiqueta: 'URL del perfil',\n              tipo: 'url',\n              valor: perfil?.urlPerfil ?? '',\n              maximo: CONFIGURACION.longitudMaximaTexto,\n              anchoCompleto: true,\n              ayuda: `Opcional. Maximo ${CONFIGURACION.longitudMaximaTexto} caracteres (VARCHAR(45) del modelo).`,\n              validar: (valor) =>\n                validarURL(valor, {\n                  etiqueta: 'La URL del perfil',\n                  requerido: false\n                })\n            }\n          ]\n        }\n      ]\n    });\n\n    const modal = Modal({\n      titulo: esEdicion\n        ? `Editar el perfil ${perfil.redSocialId}:${perfil.usuarioId}`\n        : 'Nuevo perfil social',\n      descripcion: `Usuario: ${usuario.nombreCompleto} (id ${usuario.id})`,\n      cuerpo: formulario.elemento,\n      acciones: [\n        { texto: 'Cancelar', variante: 'texto', onClick: () => modal.cerrar() },\n        {\n          texto: esEdicion ? 'Guardar' : 'Crear perfil',\n          variante: 'primario',\n          icono: 'guardar',\n          onClick: async () => {\n            if (!formulario.validar()) return;\n\n            modal.establecerCargando(true);\n\n            try {\n              const datos = formulario.obtenerDatos();\n\n              if (esEdicion) {\n                // Solo enviamos urlPerfil: la API rechaza cualquier\n                // intento de cambiar la llave compuesta.\n                await perfilSocialServicio.actualizar(\n                  perfil.redSocialId,\n                  perfil.usuarioId,\n                  { urlPerfil: datos.urlPerfil ?? '' }\n                );\n                notificador.exito('Perfil social actualizado correctamente.');\n              } else {\n                await perfilSocialServicio.crearParaUsuario(usuario.id, datos);\n                notificador.exito('Perfil social creado correctamente.');\n              }\n\n              modal.cerrar();\n              await alTerminar();\n              await cargar();\n            } catch (error) {\n              modal.establecerCargando(false);\n\n              if (error.esValidacion) {\n                formulario.mostrarErroresServidor(error);\n              } else {\n                notificador.desdeErrorApi(error);\n              }\n            }\n          }\n        }\n      ]\n    });\n\n    modal.abrir();\n    formulario.enfocarPrimero();\n  }\n\n  /** Confirma y borra un perfil social por su llave compuesta. */\n  function confirmarBorradoPerfil(perfil, alTerminar) {\n    const modal = ModalConfirmacion({\n      titulo: 'Eliminar este perfil social?',\n      mensaje:\n        `Se ejecutara DELETE /api/perfiles-sociales/${perfil.redSocialId}/${perfil.usuarioId}. ` +\n        'Los dos valores de la URL forman la llave primaria compuesta.',\n      onConfirmar: async () => {\n        try {\n          await perfilSocialServicio.eliminar(perfil.redSocialId, perfil.usuarioId);\n          notificador.exito('Perfil social eliminado correctamente.');\n          await alTerminar();\n          await cargar();\n        } catch (error) {\n          notificador.desdeErrorApi(error);\n          throw error;\n        }\n      }\n    });\n\n    modal.abrir();\n  }\n\n  // Interfaz publica de la pagina.\n  return { cargar };\n}\n","persona-frontend/js/plantillas/panelAdministracion.js":"/**\n * js/plantillas/panelAdministracion.js\n * ---------------------------------------------------------------------\n * PLANTILLA: Panel de administracion\n *\n * ATOMIC DESIGN - NIVEL 4: PLANTILLAS\n * Una plantilla ENSAMBLA organismos y define la estructura de la\n * pagina, pero NO conoce el contenido real.\n *\n * Fijate en lo que esta plantilla NO hace:\n *   - no llama a la API;\n *   - no sabe si la tabla muestra usuarios o redes sociales;\n *   - no valida nada.\n *\n * Solo dice: \"la barra arriba, la navegacion a la izquierda y el\n * contenido a la derecha\". Quien le pone contenido es la PAGINA.\n *\n * Esa ignorancia deliberada es lo que la hace reutilizable: la misma\n * plantilla sirve para las cuatro secciones de la aplicacion.\n */\n\nimport { crear, reemplazarContenido } from '../utiles/dom.js';\nimport { BarraSuperior } from '../organismos/barraSuperior.js';\nimport { NavegacionLateral } from '../organismos/navegacionLateral.js';\n\n/**\n * @param {object} propiedades\n * @param {Array} propiedades.secciones  Definicion del menu.\n * @param {string} propiedades.seccionActiva\n * @param {function} propiedades.onNavegar\n * @returns {{elemento, montarEn, establecerContenido, barraSuperior, navegacion}}\n */\nexport function PanelAdministracion({\n  secciones = [],\n  seccionActiva = null,\n  onNavegar = null\n} = {}) {\n  // ---- Organismos ----\n  const navegacion = NavegacionLateral({\n    secciones,\n    activa: seccionActiva,\n    onNavegar\n  });\n\n  const barraSuperior = BarraSuperior({\n    // La barra no sabe como se abre el menu: solo avisa. La plantilla\n    // conecta el aviso con el metodo de la navegacion.\n    onAbrirMenu: () => navegacion.abrir()\n  });\n\n  // -------------------------------------------------------------------\n  // CLASE DE POSICIONAMIENTO\n  // -------------------------------------------------------------------\n  // El organismo BarraSuperior define COMO SE VE (.o-barra-superior).\n  // La plantilla define DONDE VA (.t-panel-administracion__barra, que\n  // lleva el grid-area: barra).\n  //\n  // Esa separacion es una regla central del Atomic Design: un\n  // organismo nunca sabe en que parte de la pagina lo van a poner, asi\n  // que la clase de posicionamiento la agrega quien lo coloca.\n  //\n  // Si se olvida esta linea, el <header> no tiene grid-area y CSS Grid\n  // lo auto-coloca en la primera celda libre: se mete en la columna de\n  // la navegacion (256px) y el titulo se desborda sobre los botones.\n  barraSuperior.elemento.classList.add('t-panel-administracion__barra');\n\n  // ---- Zona de contenido, que cambia con cada seccion ----\n  const contenido = crear('main', {\n    clase: 't-panel-administracion__contenido',\n\n    // id=\"contenido-principal\" es el destino del enlace\n    // \"Saltar al contenido\".\n    id: 'contenido-principal',\n\n    // tabindex=\"-1\" permite enfocarlo por JavaScript tras el salto,\n    // sin agregarlo al recorrido normal de la tecla Tab.\n    tabIndex: -1\n  });\n\n  // ---- Estructura (la cuadricula la define el CSS) ----\n  const elemento = crear(\n    'div',\n    { clase: 't-panel-administracion' },\n\n    // El enlace de salto debe ser el PRIMER elemento enfocable de la\n    // pagina, para que aparezca con la primera pulsacion de Tab.\n    crear('a', {\n      clase: 'salto-contenido',\n      href: '#contenido-principal',\n      texto: 'Saltar al contenido principal'\n    }),\n\n    barraSuperior.elemento,\n    crear(\n      'div',\n      { clase: 't-panel-administracion__navegacion' },\n      navegacion.elemento\n    ),\n    contenido,\n\n    // El velo va al final del DOM para que quede por encima en el\n    // apilamiento natural, sin depender solo del z-index.\n    navegacion.velo\n  );\n\n  return {\n    elemento,\n    barraSuperior,\n    navegacion,\n\n    /** Inserta la plantilla en un contenedor del documento. */\n    montarEn(contenedor) {\n      reemplazarContenido(contenedor, elemento);\n    },\n\n    /**\n     * Reemplaza el contenido principal por la vista de una pagina.\n     * Es el unico punto por donde entra el contenido dinamico.\n     */\n    establecerContenido(...nodos) {\n      reemplazarContenido(contenido, ...nodos);\n\n      // Volvemos el desplazamiento arriba al cambiar de seccion. Sin\n      // esto, al pasar de la pagina 5 de usuarios a redes sociales, la\n      // vista aparece a mitad de camino y confunde.\n      contenido.scrollTop = 0;\n    },\n\n    /** Devuelve el nodo del contenido, para casos puntuales. */\n    obtenerContenedorContenido() {\n      return contenido;\n    }\n  };\n}\n\n/**\n * Cabecera de pagina: titulo, descripcion y accion principal.\n *\n * La ponemos aqui, en el nivel de plantilla, porque es un patron de\n * ESTRUCTURA que las cuatro paginas repiten igual.\n *\n * @param {object} propiedades\n * @param {string} propiedades.titulo\n * @param {string} propiedades.descripcion\n * @param {HTMLElement} propiedades.accion\n */\nexport function CabeceraPagina({ titulo, descripcion = null, accion = null } = {}) {\n  return crear(\n    'div',\n    { clase: 't-panel-administracion__cabecera' },\n    crear(\n      'div',\n      {},\n      // Es un h2 porque el h1 de la pagina es el titulo de la\n      // aplicacion, en la barra superior. Los encabezados tienen que\n      // formar una jerarquia sin saltos: h1 -> h2 -> h3.\n      crear('h2', { clase: 't-panel-administracion__titulo', texto: titulo }),\n      descripcion\n        ? crear('p', {\n            clase: 't-panel-administracion__descripcion',\n            texto: descripcion\n          })\n        : null\n    ),\n    accion\n  );\n}\n","persona-frontend/js/servicios/clienteApi.js":"/**\n * js/servicios/clienteApi.js\n * ---------------------------------------------------------------------\n * CLIENTE HTTP: el unico lugar del frontend que habla con la API.\n *\n * POR QUE CENTRALIZAR TODAS LAS PETICIONES EN UNA CLASE?\n *\n * Imagina que cada pagina llamara a fetch() por su cuenta. Entonces,\n * cada una tendria que repetir:\n *   - la URL base,\n *   - la cabecera Content-Type,\n *   - el manejo del tiempo de espera,\n *   - la lectura del JSON,\n *   - la interpretacion del error.\n *\n * Y el dia que la API cambie de formato, habria que corregir 10\n * archivos. Con esta clase, se corrige UNO.\n *\n * Es el mismo razonamiento de config/database.js en el backend: un\n * unico punto de acceso al recurso externo.\n *\n * ADEMAS: aqui definimos la clase ErrorApi, que convierte la respuesta\n * de error del servidor en un objeto de JavaScript con el que el resto\n * de la aplicacion puede trabajar con comodidad.\n */\n\nimport { CONFIGURACION } from '../config/configuracion.js';\n\n/**\n * Error propio de la capa de API.\n *\n * Igual que utils/AppError.js del backend, HEREDA de Error (extends)\n * y le agrega la informacion que necesitamos: el codigo HTTP, el\n * codigo interno y la lista de campos invalidos.\n *\n * Asi, un `catch` puede preguntar `error.esValidacion` en lugar de\n * analizar textos.\n */\nexport class ErrorApi extends Error {\n  #estadoHttp;\n  #codigo;\n  #detalles;\n\n  constructor(mensaje, estadoHttp = 0, codigo = 'DESCONOCIDO', detalles = []) {\n    super(mensaje);\n\n    this.name = 'ErrorApi';\n    this.#estadoHttp = estadoHttp;\n    this.#codigo = codigo;\n    this.#detalles = Array.isArray(detalles) ? detalles : [];\n  }\n\n  get estadoHttp() {\n    return this.#estadoHttp;\n  }\n\n  get codigo() {\n    return this.#codigo;\n  }\n\n  get detalles() {\n    return [...this.#detalles];\n  }\n\n  /** true si el error trae una lista de campos invalidos (HTTP 400). */\n  get esValidacion() {\n    return this.#codigo === 'VALIDACION' || this.#estadoHttp === 400;\n  }\n\n  /** true si el recurso no existe (HTTP 404). */\n  get esNoEncontrado() {\n    return this.#estadoHttp === 404;\n  }\n\n  /** true si choco con una regla de unicidad o integridad (HTTP 409). */\n  get esConflicto() {\n    return this.#estadoHttp === 409;\n  }\n\n  /**\n   * true si nunca se pudo contactar al servidor.\n   * estadoHttp vale 0 porque no hubo respuesta HTTP: la peticion no\n   * llego a salir o el servidor no contesto.\n   */\n  get esSinConexion() {\n    return this.#estadoHttp === 0;\n  }\n}\n\nclass ClienteApi {\n  #urlBase;\n  #tiempoEsperaMs;\n\n  constructor(urlBase, tiempoEsperaMs) {\n    this.#urlBase = urlBase;\n    this.#tiempoEsperaMs = tiempoEsperaMs;\n  }\n\n  get urlBase() {\n    return this.#urlBase;\n  }\n\n  /**\n   * Construye la cadena de consulta (query string) a partir de un objeto.\n   *\n   *   { pagina: 2, buscar: 'hopper', ciudad: null }\n   *   -> \"?pagina=2&buscar=hopper\"\n   *\n   * Dos detalles importantes:\n   *   1. Omitimos los valores vacios, para no enviar \"?ciudad=\".\n   *   2. Usamos URLSearchParams, que CODIFICA los caracteres\n   *      especiales. Si el usuario busca \"a&b\", sin codificar el \"&\"\n   *      partiria la URL y el parametro se perderia.\n   *\n   * @param {object} parametros\n   * @returns {string}\n   */\n  #construirConsulta(parametros = {}) {\n    const consulta = new URLSearchParams();\n\n    for (const [clave, valor] of Object.entries(parametros)) {\n      if (valor === null || valor === undefined || valor === '') continue;\n      consulta.append(clave, String(valor));\n    }\n\n    const texto = consulta.toString();\n    return texto === '' ? '' : `?${texto}`;\n  }\n\n  /**\n   * Ejecuta una peticion HTTP y devuelve el cuerpo ya interpretado.\n   *\n   * @param {string} ruta      Ruta relativa, por ejemplo '/usuarios/5'.\n   * @param {object} opciones  { metodo, cuerpo, parametros }\n   * @returns {Promise<object>} El JSON de la respuesta.\n   * @throws {ErrorApi}\n   */\n  async #peticion(ruta, opciones = {}) {\n    const { metodo = 'GET', cuerpo = null, parametros = {} } = opciones;\n\n    const url = `${this.#urlBase}${ruta}${this.#construirConsulta(parametros)}`;\n\n    /**\n     * TIEMPO DE ESPERA (timeout)\n     *\n     * fetch() no tiene opcion de timeout: si el servidor no responde,\n     * la promesa queda pendiente para siempre y el usuario ve el\n     * spinner eternamente.\n     *\n     * La solucion estandar es AbortController: creamos un\n     * \"controlador de cancelacion\", le pasamos su senial a fetch y,\n     * pasados N milisegundos, llamamos a abort(). Eso hace que fetch\n     * rechace la promesa con un error de tipo AbortError.\n     */\n    const controlador = new AbortController();\n    const temporizador = setTimeout(() => controlador.abort(), this.#tiempoEsperaMs);\n\n    try {\n      const configuracionPeticion = {\n        method: metodo,\n        headers: {\n          Accept: 'application/json'\n        },\n        signal: controlador.signal\n      };\n\n      // Solo agregamos cuerpo y Content-Type si hay algo que enviar.\n      // Un GET con cuerpo es invalido en HTTP.\n      if (cuerpo !== null) {\n        configuracionPeticion.headers['Content-Type'] = 'application/json';\n        configuracionPeticion.body = JSON.stringify(cuerpo);\n      }\n\n      const respuesta = await fetch(url, configuracionPeticion);\n\n      // ----- Interpretar el cuerpo -----\n      // Una respuesta 204 (No Content) no tiene cuerpo: si\n      // intentaramos leer el JSON, lanzaria una excepcion.\n      let datos = null;\n\n      if (respuesta.status !== 204) {\n        const textoRespuesta = await respuesta.text();\n\n        if (textoRespuesta !== '') {\n          try {\n            datos = JSON.parse(textoRespuesta);\n          } catch {\n            // El servidor respondio algo que no era JSON (por ejemplo\n            // una pagina HTML de error de un proxy).\n            throw new ErrorApi(\n              'El servidor respondio en un formato que no se pudo interpretar.',\n              respuesta.status,\n              'RESPUESTA_INVALIDA'\n            );\n          }\n        }\n      }\n\n      // ----- Interpretar el estado -----\n      //\n      // OJO, ESTO SORPRENDE A TODO EL MUNDO LA PRIMERA VEZ:\n      // fetch() NO lanza error con un 404 ni con un 500. Solo falla si\n      // la peticion no llego a salir (sin red, CORS, DNS).\n      //\n      // Por eso HAY que revisar respuesta.ok a mano. Es el error\n      // numero uno al aprender fetch: se asume que un 500 cae en el\n      // catch, y no es asi.\n      if (!respuesta.ok) {\n        const error = datos?.error ?? {};\n\n        throw new ErrorApi(\n          error.mensaje ?? `Error HTTP ${respuesta.status}`,\n          respuesta.status,\n          error.codigo ?? 'ERROR_HTTP',\n          error.detalles ?? []\n        );\n      }\n\n      return datos;\n    } catch (error) {\n      // Si ya es un ErrorApi, lo dejamos pasar tal cual.\n      if (error instanceof ErrorApi) throw error;\n\n      // El AbortController cancelo la peticion por tiempo de espera.\n      if (error.name === 'AbortError') {\n        throw new ErrorApi(\n          `El servidor no respondio en ${this.#tiempoEsperaMs / 1000} segundos. Verifica que la API este encendida.`,\n          0,\n          'TIEMPO_AGOTADO'\n        );\n      }\n\n      // TypeError es lo que lanza fetch cuando no hay red, el servidor\n      // esta apagado o CORS bloqueo la peticion.\n      throw new ErrorApi(\n        'No se pudo conectar con la API. Revisa que el servidor este corriendo en ' +\n          this.#urlBase +\n          ' y que CORS permita este origen.',\n        0,\n        'SIN_CONEXION'\n      );\n    } finally {\n      // Limpiamos el temporizador siempre, haya exito o error. Si no,\n      // quedaria un setTimeout pendiente por cada peticion.\n      clearTimeout(temporizador);\n    }\n  }\n\n  // ---------------- Metodos publicos por verbo HTTP ----------------\n\n  /** GET: leer. Es el unico verbo que lleva parametros de consulta. */\n  obtener(ruta, parametros = {}) {\n    return this.#peticion(ruta, { metodo: 'GET', parametros });\n  }\n\n  /** POST: crear. */\n  crear(ruta, cuerpo) {\n    return this.#peticion(ruta, { metodo: 'POST', cuerpo });\n  }\n\n  /** PUT: actualizar. */\n  actualizar(ruta, cuerpo) {\n    return this.#peticion(ruta, { metodo: 'PUT', cuerpo });\n  }\n\n  /** PATCH: modificacion parcial puntual. */\n  modificar(ruta, cuerpo = {}) {\n    return this.#peticion(ruta, { metodo: 'PATCH', cuerpo });\n  }\n\n  /** DELETE: eliminar. */\n  eliminar(ruta) {\n    return this.#peticion(ruta, { metodo: 'DELETE' });\n  }\n\n  /**\n   * Comprueba si la API esta disponible.\n   * Devuelve un booleano en vez de lanzar, porque es una consulta\n   * informativa para el indicador de la barra superior.\n   */\n  async verificarSalud() {\n    try {\n      const respuesta = await this.obtener('/salud');\n      return respuesta?.ok === true;\n    } catch {\n      return false;\n    }\n  }\n}\n\n// SINGLETON: una sola instancia para toda la aplicacion.\nexport const clienteApi = new ClienteApi(\n  CONFIGURACION.urlApi,\n  CONFIGURACION.tiempoEsperaMs\n);\n","persona-frontend/js/utiles/dom.js":"/**\n * js/utiles/dom.js\n * ---------------------------------------------------------------------\n * Utilidades para crear y manipular elementos del DOM.\n *\n * EL PROBLEMA QUE RESUELVE ESTE ARCHIVO\n * ---------------------------------------------------------------------\n * Crear elementos con la API nativa es muy verboso:\n *\n *   const boton = document.createElement('button');\n *   boton.className = 'a-boton a-boton--primario';\n *   boton.textContent = 'Guardar';\n *   boton.addEventListener('click', guardar);\n *   contenedor.appendChild(boton);\n *\n * Con el ayudante `crear` queda en una linea:\n *\n *   crear('button', {\n *     clase: 'a-boton a-boton--primario',\n *     texto: 'Guardar',\n *     onClick: guardar\n *   })\n *\n * POR QUE NO USAR innerHTML?\n * ---------------------------------------------------------------------\n * Porque innerHTML con datos del usuario abre la puerta a un ataque\n * XSS (Cross-Site Scripting). Si un usuario se llama:\n *\n *   <img src=x onerror=\"alert('me robe tu sesion')\">\n *\n * y lo insertamos con innerHTML, el navegador EJECUTA ese codigo.\n *\n * Con textContent, el navegador lo trata como TEXTO: se muestra el\n * texto literal y nada se ejecuta. Es seguro por diseno.\n *\n * Regla practica: innerHTML solo con texto que escribimos nosotros\n * (nunca con datos de la API o de un formulario).\n */\n\n/**\n * Crea un elemento del DOM con sus propiedades y sus hijos.\n *\n * @param {string} etiqueta    Nombre de la etiqueta HTML ('div', 'button'...).\n * @param {object} propiedades Configuracion del elemento.\n * @param {...(Node|string|null)} hijos  Elementos o textos a insertar dentro.\n * @returns {HTMLElement}\n */\nexport function crear(etiqueta, propiedades = {}, ...hijos) {\n  const elemento = document.createElement(etiqueta);\n\n  // Recorremos las propiedades y las aplicamos segun su nombre.\n  for (const [clave, valor] of Object.entries(propiedades)) {\n    // Saltamos los valores vacios para no poner atributos inutiles.\n    if (valor === null || valor === undefined || valor === false) continue;\n\n    // ---- Caso 1: clases CSS ----\n    if (clave === 'clase') {\n      elemento.className = valor;\n      continue;\n    }\n\n    // ---- Caso 2: texto (seguro, no interpreta HTML) ----\n    if (clave === 'texto') {\n      elemento.textContent = valor;\n      continue;\n    }\n\n    // ---- Caso 3: HTML interno. Solo para marcado nuestro (iconos). ----\n    if (clave === 'html') {\n      elemento.innerHTML = valor;\n      continue;\n    }\n\n    // ---- Caso 4: manejadores de evento (onClick, onInput...) ----\n    // Detectamos las propiedades que empiezan por \"on\" seguido de\n    // mayuscula y las convertimos en addEventListener.\n    if (clave.startsWith('on') && typeof valor === 'function') {\n      // 'onClick' -> 'click'\n      const evento = clave.slice(2).toLowerCase();\n      elemento.addEventListener(evento, valor);\n      continue;\n    }\n\n    // ---- Caso 5: atributos data-* y aria-* ----\n    // Estos SI tienen que ir como atributo, no como propiedad del\n    // objeto, porque el DOM no expone una propiedad con ese nombre.\n    if (clave.startsWith('data') || clave.startsWith('aria')) {\n      // 'dataEtiqueta' -> 'data-etiqueta'; 'ariaLabel' -> 'aria-label'\n      const atributo = clave\n        .replace(/([A-Z])/g, '-$1')\n        .toLowerCase();\n      elemento.setAttribute(atributo, valor);\n      continue;\n    }\n\n    // ---- Caso 6: estilos en linea ----\n    if (clave === 'estilo' && typeof valor === 'object') {\n      Object.assign(elemento.style, valor);\n      continue;\n    }\n\n    // ---- Caso 7: cualquier otra propiedad del DOM ----\n    // id, type, value, disabled, href, placeholder, etc.\n    // Preferimos la propiedad al atributo porque es mas rapida y\n    // respeta los tipos (disabled = true, no disabled=\"true\").\n    if (clave in elemento) {\n      elemento[clave] = valor;\n    } else {\n      elemento.setAttribute(clave, valor);\n    }\n  }\n\n  // Insertamos los hijos. flat(Infinity) aplana los arreglos anidados\n  // para poder escribir crear('ul', {}, items.map(...)) sin envolver.\n  for (const hijo of hijos.flat(Infinity)) {\n    if (hijo === null || hijo === undefined || hijo === false) continue;\n\n    // Un texto se convierte en nodo de texto (de nuevo: seguro).\n    if (typeof hijo === 'string' || typeof hijo === 'number') {\n      elemento.appendChild(document.createTextNode(String(hijo)));\n    } else {\n      elemento.appendChild(hijo);\n    }\n  }\n\n  return elemento;\n}\n\n/**\n * Atajo de document.querySelector.\n * @param {string} selector\n * @param {Document|HTMLElement} raiz\n * @returns {HTMLElement|null}\n */\nexport function buscar(selector, raiz = document) {\n  return raiz.querySelector(selector);\n}\n\n/**\n * Atajo de querySelectorAll que devuelve un ARREGLO de verdad.\n *\n * querySelectorAll devuelve una NodeList, que NO tiene map ni filter.\n * Array.from la convierte en arreglo para poder usar todos los\n * metodos de iteracion.\n */\nexport function buscarTodos(selector, raiz = document) {\n  return Array.from(raiz.querySelectorAll(selector));\n}\n\n/**\n * Borra todos los hijos de un elemento.\n *\n * Por que no `elemento.innerHTML = ''`?\n * Porque con innerHTML el navegador tiene que parsear una cadena\n * vacia y, en algunos casos, no libera bien los manejadores de\n * eventos de los hijos. removeChild en bucle es explicito y rapido.\n *\n * @param {HTMLElement} elemento\n */\nexport function vaciar(elemento) {\n  while (elemento.firstChild) {\n    elemento.removeChild(elemento.firstChild);\n  }\n}\n\n/**\n * Reemplaza todo el contenido de un elemento por los nuevos hijos.\n * Es la operacion mas frecuente al re-renderizar una vista.\n *\n * @param {HTMLElement} contenedor\n * @param {...(Node|string)} hijos\n */\nexport function reemplazarContenido(contenedor, ...hijos) {\n  vaciar(contenedor);\n\n  for (const hijo of hijos.flat(Infinity)) {\n    if (hijo === null || hijo === undefined || hijo === false) continue;\n\n    if (typeof hijo === 'string' || typeof hijo === 'number') {\n      contenedor.appendChild(document.createTextNode(String(hijo)));\n    } else {\n      contenedor.appendChild(hijo);\n    }\n  }\n}\n\n/**\n * Crea una funcion \"con retardo\" (debounce).\n *\n * COMO FUNCIONA\n * Cada vez que se llama a la funcion devuelta, CANCELA el temporizador\n * anterior y arranca uno nuevo. Solo cuando pasan `retardo`\n * milisegundos sin nuevas llamadas, se ejecuta de verdad.\n *\n * Caso de uso tipico: el campo de busqueda. El usuario escribe\n * \"hopper\" (6 pulsaciones) y en lugar de 6 peticiones a la API se\n * envia UNA, cuando deja de teclear.\n *\n * @param {function} funcion\n * @param {number} retardo  Milisegundos de espera.\n * @returns {function}\n */\nexport function conRetardo(funcion, retardo = 400) {\n  // `temporizador` vive en el closure: persiste entre llamadas sin\n  // ser una variable global.\n  let temporizador = null;\n\n  return function (...argumentos) {\n    // Cancelamos la ejecucion pendiente, si habia alguna.\n    clearTimeout(temporizador);\n\n    temporizador = setTimeout(() => {\n      funcion.apply(this, argumentos);\n    }, retardo);\n  };\n}\n\n/**\n * Crea un icono SVG a partir del contenido de su trazado.\n *\n * Centralizamos los iconos para no repetir el marcado del SVG\n * en cada componente. Ver utiles/iconos.js para el catalogo.\n *\n * @param {string} trazado  El interior del <svg> (paths, circles...).\n * @param {string} clase    Clases CSS del icono.\n * @returns {SVGElement}\n */\nexport function crearIcono(trazado, clase = 'a-icono') {\n  // Los elementos SVG necesitan createElementNS con su namespace.\n  // Si se usa createElement('svg'), el navegador crea un elemento\n  // HTML desconocido y el icono NO se dibuja. Es un error muy comun.\n  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n\n  svg.setAttribute('viewBox', '0 0 24 24');\n  svg.setAttribute('class', clase);\n\n  // Los iconos son decorativos: el lector de pantalla los ignora y\n  // lee el texto o el aria-label del boton que los contiene.\n  svg.setAttribute('aria-hidden', 'true');\n\n  // Aqui innerHTML es seguro: el trazado es una constante nuestra,\n  // nunca un dato que venga del usuario o de la API.\n  svg.innerHTML = trazado;\n\n  return svg;\n}\n"};
